import{n as e}from"./characters-BfDKikMt.js";import{_ as t,a as n,c as r,d as i,f as a,h as o,i as s,l as c,m as l,n as u,p as d,r as ee,s as f,t as p,u as te}from"./archiveDossiers-z2Pbd4k6.js";import"./genealogies-DWQ-XZNZ.js";import"./dynasties-BzmccjQU.js";import"./succession-DWiEPd7h.js";var m={"grande-guerra":{beginning:`Ano 0, contado a partir da morte de Edric Averen.`,startingEvent:`Morte sem sucessor declarado e divisão imediata das Doze Legiões.`,politicalContext:`A Coroa Una concentrava estradas, celeiros e comando militar, mas não possuía regra sucessória capaz de sobreviver à ausência do soberano.`,peoplesSituation:`Populações humanas foram recrutadas e deslocadas; povos antigos permaneceram fora da maior parte das crônicas humanas, embora sofressem com rotas e migrações.`,magicSituation:`A magia verdadeira existia, mas as três linhagens ainda não ocupavam posição pública reconhecida nos Estados humanos.`,rulers:[`Edric Averen até o ano 0`,`Aldren, Kaelor e Theron como pretendentes`,`Governadores regionais progressivamente autônomos`],discoveries:[`Novas rotas militares, depois convertidas em estradas`,`Técnicas de armazenamento sob cerco`],migrations:[`Fuga de áreas centrais para vales, costas e montanhas`,`Formação de comunidades militares permanentes`],crises:[`Fome`,`Fragmentação das legiões`,`Perda de legitimidade`],religiousChanges:[`Ritos funerários regionais substituíram cerimônias da Coroa`,`Virtudes dos Sete Nomes foram usadas por todos os lados`],culturalChanges:[`Surgimento de dialetos políticos e calendários locais`,`Baladas dos três estandartes`],naturalEvents:[`Secas e invernos agravaram campanhas; nenhum desastre sobrenatural é confirmado`],historicalFigures:[`Edric Averen`,`Aldren Averen`,`Kaelor Averen`,`Theron Averen`,`Marcellus Veyron`],endingEvent:`Marcellus Veyron incorpora legiões exaustas e encerra as principais frentes no ano 100.`,transition:`A exaustão permitiu reunificação rápida, mas concedeu a Veyron força sem instituições capazes de limitá-lo, originando a Era da Queda da Coroa.`,detailedTimeline:[{date:`Ano 0`,title:`Cisma sucessório`,description:`Três herdeiros e doze legiões rompem a unidade.`},{date:`Anos 1–63`,title:`Campanhas e regionalização`,description:`A guerra transforma governadores em poderes locais.`},{date:`Anos 64–91`,title:`Exaustão`,description:`Fome e fragmentação removem capacidade de vitória Averen.`},{date:`Anos 92–100`,title:`Reunificação Veyron`,description:`Marcellus vence territórios incapazes de sustentar nova campanha.`}]},"queda-coroa":{beginning:`Ano 101, após a reunificação militar de Marcellus Veyron.`,startingEvent:`Veyron assume a Coroa reunificada e promete restaurar estradas e colheitas.`,politicalContext:`O continente desejava estabilidade, mas os mecanismos regionais criados pela guerra foram subordinados a impostos e vigilância central.`,peoplesSituation:`Humanos enfrentaram reconstrução e confisco; povos antigos limitaram contato diante do avanço militar.`,magicSituation:`Linhagens bruxas aparecem apenas em registros dispersos e ainda não são política continental pública.`,rulers:[`Marcellus Veyron`,`Governadores militares subordinados`,`Conselho dos doze comandantes no fim do regime`],discoveries:[`Reconstrução padronizada de estradas`,`Novas técnicas fiscais e censitárias`],migrations:[`Retorno parcial a cidades`,`Fuga de devedores e desertores para fronteiras`],crises:[`Fome dos Sete Invernos`,`Confisco de sementes`,`Vigilância e trabalho compulsório`],religiousChanges:[`A Coroa tentou associar-se à justiça de Edria`,`Templos comunitários ampliaram cozinhas de abrigo`],culturalChanges:[`Memória da reunificação dividiu-se entre alívio e tirania`,`Adagas tornaram-se símbolo de limite ao soberano`],naturalEvents:[`Sete invernos de colheita ruim, sem causa sobrenatural comprovada`],historicalFigures:[`Marcellus Veyron`,`Os doze comandantes não identificados de forma segura`],endingEvent:`Noite das Doze Adagas, morte de Veyron em 158 d.C.`,transition:`O regicídio libertou governadores e encerrou a possibilidade imediata de nova Coroa Una. Reinos independentes buscaram rotas e conhecimento além das fronteiras, abrindo a Era da Magia.`,detailedTimeline:[{date:`101 d.C.`,title:`Coroação de Veyron`,description:`Começa a reconstrução centralizada.`},{date:`Décadas seguintes`,title:`Tributos e vigilância`,description:`O custo do regime cresce sobre regiões exaustas.`},{date:`Sete invernos`,title:`Fome e confisco`,description:`Sementes e estoques tornam-se instrumentos de controle.`},{date:`158 d.C.`,title:`Doze Adagas`,description:`Comandantes matam Veyron e o continente se fragmenta definitivamente.`}]},"era-magia":{beginning:`Ano 159, quando reinos recém-independentes iniciaram expedições e tratados além das antigas fronteiras.`,startingEvent:`Primeiros contatos diplomáticos registrados com Sylvaris e abertura dos Portões de Kar-Dûm.`,politicalContext:`Winterfeld, Valoria, Ravenhold e Eldemar procuravam recursos e legitimidade sem uma autoridade continental.`,peoplesSituation:`Elfos, anões, orcs e gigantes passaram a aparecer em arquivos humanos, embora já possuíssem histórias próprias.`,magicSituation:`Kayler, Nimbus e Rivs tornaram pública a magia hereditária. O dom não podia ser ensinado e o Juramento Arcano negava direito de governo.`,rulers:[`Primeiras dinastias regionais`,`Guardadores de Sylvaris`,`Conselho dos Nove Salões`],discoveries:[`Registro público das Três Linhagens`,`Cartografia subterrânea e florestal compartilhada`,`Distinção gradual entre runa, religião e magia de sangue`],migrations:[`Mercadores humanos para Porto Verde e portões de Kar-Dûm`,`Comunidades de fronteira formadas por mais de um povo`],crises:[`Tratados que chamavam presença antiga de “descoberta”`,`Tentativas de comprar serviço mágico exclusivo`],religiousChanges:[`Tradições não humanas foram traduzidas, muitas vezes de forma incorreta`,`Doutrina das Três Correntes tornou-se pública`],culturalChanges:[`Novos alfabetos comerciais`,`Empréstimos linguísticos`,`Debate sobre o significado de humanidade e povo antigo`],naturalEvents:[`Rotas e criaturas raras foram documentadas; nenhum aumento de dragões é confirmado`],historicalFigures:[`Primeiros diplomatas dos Círculos`,`Mestres dos Nove Salões`,`Ancestrais públicos das Casas bruxas`],endingEvent:`No ano 310, as relações deixaram de ser expedições ocasionais e tornaram-se alianças, mercados e disputas permanentes.`,transition:`A integração econômica e a visibilidade dos bruxos permitiram que coroas competissem por apoio exclusivo, dando origem à Era das Coroas.`,detailedTimeline:[{date:`159 d.C.`,title:`Abertura política`,description:`Reinos independentes buscam tratados.`},{date:`Séculos II–III`,title:`Portões e margens`,description:`Sylvaris e Kar-Dûm regulam contato.`},{date:`Fim do século III`,title:`Três Linhagens`,description:`Kayler, Nimbus e Rivs são reconhecidas publicamente.`},{date:`310 d.C.`,title:`Mundo interligado`,description:`Alianças e dependências substituem o ciclo de expedições.`}]},"era-coroas":{beginning:`Ano 311, marcado pela consolidação das dinastias e de tratados comerciais entre povos.`,startingEvent:`Coroas transformam relações com as três Casas em política de Estado.`,politicalContext:`Reinos estáveis competiam por rotas, metais, alimento e prestígio, enquanto conselhos locais tentavam limitar monarcas.`,peoplesSituation:`Povos antigos negociavam com maior frequência; clãs orcs eram contratados por lados distintos e depois descritos falsamente como unidade.`,magicSituation:`As três Casas alcançaram máxima visibilidade. Normus dominou as tempestades sem aceitar soberania.`,rulers:[`Dinastias regionais de Winterfeld, Valoria, Ravenhold e Eldemar`,`Rainha Aelwen em Sylvaris`,`Conselho dos Nove Salões`],discoveries:[`Aprimoramento de artefatos condutores`,`Protocolos de metal e runa`,`Novas rotas continentais`],migrations:[`Crescimento de cidades`,`Mercenários e artesãos deslocados pelas guerras`],crises:[`Guerra dos Tronos`,`Túneis Vazios`,`Invasões e bloqueios de alimento`],religiousChanges:[`Coroas tentaram apropriar virtudes e lendas`,`Juramento Arcano ganhou relevância política`],culturalChanges:[`Formação de identidades nacionais`,`Prestígio de cavaleiros e Casas`,`Culpa coletiva contra orcs`],naturalEvents:[`Vyrasul passou a permanecer nas geleiras de Winterfeld, sem tornar-se súdito`],historicalFigures:[`Normus Kayler`,`Rainha Aelwen`,`Líderes das três Casas`],endingEvent:`Em 612 d.C., a Guerra dos Tronos termina sem uma coroa controlar os bruxos; reis passam da competição ao projeto de eliminação.`,transition:`O medo produzido pela independência de Normus e pelas Casas permitiu o Conselho dos Sete Reis e abriu a Caça às Bruxas.`,detailedTimeline:[{date:`311 d.C.`,title:`Consolidação das coroas`,description:`Dinastias e tratados tornam-se instituições permanentes.`},{date:`487–491 d.C.`,title:`Túneis Vazios`,description:`Kar-Dûm limita expansão após desastre.`},{date:`552 d.C.`,title:`Águas Negras`,description:`Eldemar vence e contrai dívida civil.`},{date:`566–612 d.C.`,title:`Guerra dos Tronos`,description:`Coroas disputam as Três Correntes.`},{date:`612 d.C.`,title:`Juramento de Normus`,description:`A independência bruxa é reafirmada e passa a ser tratada como ameaça.`}]},"caca-bruxas":{beginning:`Ano 613, quando negociações secretas entre coroas passaram a preparar registro e captura das linhagens.`,startingEvent:`Formação do Conselho dos Sete Reis, seguida pelo Edito da Cinza Branca em 628 d.C.`,politicalContext:`Governantes usaram medo, crise econômica e memória da Guerra dos Tronos para justificar política de sangue.`,peoplesSituation:`Comunidades humanas dividiram-se entre perseguição, silêncio e abrigo; Sylvaris, Montanhas Cinzentas e redes civis protegeram fugitivos de maneiras diferentes.`,magicSituation:`Magia verdadeira tornou-se crime ou propriedade reivindicada. Nimbus resistiu, Rivs evacuou arquivos e Kayler desapareceu dos registros.`,rulers:[`Conselho dos Sete Reis — composição integral contestada`,`Rainha Aelwen`,`Mesas de Vigias das Montanhas`],discoveries:[`Cifras de refúgio`,`Técnicas de apagamento e falsificação de genealogias`,`Nenhuma nova linhagem mágica`],migrations:[`Fuga para Montanhas Cinzentas e Sylvaris`,`Crianças separadas ou renomeadas`,`Desaparecimento coordenado Rivs`],crises:[`Guerra da Cinza Branca`,`Cerco da Fortaleza do Véu`,`Destruição pública das Casas`],religiousChanges:[`Propaganda associou sangue arcano a impureza`,`Chama sem Coroa e Brasa Comum ampliaram redes de abrigo`],culturalChanges:[`Medo de traços Kayler`,`Arquivos incompletos`,`Silêncio familiar sobre ascendência`],naturalEvents:[`Tempestades da batalha final foram registradas, mas relatos ampliam sua escala`],historicalFigures:[`Normus Kayler`,`Namídia Bellatrix`,`Rainha Aelwen`,`Sirius Kayler`],endingEvent:`Em 704 d.C., Namídia morre, Normus trava sua batalha final e Sirius é ocultado; as coroas declaram as Casas encerradas.`,transition:`Não há sexta era oficial nomeada. Os cinco séculos seguintes constituem o período pós-Caça, construído sobre apagamento, falsa segurança e a sobrevivência secreta de Sirius até 1204.`,detailedTimeline:[{date:`613–627 d.C.`,title:`Preparação política`,description:`Reis compartilham censos, medos e projetos de controle.`},{date:`628 d.C.`,title:`Edito da Cinza Branca`,description:`A perseguição torna-se política continental.`},{date:`Século VII`,title:`Resistência e evacuação`,description:`Nimbus combate, Rivs desaparece e redes civis escondem pessoas.`},{date:`704 d.C.`,title:`Último ano`,description:`Sirius nasce; Namídia e Normus morrem protegendo sua sobrevivência.`},{date:`704–1204 d.C.`,title:`Consequência prolongada`,description:`Coroas tratam as Casas como extintas enquanto o herdeiro Kayler permanece isolado.`}]}},ne=[e({id:`grande-guerra`,name:`I — A Grande Guerra`,subtitle:`A ruptura do reino indiviso`,summary:`A disputa entre os três herdeiros de Edric Averen dividiu as Doze Legiões e converteu uma sucessão em cem anos de guerra.`,description:`Quando Edric Averen morreu sem declarar um sucessor, seus filhos exigiram a Coroa Una com argumentos igualmente frágeis. As legiões escolheram senhores, celeiros viraram fortalezas e antigas estradas foram quebradas para deter exércitos. O conflito encerrou a ideia de um Avernor governado por uma só vontade e deixou fronteiras que ainda orientam impostos, dialetos e ressentimentos.`,causes:[`Morte de Edric Averen sem sucessor declarado`,`Pretensões incompatíveis de Aldren, Kaelor e Theron`,`Divisão das Doze Legiões e dos celeiros reais`],phases:[`Primeiro cisma das legiões`,`Campanhas dos três estandartes`,`Guerra de desgaste regional`,`Ascensão reunificadora de Marcellus Veyron`],consequences:[`Milhões de mortos ao longo de cerca de um século`,`Destruição da legitimidade da Coroa Una`,`Marcellus Veyron reúne os territórios exauridos`],category:`Era histórica`,status:`Encerrada`,period:`Ano 0–100`,events:[`Cisma das Doze Legiões`,`Cerco dos Três Estandartes`,`Tratado das Cinzas`],curiosities:[`O ano zero marca a morte de Edric, não a fundação do continente.`,`Quatro estradas reais atuais seguem rotas militares abertas durante a guerra.`],quotes:[`Toda coroa nasce de uma escolha — e toda escolha cobra sangue.`],relations:[{label:`Guerra dos Três Herdeiros`,to:`/guerras/guerra-dos-tres-herdeiros`}]}),e({id:`queda-coroa`,name:`II — A Queda da Coroa`,subtitle:`Reunificação, fome e regicídio`,summary:`Marcellus Veyron reunificou o reino pela força, mas sua tirania culminou na Noite das Doze Adagas e numa fragmentação definitiva.`,description:`Marcellus Veyron venceu o que restava das legiões e prometeu restaurar estradas e colheitas. A reconstrução veio acompanhada de tributos impossíveis, vigilância e confisco de sementes. Na capital, doze comandantes que sustentavam o regime o mataram na Noite das Doze Adagas. A morte do soberano soltou governadores militares e consolidou Winterfeld, Valoria, Ravenhold e Eldemar como estados humanos independentes.`,causes:[`Centralização pela conquista`,`Tributos impossíveis`,`Fome, vigilância e confisco de sementes`],consequences:[`Morte de Veyron por doze comandantes`,`Formação política dos quatro reinos humanos`,`Desaparecimento das doze armas e disputa pela memória do regicídio`],category:`Era histórica`,status:`Encerrada`,period:`Ano 101–158`,events:[`Marcha de Veyron`,`Fome dos Sete Invernos`,`Noite das Doze Adagas`],curiosities:[`Nenhuma das doze adagas foi encontrada.`,`Valoria conserva os maiores arquivos fiscais do período.`],quotes:[`Os impérios raramente caem de fora. Primeiro apodrecem por dentro.`],relations:[{label:`Noite das Doze Adagas`,to:`/lendas/noite-das-doze-adagas`}]}),e({id:`era-magia`,name:`III — A Era da Magia`,subtitle:`O mundo antigo se deixa perceber`,summary:`Expedições registraram povos antigos, criaturas raras e as três linhagens hereditárias de bruxos: Kayler, Nimbus e Rivs.`,description:`A abertura de rotas além das antigas fronteiras humanas revelou que Avernor nunca estivera vazio. Elfos de Sylvaris, anões de Kar-Dûm e comunidades das terras selvagens já possuíam calendários e memórias próprias. Nesse período, as Casas Kayler, Nimbus e Rivs tornaram pública a existência da magia verdadeira — um dom de sangue que não pode ser ensinado a quem não nasceu nessas linhagens.`,consequences:[`Primeiros tratados estáveis com povos antigos`,`Centralidade política de Kayler, Nimbus e Rivs`,`Formulação pública do Juramento Arcano`],category:`Era histórica`,status:`Encerrada`,period:`Ano 159–310`,events:[`Primeiro Concílio de Lethariel`,`Abertura dos Portões de Kar-Dûm`,`Registro das Três Linhagens`],curiosities:[`O termo “descoberta da magia” é rejeitado pelos cronistas élficos.`,`Os primeiros tratados confundiam feitiçaria hereditária com práticas religiosas.`],quotes:[`A magia não foi descoberta. Ela apenas permitiu que o mundo a percebesse.`],relations:[{label:`Casa Kayler`,to:`/casas/kayler`},{label:`Casa Nimbus`,to:`/casas/nimbus`},{label:`Casa Rivs`,to:`/casas/rivs`}]}),e({id:`era-coroas`,name:`IV — A Era das Coroas`,subtitle:`Alianças, fronteiras e o auge de Normus`,summary:`Reinos consolidaram suas identidades e disputaram a lealdade dos bruxos. Normus Kayler tornou-se a maior força arcana conhecida.`,description:`A estabilidade das novas coroas trouxe prosperidade desigual e a Guerra dos Tronos. Reis competiram pelo apoio das três Casas. Normus recusou servir a um soberano, defendeu Kar-Dûm e depois Sylvaris contra invasões orcs, recebendo o título de Cavaleiro de Honra — o único não elfo a conquistá-lo. Nesse período o dragão branco Vyrasul passou a ser associado a Winterfeld sem pertencer à coroa.`,phases:[`Guerra dos Tronos`,`Defesa de Kar-Dûm`,`Invasões orcs contra Sylvaris`,`Nomeação de Normus como Cavaleiro de Honra`],consequences:[`Prestígio continental de Normus`,`Medo crescente das coroas diante dos bruxos`,`Associação cultural entre Vyrasul e Winterfeld`],category:`Era histórica`,status:`Encerrada`,period:`Ano 311–612`,events:[`Pacto das Sete Pontes`,`Defesa de Sylvaris`,`Juramento de Normus`],curiosities:[`O título de Normus não o colocou na linha sucessória élfica.`,`A amizade entre Normus e a Rainha de Sylvaris foi política e pessoal, jamais amorosa.`],quotes:[`Quando reis cobiçam a mesma força, a paz se torna apenas o intervalo entre duas batalhas.`],relations:[{label:`Normus Kayler`,to:`/personagens/normus-kayler`},{label:`Rainha Aelwen`,to:`/personagens/rainha-aelwen`}]}),e({id:`caca-bruxas`,name:`V — A Caça às Bruxas`,subtitle:`O medo transforma protetores em presas`,summary:`Reis e inquisidores perseguiram Nimbus, Rivs e Kayler até quase apagarem as três linhagens. Sirius nasceu no fim dessa era.`,description:`Sete reis reunidos em conselho decidiram controlar ou eliminar as três Casas. Os Nimbus foram destruídos lutando; os Rivs esconderam bibliotecas e desapareceram. Normus firmou com a Rainha de Sylvaris um pacto de proteção aos descendentes, partiu, conheceu Namídia na fortaleza rebelde das Montanhas Cinzentas e viveu com ela perto da Floresta Antiga e do mar. Sirius nasceu ali. Namídia morreu protegendo o filho; Normus travou sua batalha final e os Kayler foram dados como extintos.`,causes:[`Conselho dos Sete Reis`,`Medo de que um bruxo decidisse guerras`,`Planos de registro, controle e tomada de crianças`],phases:[`Resistência final dos Nimbus`,`Evacuação das bibliotecas Rivs`,`Pacto entre Normus e Sylvaris`,`Vida de Normus e Namídia junto à Floresta Antiga`,`Nascimento de Sirius e batalha final`],consequences:[`Nimbus considerados destruídos`,`Rivs desaparecidos com parte do conhecimento`,`Kayler considerados extintos`,`Sirius preservado como último bruxo conhecido`],category:`Era histórica`,status:`Encerrada`,period:`Ano 613–704`,events:[`Edito da Cinza Branca`,`Cerco da Fortaleza do Véu`,`Nascimento de Sirius Kayler`],curiosities:[`Muitos registros da perseguição foram deliberadamente alterados.`,`Sirius é considerado o último bruxo conhecido, não necessariamente o último sobrevivente possível.`],quotes:[`O mundo chamou de monstros aqueles que antes chamava de heróis.`],relations:[{label:`Guerra da Cinza Branca`,to:`/guerras/guerra-da-cinza-branca`},{label:`Sirius Kayler`,to:`/personagens/sirius-kayler`},{label:`Casa Kayler`,to:`/casas/kayler`},{label:`Casa Nimbus`,to:`/casas/nimbus`},{label:`Casa Rivs`,to:`/casas/rivs`}]})].map(e=>({...e,...m[e.id]})),h=(e,t,n)=>({title:e,period:t,body:n}),g={winterfeld:{population:`Censo público incompleto; maior concentração em Winterheim e nos vales termais.`,foundation:`Consolidado após a Queda da Coroa por jarls que controlavam vales termais e passagens do norte; o ano exato permanece contestado entre três calendários locais.`,climate:`Subártico, com degelos curtos, ventos de altitude e quarenta noites de frio crítico.`,geography:`Vales termais cercados por geleiras, minas profundas e passos sujeitos a avalanche.`,succession:`A Casa do Lobo apresenta o candidato, mas o Conselho dos Jarls precisa confirmar capacidade de manter abrigo, estoque e passagem.`,religion:`Vigília da Última Brasa, coexistindo com cantos territoriais dos gigantes.`,architecture:`Pedra negra, telhados inclinados, canais de água quente e muralhas que incluem depósitos públicos.`,culture:`Hospitalidade de inverno é obrigação jurídica; coragem sem preparo é tratada como desperdício.`,customs:[`Auditoria pública dos celeiros antes das quarenta noites`,`Troca de mantos entre anfitrião e hóspede como garantia de abrigo`],festivals:[`Abertura do Degelo`,`Noite da Última Brasa`],cuisine:[`Carne curada`,`Pães densos de raiz`,`Caldo mineral preparado nas fontes termais`],alliesPolitical:[`Comunidades de gigantes dos passos`,`Kar-Dûm em acordos de metal e sal`],rivalsPolitical:[`Jarls que disputam pedágios entre si`,`Mercadores que tentam privatizar depósitos`],importantCharacters:[`Runa de Winterfeld`,`Conselho dos Jarls`],relevantPlaces:[`Winterheim`,`Geleiras de Vyrasul`],currentSituation:`Runa é a única herdeira pública, mas dois jarls exigem nova Prova do Abrigo. Degelos irregulares pressionam reservas e rotas.`,rumors:[`Alguns cantos gigantes descrevem um tratado anterior à própria Casa do Lobo`,`Vyrasul teria abandonado uma geleira por causa de caçadores ainda ativos`],narrativeImportance:`Controla o acesso ao norte, o pacto com os gigantes e a região do único dragão branco conhecido, sem possuir qualquer autoridade sobre ele.`,biographyTitle:`História do reino`,biography:[h(`Vales antes da coroa`,`Antes da Queda`,`Comunidades termais, mineiros e gigantes mantinham tratados locais muito antes de uma monarquia estável. A fragmentação da Coroa Una tornou indispensável coordenar passagens e depósitos.`),h(`A Casa do Lobo`,`Após 158 d.C.`,`Os jarls reconheceram uma casa real sob condição de que abrigo permanecesse dever público. A cláusula explica por que a sucessão nunca é automática.`),h(`O reino atual`,`1204 d.C.`,`Winterfeld enfrenta degelos imprevisíveis, tensão sucessória e tentativas religiosas de apropriar Vyrasul. O futuro do reino depende mais de logística climática que de expansão.`)]},sylvaris:{population:`Não publicada em total único; Lethariel registra cerca de 22 mil habitantes e os bosques usam contagens sazonais.`,foundation:`Não possui ato único de fundação. Comunidades da Floresta Antiga reconheceram gradualmente os Círculos da Memória e uma guardadora comum.`,climate:`Úmido e temperado, com microclimas definidos por rios, copas e clareiras manejadas.`,geography:`Floresta antiga, rios sinuosos, plataformas elevadas e uma costa aberta apenas por Porto Verde.`,succession:`Os Círculos escolhem entre descendentes elegíveis; idade e gênero não criam preferência automática. Elara é a primeira designada.`,religion:`Caminho das Raízes e Memória da Primeira Raiz.`,architecture:`Estruturas suspensas, encaixes removíveis, vidro vegetal e fundações que evitam raízes ativas.`,culture:`Memória é inseparável do lugar. Leis, luto e manejo territorial são revisados por estação.`,customs:[`Jardins memoriais no lugar de túmulos fechados`,`Consentimento dos Círculos antes de alterar cursos de água`],festivals:[`Vigília da Copa Silenciosa`,`Retorno das Folhas de Prata`],cuisine:[`Frutos sazonais`,`Pães de sementes`,`Cogumelos cultivados em madeira caída`],alliesPolitical:[`Porto Verde`,`Antiga aliança pessoal com Normus Kayler`],rivalsPolitical:[`Cortes que exigem madeira viva`,`Ala isolacionista interna`],importantCharacters:[`Rainha Aelwen`,`Elara`,`Lyssara`,`Maeriel`],relevantPlaces:[`Lethariel`,`Porto Verde`,`Floresta Antiga`],currentSituation:`A chegada de Sirius ameaça tornar público o pacto Kayler no momento em que Elara ainda consolida sua legitimidade.`,rumors:[`Caminhos antigos teriam sido fechados para ocultar refugiados`,`Parte do conselho deseja entregar o medalhão a outra princesa`],narrativeImportance:`É o ponto onde memória Kayler, sucessão de Elara e futuro da Floresta Antiga se encontram.`,biographyTitle:`História do reino`,biography:[h(`Comunidades da Primeira Raiz`,`Antes dos calendários humanos`,`Bosques e cidades-jardim compartilhavam memória ritual sem uma capital única. A figura real surgiu como guardadora de acordos, não proprietária territorial.`),h(`Abertura e limites`,`Era da Magia`,`Sylvaris firmou tratados com humanos e Kar-Dûm, restringindo circulação a rotas capazes de suportar comércio sem desmatamento.`),h(`Normus e a perseguição`,`Era das Coroas e Caça às Bruxas`,`A defesa conjunta criou amizade entre Normus e Aelwen. Mais tarde, o reino protegeu nomes e caminhos, mas evitou guerra aberta que poderia destruir a floresta.`),h(`Sucessão presente`,`1204 d.C.`,`Elara foi escolhida pelos Círculos, enquanto o pacto e a volta de Sirius obrigam o reino a discutir quanto segredo ainda é proteção.`)]},"kar-dum":{population:`Censo por salão, não consolidado; Thur-Kar registra cerca de 61 mil habitantes.`,foundation:`União progressiva de nove redes subterrâneas em torno de água, ventilação e defesa; não há fundador único reconhecido.`,climate:`Temperatura subterrânea estável, com zonas quentes próximas às forjas e galerias frias junto aos aquíferos.`,geography:`Cordilheira central perfurada por salões, poços, rios subterrâneos e túneis lacrados.`,succession:`Cada salão combina sangue, ofício ou eleição conforme sua função; o Conselho dos Nove não possui herdeiro único.`,religion:`Os Nove Ecos e o mito dos Sete Golpes.`,architecture:`Arcos de compressão, pontes de pedra, canais de ventilação e placas que registram toda intervenção.`,culture:`Qualidade material é dever moral. Falhas devem ser registradas com o mesmo cuidado que obras bem-sucedidas.`,customs:[`Nomear ferramentas herdadas`,`Ler em público a razão de cada túnel fechado`],festivals:[`Batida dos Sete Metais`,`Festival controverso do Oitavo Golpe`],cuisine:[`Pães de fungo`,`Peixes de caverna`,`Queijos trocados com vales da superfície`],alliesPolitical:[`Valoria, apesar da dependência alimentar`,`Winterfeld em engenharia de minas`],rivalsPolitical:[`Salões que competem por veios`,`Seladores que desejam controlar o Véu`],importantCharacters:[`Conselho dos Nove Salões`,`Brunna Dhorin`,`Keld Brunna`],relevantPlaces:[`Thur-Kar`,`Túneis Vazios`],currentSituation:`O reino debate inovação, segurança e a pressão dos Seladores por acesso a lacres antigos.`,rumors:[`Um décimo salão teria sido apagado depois de romper uma Fratura`,`O Martelo de Orun perdeu uma fração de massa nunca explicada`],narrativeImportance:`Guarda conhecimento material capaz de reparar ou agravar Fraturas e conserva a origem técnica de Fulgarion.`,biographyTitle:`História da confederação`,biography:[h(`Nove necessidades`,`Período anterior à abertura`,`Salões independentes perceberam que nenhuma mina sobrevivia sem compartilhar ar, água e rotas. A confederação surgiu de dependência material.`),h(`Abertura dos Portões`,`Era da Magia`,`O contato ampliou comércio e risco. Kar-Dûm registrou tratados em ardósia e recusou a ideia humana de um rei anão único.`),h(`Túneis Vazios`,`487–491 d.C.`,`A competição rompeu lacres, obrigou evacuações e produziu o Código das Profundezas.`),h(`Presente`,`1204 d.C.`,`A disputa agora envolve Fraturas e a possibilidade de que antigos lacres sejam estruturas do Véu, não simples obras de mineração.`)]},valoria:{population:`Maior população rural dos reinos centrais; total varia com colheitas e não possui censo recente confiável.`,foundation:`Formou-se quando as planícies e canais deixaram de obedecer aos governadores da antiga Coroa e reconheceram pactos de celeiro.`,climate:`Temperado, com cheias sazonais e verões secos que exigem irrigação.`,geography:`Planícies férteis, rios navegáveis, diques e sete pontes politicamente autônomas.`,succession:`A Casa Arden precisa da confirmação das Sete Pontes e da quitação de dívidas agrárias. Roderic governa; Ilyra é herdeira.`,religion:`Fé dos Sete Nomes, Culto da Coroa Dourada e Brasa Comum.`,architecture:`Celeiros de tijolo, casas de pátio, pontes fortificadas e canais que também funcionam como vias.`,culture:`Pesos públicos e crédito determinam prestígio; festas agrícolas convivem com disputas entre campo e corte.`,customs:[`Pesagem pública da primeira colheita`,`Mutirão obrigatório quando um dique ameaça comunidades vizinhas`],festivals:[`Abertura dos Canais`,`Mesa do Primeiro Pão`],cuisine:[`Pães claros`,`Ensopados de cevada`,`Peixes de rio e frutas conservadas`],alliesPolitical:[`Eldemar no comércio fluvial`,`Kar-Dûm no fornecimento de alimentos`],rivalsPolitical:[`Ala expansionista da própria corte`,`Credores que manipulam escassez`],importantCharacters:[`Roderic Arden`,`Ilyra Arden`],relevantPlaces:[`Valóris`,`Campos Baixos`,`Sete Pontes`],currentSituation:`A popularidade de Ilyra, dívidas de dique e pressões por guerra preventiva ameaçam dividir a Casa Arden.`,rumors:[`Armazéns privados ocultam colheitas para elevar preços`,`Uma das Sete Pontes considera negar Roderic antes do fim do mandato`],narrativeImportance:`É o celeiro de Avernor; qualquer crise interna transforma rapidamente política dinástica em fome continental.`,biographyTitle:`História do reino`,biography:[h(`A planície administrada`,`Após a Queda`,`Cidades de ponte e famílias rurais substituíram governadores militares por pactos de irrigação e armazenamento.`),h(`A Casa Arden`,`Era das Coroas`,`Os Arden consolidaram a monarquia aceitando limites de preço e deveres sobre diques.`),h(`Revoltas e reformas`,`Séculos recentes`,`Fomes e greves mostraram que cavalaria não colhe grão. As Sete Pontes ampliaram seu poder de confirmação.`),h(`Crise presente`,`1204 d.C.`,`Ilyra representa continuidade do pacto para os campos e ameaça à ala que deseja transformar excedente agrícola em conquista.`)]},ravenhold:{population:`Censo militar detalhado e censo civil contestado; Ravencastle reúne cerca de 73 mil habitantes.`,foundation:`Consolidado por legiões orientais que conservaram estradas e fortalezas após a queda de Veyron.`,climate:`Continental, com invernos secos e verões quentes nas fronteiras orientais.`,geography:`Planaltos abertos, estradas militares, rios rasos e uma sequência de fortalezas circulares.`,succession:`Sangue Corven, juramento militar e maioria do Senado de Estandartes. Vera governa; Cassor aguarda confirmação.`,religion:`Vigília do Sol Negro e vertentes militares dos Sete Nomes.`,architecture:`Anéis defensivos, pátios de treino, cisternas e bairros que preservam muralhas antigas.`,culture:`Disciplina e serviço público conferem status, mas a reforma pós-perseguição questiona obediência sem consciência.`,customs:[`Leitura anual de ordens recusadas`,`Treino cívico contra incêndio e cerco`],festivals:[`Dia dos Estandartes Baixos`,`Vigília dos Nomes Restituídos`],cuisine:[`Carne defumada`,`Grãos torrados`,`Caldo de marcha`],alliesPolitical:[`Valoria em contratos de cavalaria`,`Facções comerciais das fronteiras`],rivalsPolitical:[`Clãs e cidades de Vul’Gar quando tratados falham`,`Veteranos e aristocratas em conflito interno`],importantCharacters:[`Vera Corven`,`Cassor Corven`,`Kharza Gron`],relevantPlaces:[`Ravencastle`,`Estrada de Cinza`],currentSituation:`Ataques de bandeira falsa e a defesa pública da Caça às Bruxas por Cassor colocam reforma, fronteira e sucessão na mesma crise.`,rumors:[`Arquivos militares ocultam ordens do Edito da Cinza Branca`,`A Corte de Cinza possui aliados no Senado`],narrativeImportance:`Pode impedir ou reiniciar uma guerra oriental e conserva o aparato institucional que executou parte da perseguição.`,biographyTitle:`História do reino`,biography:[h(`As legiões que ficaram`,`Após 158 d.C.`,`Unidades orientais mantiveram estradas e transformaram comando temporário em governo. O Senado nasceu para impedir que um general reunisse poder absoluto.`),h(`Cultura de fronteira`,`Era das Coroas`,`Fortificações e serviço tornaram-se identidade. Contratos com clãs orcs alternaram cooperação e exploração.`),h(`A Cinza Branca`,`628–704 d.C.`,`Legiões executaram o Edito. Registros posteriores revelaram recusas, cumplicidade e falsificação de ordens.`),h(`Reforma incompleta`,`1204 d.C.`,`Veteranos reformistas enfrentam Cassor e provocadores de fronteira. A sucessão decidirá se o reino aprende com os próprios arquivos.`)]},eldemar:{population:`População flutuante de marinheiros; Porto de Eldemar registra cerca de 81 mil residentes permanentes.`,foundation:`Aliança de portos e pilotos que recusaram governadores continentais depois da Noite das Doze Adagas.`,climate:`Marítimo, ventoso e úmido, sujeito a neblinas e tempestades meridionais.`,geography:`Costa recortada, ilhas rochosas, estuários, docas profundas e acesso ao Arquipélago das Brumas.`,succession:`O Conselho das Marés escolhe descendente da Casa da Maré Alta com licença de capitão vigente.`,religion:`Juramento do Horizonte e vertentes portuárias dos Sete Nomes.`,architecture:`Terraços de pedra, pontes móveis, armazéns inundáveis e torres de sinos codificados.`,culture:`Promessas escritas, conhecimento de maré e reputação de tripulação valem mais que nascimento isolado.`,customs:[`Registro de obrigações antes de cada viagem`,`Reparação pública quando uma rota salva o porto ao custo de uma vila`],festivals:[`Noite das Cartas Luminosas`,`Retorno da Primeira Frota`],cuisine:[`Peixe salgado`,`Ensopado de mariscos`,`Pão de algas e cítricos importados`],alliesPolitical:[`Valoria no comércio`,`Sylvaris pelo Tratado da Madeira Caída`],rivalsPolitical:[`Liga das Brumas`,`Contrabandistas tolerados e perseguidos alternadamente`],importantCharacters:[`Selka Elmer`,`Taris Elmer`],relevantPlaces:[`Porto de Eldemar`,`Arquipélago das Brumas`,`Mar das Estrelas`],currentSituation:`Reparações das Águas Negras seguem incompletas e a prova marítima de Taris pode ser manipulada.`,rumors:[`Cartas oficiais omitem rotas de evacuação e esconderijos Rivs`,`Conselheiros financiam contrabandistas que publicamente condenam`],narrativeImportance:`Conecta reinos, outros mundos marítimos e a memória das Casas Rivs; informação circula por Eldemar antes de chegar às coroas.`,biographyTitle:`História do reino`,biography:[h(`Portos sem rei`,`Após a Queda`,`Pilotos e estaleiros substituíram o governador por um conselho capaz de coordenar marés, impostos e resgates.`),h(`Casa da Maré Alta`,`Era das Coroas`,`A monarquia foi aceita sob a condição de que todo herdeiro provasse capacidade de navegação.`),h(`Águas Negras`,`552 d.C.`,`O porto sobreviveu por engodo marítimo que sacrificou vilas. A vitória nunca encerrou a dívida.`),h(`Presente`,`1204 d.C.`,`Com a sucessão em avaliação e as reparações abertas, Eldemar decide se sua habilidade de ocultar rotas serve à proteção ou ao privilégio.`)]},"montanhas-cinzentas":{population:`Não existe censo confederado; Fortaleza do Véu registra cerca de 9 mil habitantes e refugiados variáveis.`,foundation:`Não fundada por decreto. Fortalezas de desertores, exilados e mineiros passaram a cooperar em sucessivas crises.`,climate:`Frio, seco e variável, com vales de pouca luz e quedas-d’água sazonais.`,geography:`Picos cinzentos, cavernas, passagens estreitas e redutos independentes sem centro permanente.`,succession:`Não hereditária no território. Cada fortaleza define seus guardiões; a Mesa de Vigias dissolve-se quando a crise termina.`,religion:`Chama sem Coroa, Brasa Comum e crenças trazidas por exilados.`,architecture:`Fortalezas escavadas, depósitos dispersos, cisternas ocultas e rotas de evacuação cifradas.`,culture:`Cidadania por serviço e desconfiança de títulos permanentes. Abrigo pode superar tratado externo.`,customs:[`Quebrar simbolicamente uma coroa antes de assumir dever de vigia`,`Registrar refugiados por cifras, nunca por listas completas`],festivals:[`Noite das Portas Abertas`,`Mesa dos Ausentes`],cuisine:[`Queijo de cabra`,`Cogumelos de caverna`,`Pães de cevada escura`],alliesPolitical:[`Redes civis de Valoria e Sylvaris`,`Fortalezas signatárias da Mesa`],rivalsPolitical:[`Coroas que exigem extradição`,`Redutos que cobram pedágios abusivos`],importantCharacters:[`Namídia Bellatrix`,`Marek Bellatrix`],relevantPlaces:[`Fortaleza do Véu`,`Rotas Bellatrix`],currentSituation:`A memória de Namídia une a região, mas arquivos cifrados atraem facções e ameaçam a autonomia entre fortalezas.`,rumors:[`Algumas rotas da Caça às Bruxas ainda são usadas`,`Descendentes de refugiados ocupam cargos sem conhecer os nomes protegidos`],narrativeImportance:`É o arquivo material da resistência sem coroa e o lugar onde os legados Kayler e Bellatrix se uniram.`,biographyTitle:`História do território`,biography:[h(`Redutos de quem recusou`,`Depois da Queda`,`Desertores e famílias expulsas ocuparam fortalezas que nenhuma coroa conseguia sustentar.`),h(`Confederação temporária`,`Era das Coroas`,`Crises ensinaram os redutos a eleger uma Mesa sem permitir que ela se tornasse governo permanente.`),h(`Caça às Bruxas`,`628–704 d.C.`,`A região abrigou perseguidos e suportou o Cerco da Fortaleza do Véu. Namídia reorganizou depósitos e cifras.`),h(`Presente`,`1204 d.C.`,`As fortalezas precisam cooperar contra facções interessadas nos arquivos sem recriar a autoridade que historicamente rejeitam.`)]}},_={winterheim:{foundation:`Erguida sobre fontes termais antes da consolidação da Casa do Lobo; os primeiros terraços são mais antigos que a muralha.`,climate:`Frio extremo, neve persistente e vapor das fontes.`,geography:`Terraços de pedra entre uma encosta e canais termais.`,government:`Conselho urbano subordinado à coroa e fiscalizado pelos jarls durante o inverno.`,religion:`Vigília da Última Brasa.`,architecture:`Pedra negra, telhados agudos, túneis aquecidos e depósitos integrados às muralhas.`,culture:`Preparação para o inverno organiza calendário, trabalho e prestígio.`,customs:[`Toda oficina cede calor à enfermaria mais próxima`,`Portões fechados não anulam túneis de socorro`],festivals:[`Fecho das Quarenta Noites`,`Primeiro Degelo`],cuisine:[`Caldo de raiz e carne curada`,`Pães aquecidos sobre canais`],military:[`Guarda dos portões`,`Guias dos túneis de socorro`],internalConflicts:[`Acesso desigual às fontes`,`Pressão de jarls sobre os depósitos`],importantCharacters:[`Runa de Winterfeld`],relevantPlaces:[`Salão dos Jarls`,`Canais Termais`],currentSituation:`Estoque suficiente, mas canais antigos exigem reparo antes do próximo inverno.`,rumors:[`Um túnel de socorro alcança território gigante sem constar nos mapas`],narrativeImportance:`É o teste concreto da legitimidade de qualquer governante de Winterfeld.`,biographyTitle:`História urbana`,biography:[h(`As fontes e a cidadela`,`Fundação não registrada`,`Mineiros e famílias de pastores ocuparam as fontes antes da coroa. Muralhas vieram depois, quando as passagens passaram a financiar invasões.`),h(`Cidade do abrigo`,`Era atual`,`A obrigação de guardar alimento por três invernos tornou Winterheim símbolo de segurança e alvo de quem deseja controlar a sucessão.`)]},lethariel:{foundation:`Cresceu ao redor de jardins memoriais e encontros dos Círculos; não possui pedra de fundação.`,climate:`Úmido, ameno e protegido pela copa.`,geography:`Margens, raízes elevadas, canais e plataformas vivas.`,government:`Rainha, Círculos da Memória e assembleias de ofício.`,religion:`Caminho das Raízes.`,architecture:`Pontes removíveis, fibras cultivadas e salões encaixados sem ferir troncos.`,culture:`Cada mudança urbana precisa registrar quem e o que será afetado.`,customs:[`Áreas de luto não são colhidas por uma estação`,`Estrangeiros recebem guia responsável pela rota`],festivals:[`Vigília da Copa`,`Retorno das Aves Claras`],cuisine:[`Frutas, sementes, cogumelos e infusões`],military:[`Sentinelas de plataforma`,`Arqueiros de margem`],internalConflicts:[`Sigilo do pacto Kayler`,`Isolacionismo contra abertura`],importantCharacters:[`Aelwen`,`Elara`,`Lyssara`,`Maeriel`],relevantPlaces:[`Palácio da Seiva Clara`,`Jardim dos Nomes`],currentSituation:`A cidade prepara a chegada de Sirius sem tornar pública a rota.`,rumors:[`A segunda metade do medalhão jamais deixa o jardim interno`],narrativeImportance:`Centro da sucessão de Elara e do acerto de contas entre Aelwen e o herdeiro Kayler.`,biographyTitle:`História urbana`,biography:[h(`Cidade sem muralha`,`Antes da Era da Magia`,`Lethariel cresceu por acordos entre margens e bosques, usando o próprio manejo como defesa.`),h(`Memória e pacto`,`Era atual`,`O arquivo do pacto tornou a capital guardiã de uma história que agora precisa ser devolvida aos envolvidos.`)]},"thur-kar":{foundation:`Ponto de encontro aberto quando nove redes de ventilação passaram a depender do mesmo vazio central.`,climate:`Subterrâneo estável, com extremos de calor junto ao magma controlado.`,geography:`Pontes sobre um abismo, canais de magma e nove eixos de túnel.`,government:`Conselho técnico dos Nove Salões.`,religion:`Nove Ecos e Sete Golpes.`,architecture:`Pedra encaixada, metais dilatáveis e ventilação redundante.`,culture:`Medição e registro possuem valor cívico.`,customs:[`Silêncio durante teste de fratura`,`Leitura pública de falhas de obra`],festivals:[`Calibração das Nove Bigornas`],cuisine:[`Fungos, peixes de caverna e alimentos importados de Valoria`],military:[`Guardiões de ponte`,`Engenheiros de evacuação`],internalConflicts:[`Forjas disputam ar e água`,`Tradicionalistas contestam o Oitavo Golpe`],importantCharacters:[`Conselho dos Nove`,`Brunna Dhorin`],relevantPlaces:[`Ponte das Nove Bigornas`,`Câmara do Martelo`],currentSituation:`Seladores pedem acesso a lacres que os engenheiros consideram inseguros.`,rumors:[`Fulgarion foi temperada num canal hoje fechado`],narrativeImportance:`Concentra o conhecimento material necessário para compreender armas, Fraturas e obras antigas.`,biographyTitle:`História urbana`,biography:[h(`O vazio compartilhado`,`Fundação antiga`,`Nove rotas convergiram e transformaram dependência de ventilação em governo comum.`),h(`Depois dos Túneis Vazios`,`491 d.C. em diante`,`A cidade converteu desastre em código, mas novas pressões arcanas testam se a memória evitará repetição.`)]},valoris:{foundation:`Mercado de travessia que cresceu quando sete pontes aceitaram pesos comuns.`,climate:`Temperado, com cheias sazonais.`,geography:`Ilhas fluviais, canais e bairros baixos protegidos por diques.`,government:`Coroa Arden, magistrados de peso e delegados das Sete Pontes.`,religion:`Coroa Dourada e Brasa Comum.`,architecture:`Celeiros fortificados, pórticos de mercado e casas elevadas nas áreas inundáveis.`,culture:`Crédito e reputação são públicos; ocultar grão em emergência é crime grave.`,customs:[`Primeira saca pesada em praça`,`Sinos distintos para cheia e especulação`],festivals:[`Abertura dos Canais`,`Mesa do Primeiro Pão`],cuisine:[`Pães, queijo fresco e peixe de rio`],military:[`Guarda fluvial`,`Cavalaria Arden`],internalConflicts:[`Corte contra barqueiros`,`Especulação de grãos`],importantCharacters:[`Roderic Arden`,`Ilyra Arden`],relevantPlaces:[`Tribunal dos Pesos`,`Sete Pontes`],currentSituation:`Investigações de estoque coincidem com a crise sucessória.`,rumors:[`Dois celeiros nobres possuem paredes falsas`],narrativeImportance:`Decisões tomadas em Valóris podem alimentar ou desestabilizar todo Avernor.`,biographyTitle:`História urbana`,biography:[h(`O mercado das pontes`,`Após a Queda`,`Padrões comuns de medida permitiram que a travessia se tornasse capital.`),h(`Crédito e crise`,`Era atual`,`A riqueza da cidade mascara o conflito entre abundância registrada e fome produzida por retenção.`)]},ravencastle:{foundation:`Fortaleza legionária ampliada em anéis sucessivos até absorver bairros civis.`,climate:`Seco, com verões quentes e risco de incêndio.`,geography:`Colina central cercada por muralhas concêntricas e estradas radiais.`,government:`Coroa Corven, Senado de Estandartes e magistratura civil.`,religion:`Vigília do Sol Negro.`,architecture:`Muralhas preservadas, portões estreitos, cisternas e pátios militares.`,culture:`Serviço e registro são fontes de status; a cidade debate os limites da obediência.`,customs:[`Treino coletivo contra incêndio`,`Exposição pública de ordens anuladas`],festivals:[`Descida dos Estandartes`],cuisine:[`Ensopados de marcha e pão torrado`],military:[`Guarnição dos anéis`,`Arquivo das legiões`],internalConflicts:[`Reformistas contra defensores da perseguição`,`Vigilância de bairros`],importantCharacters:[`Vera Corven`,`Cassor Corven`],relevantPlaces:[`Senado de Estandartes`,`Arquivo das Ordens`],currentSituation:`A sucessão e os ataques de fronteira dividem os anéis urbanos.`,rumors:[`A Corte de Cinza ocupa uma cisterna desativada`],narrativeImportance:`Guarda os documentos capazes de provar responsabilidades da Cinza Branca.`,biographyTitle:`História urbana`,biography:[h(`Fortaleza em camadas`,`Após a Queda`,`Cada ameaça produziu uma nova muralha, e cada muralha antiga tornou-se bairro.`),h(`Cidade sob revisão`,`Era atual`,`Ravencastle tenta converter arquivo militar em memória cívica enquanto parte da elite prefere silêncio.`)]},"porto-de-eldemar":{foundation:`União de docas insulares depois da queda dos governadores de Veyron.`,climate:`Marítimo, úmido e sujeito a tempestades.`,geography:`Ilhas rochosas, docas profundas e bairros em terraços.`,government:`Coroa da Maré Alta, Conselho das Marés e guildas portuárias.`,religion:`Juramento do Horizonte.`,architecture:`Pontes móveis, armazéns de pedra inundáveis e torres de sino.`,culture:`Uma promessa escrita acompanha toda partida.`,customs:[`Entrega pública de placas de cera`,`Código de sinos conhecido por crianças e marinheiros`],festivals:[`Noite das Cartas Luminosas`],cuisine:[`Mariscos, peixe salgado e pão de algas`],military:[`Frota de escolta`,`Guarda das pontes`],internalConflicts:[`Reparações das Águas Negras`,`Contrabando ligado ao conselho`],importantCharacters:[`Selka Elmer`,`Taris Elmer`],relevantPlaces:[`Docas Fundas`,`Torre dos Sinos`],currentSituation:`A prova de Taris e antigas dívidas marítimas dominam o conselho.`,rumors:[`Mapas de evacuação Rivs circulam entre pilotos`],narrativeImportance:`É a principal porta marítima para arquivos, outros mundos e rotas não controladas por coroas.`,biographyTitle:`História urbana`,biography:[h(`Docas reunidas`,`Após a Queda`,`Pontes móveis permitiram que ilhas rivais compartilhassem defesa sem perder autonomia.`),h(`Vitória devida`,`Após 552 d.C.`,`A cidade sobreviveu às Águas Negras, mas ainda deve reparação às vilas usadas no engodo.`)]},"fortaleza-do-veu":{foundation:`Reduto de fronteira anterior aos Bellatrix; convertido em abrigo quando a família recusou recrutamento forçado.`,climate:`Frio e seco, moderado por uma queda-d’água sazonal.`,geography:`Fortaleza escavada atrás da queda, ligada a cavernas e passagens cifradas.`,government:`Mesa local de vigias; guardião eleito durante crise.`,religion:`Chama sem Coroa.`,architecture:`Depósitos dispersos, cisternas internas, corredores falsos e arquivo sem nomes completos.`,culture:`Abrigo e prestação de contas valem mais que nobreza.`,customs:[`Título quebrado ao fim do mandato`,`Inventários cifrados para proteger refugiados`],festivals:[`Noite das Portas Abertas`],cuisine:[`Queijo de cabra, cevada e cogumelos`],military:[`Vigias de passagem`,`Defesa de cerco`],internalConflicts:[`Autonomia contra coordenação`,`Quem pode acessar cifras Bellatrix`],importantCharacters:[`Namídia Bellatrix`,`Marek Bellatrix`],relevantPlaces:[`Arquivo dos Inventários`,`Porta da Queda`],currentSituation:`Agentes procuram os registros de Namídia e obrigam os vigias a rever acessos.`,rumors:[`Uma cópia do caderno saiu da fortaleza depois de 704 d.C.`],narrativeImportance:`Liga a resistência Bellatrix à sobrevivência de Sirius.`,biographyTitle:`História da fortaleza`,biography:[h(`De reduto a abrigo`,`Era das Coroas`,`Os Bellatrix transformaram defesa territorial em instituição para exilados.`),h(`O cerco e as cifras`,`Caça às Bruxas`,`Namídia dispersou estoques e nomes, permitindo que a fortaleza perdesse batalhas sem entregar toda a rede.`)]},"porto-verde":{foundation:`Criado por acordo entre guardiões de Sylvaris e mercadores incapazes de entrar nos bosques internos.`,climate:`Úmido, com cheias fluviais e neblina costeira.`,geography:`Margem larga, armazéns sobre estacas e canais controlados.`,government:`Administrador escolhido pelos Círculos com conselho de companhias estrangeiras.`,religion:`Caminho das Raízes e práticas trazidas pelos mercadores.`,architecture:`Madeira caída marcada, estacas removíveis e telhados leves.`,culture:`Hospitalidade condicionada a regras ambientais claras.`,customs:[`Armas entregues na entrada`,`Fraude pune a companhia inteira por uma estação`],festivals:[`Feira da Madeira Caída`],cuisine:[`Peixes de rio, ervas élficas e pães estrangeiros`],military:[`Sentinelas de margem`,`Barcos de patrulha`],internalConflicts:[`Contrabando de madeira viva`,`Estrangeiros que exigem acesso interno`],importantCharacters:[`Representantes dos Círculos`],relevantPlaces:[`Casa das Fichas`,`Cais das Estacas`],currentSituation:`A movimentação de Elara e rumores sobre Sirius aumentaram a inspeção sem fechar o comércio.`,rumors:[`Marcadores de refugiados foram removidos por alguém com acesso oficial`],narrativeImportance:`É a zona de contato em que Sylvaris precisa equilibrar abertura, segredo e soberania.`,biographyTitle:`História urbana`,biography:[h(`Uma margem negociada`,`Era da Magia`,`O porto nasceu para impedir que comércio exigisse a abertura irrestrita da floresta.`),h(`Fronteira presente`,`1204 d.C.`,`Rotas alteradas e sinais removidos fazem do entreposto a primeira pista da jornada de Elara.`)]}},v={"floresta-antiga":{climate:`Úmido e temperado, com variações de copa e altitude.`,geography:`Bosques manejados, áreas sagradas, rios e uma zona costeira pouco registrada.`,culture:`Elfos e comunidades de margem tratam deslocamento como responsabilidade ecológica.`,relevantPlaces:[`Sylvaris`,`Lethariel`,`Refúgio costeiro de Sirius — posição não publicada`],currentSituation:`Rotas de refúgio antigas voltaram a ser investigadas.`,rumors:[`Algumas mudanças de caminho resultam de guardiões; outras podem indicar Fraturas`],narrativeImportance:`Origem do isolamento de Sirius e território político de Sylvaris.`,historicalSources:[`Mapas dos Círculos`,`Carta de Normus`,`Relatórios de patrulha`]},"mar-das-estrelas":{climate:`Marítimo, com neblina e correntes frias.`,geography:`Mar profundo ao sul, com recifes, bancos luminosos e rotas sazonais.`,culture:`Pilotos de Eldemar distinguem brilho útil de ilusões de distância.`,relevantPlaces:[`Porto de Eldemar`,`Arquipélago das Brumas`],currentSituation:`Avistamentos do kraken alteram comboios sem confirmação de ataque recente.`,rumors:[`O plâncton reage a Fraturas; hipótese sem prova`],narrativeImportance:`Rota comercial e limiar para histórias de outros mundos.`},"deserto-de-zharak":{climate:`Árido, com grande variação entre dia e noite.`,geography:`Planícies de sal, dunas rochosas e aquíferos isolados.`,culture:`Cidades de poço tratam água como bem comum durante conflito.`,customs:[`Trégua obrigatória dentro do círculo de um poço`],cuisine:[`Pães achatados`,`Frutas secas`,`Caldo salgado de raízes`],currentSituation:`Poços orientais baixaram além da marca segura.`,rumors:[`Uma cidade soterrada preserva água sem evaporar`],narrativeImportance:`Conecta Vul’Gar, facções de portal e rotas que evitam Ravenhold.`},"arquipelago-das-brumas":{climate:`Úmido, ventoso e instável.`,geography:`Ilhas pequenas, canais rasos e bancos de neblina.`,government:`Pactos locais entre vilas, sem soberania única.`,culture:`Pilotos locais controlam acesso melhor que grandes frotas.`,currentSituation:`A prova sucessória de Taris aumenta espionagem e sabotagem.`,rumors:[`Cartógrafos do Impossível registraram uma ilha que muda de distância`],narrativeImportance:`Refúgio comercial e espaço onde autoridade de Eldemar encontra limites.`},"terras-sombrias":{climate:`Seco e contaminado por poeira metálica em antigas zonas de mineração.`,geography:`Cidades vazias, minas abertas, poços inseguros e estradas tomadas por vegetação.`,currentSituation:`Expedições sanitárias distinguem contaminação de relatos sobrenaturais.`,rumors:[`Alguns mortos vistos nas ruínas podem ser Retornados; nenhum caso foi autenticado`],narrativeImportance:`Mostra como desastre material se converte em mito e oferece campo para necromancia e investigação.`},"mar-interior":{climate:`Temperado, com neblinas de margem.`,geography:`Lagos e estreitos conectados por pontes, balsas e antigos postos militares.`,culture:`Barqueiros mantêm vocabulário misto de Valoria, Sylvaris e tradições Rivs.`,relevantPlaces:[`Ruínas Rivs`,`Sete Pontes`],currentSituation:`Escavações ilegais procuram o Arquivo Submerso.`,rumors:[`Correntes teriam mudado para ocultar uma entrada Rivs`],narrativeImportance:`Corredor econômico e principal vestígio territorial da Casa Rivs.`}},y=[e({id:`winterfeld`,name:`Winterfeld`,subtitle:`Gelo, muralhas e juramentos antigos`,summary:`Reino setentrional protegido por montanhas, gigantes aliados e pela presença rara do dragão branco Vyrasul.`,description:`Winterfeld vive de mineração profunda, criação de cervos-das-neves e pedágios nas passagens glaciais. Seu conselho de jarls limita a autoridade da coroa, sobretudo durante invernos de fome. Vyrasul não pertence ao reino nem obedece ao monarca: o dragão natural escolheu permanecer nas geleiras após ter sido salvo de caçadores.`,image:`/assets/images/kingdoms/kingdom-winterfeld-page.webp`,thumbnail:`/assets/images/kingdoms/kingdom-winterfeld-card.webp`,category:`Reino humano`,status:`Soberano`,location:`Extremo norte`,capital:`Winterheim`,symbol:`Lobo branco sob uma estrela de gelo`,government:`Monarquia pactuada com o Conselho dos Jarls`,economy:`Ferro glacial, peles, sal e controle das passagens`,relations:[{label:`Vyrasul`,to:`/criaturas/vyrasul`},{label:`Winterheim`,to:`/cidades/winterheim`}],events:[`Pacto dos Gigantes`,`Cerco do Degelo`],curiosities:[`As muralhas mantêm depósitos públicos de grãos para três invernos.`],quotes:[`No norte, uma promessa vale o peso do abrigo.`]}),e({id:`sylvaris`,name:`Sylvaris`,subtitle:`O coração vivo da Floresta Antiga`,summary:`Reino élfico protegido por árvores milenares, sentinelas e caminhos que se transformam sob orientação dos guardiões.`,description:`Sylvaris não separa cidade e floresta: pontes crescem entre troncos, a água define bairros e construções novas exigem o consentimento de círculos de guardiões. A Rainha governa com um conselho de memórias, formado por representantes de ofícios e bosques. A amizade com Normus garantiu refúgio aos Kayler e originou um pacto secreto sobre seus descendentes.`,image:`/assets/images/kingdoms/kingdom-sylvaris-page.webp`,thumbnail:`/assets/images/kingdoms/kingdom-sylvaris-card.webp`,category:`Reino élfico`,status:`Soberano`,location:`Oeste e sudoeste`,capital:`Lethariel`,symbol:`Folha de prata sobre esmeralda`,government:`Monarquia aconselhada pelos Círculos da Memória`,economy:`Medicina, madeira caída, vidro vegetal e manuscritos`,relations:[{label:`Elara`,to:`/personagens/elara`},{label:`Rainha Aelwen`,to:`/personagens/rainha-aelwen`},{label:`Lethariel`,to:`/cidades/lethariel`}],events:[`Defesa de Sylvaris`,`Pacto dos Descendentes`],curiosities:[`Cortar uma árvore viva sem autorização é tratado como agressão política.`],quotes:[`A floresta não fecha caminhos; ela decide quem está preparado para atravessá-los.`]}),e({id:`kar-dum`,name:`Kar-Dûm`,subtitle:`Pedra, fogo e memória`,summary:`Confederação anã de salões subterrâneos, minas profundas e forjas cujo acesso depende de juramentos comerciais.`,description:`Kar-Dûm é uma união de salões, não uma coroa simples. Mestres de forja, cartógrafos de túneis e guardiões de aquíferos dividem o poder. A riqueza mineral sustenta o reino, mas também o força a negociar alimentos com Valoria. Cada túnel abandonado é lacrado com uma placa explicando a razão — desabamento, gás, criatura ou dívida.`,image:`/assets/images/kingdoms/kingdom-kar-dum-page.webp`,thumbnail:`/assets/images/kingdoms/kingdom-kar-dum-card.webp`,category:`Reino anão`,status:`Confederação soberana`,location:`Cordilheira central`,capital:`Thur-Kar`,symbol:`Martelo dourado sobre montanha negra`,government:`Conselho dos Nove Salões`,economy:`Aço, ferramentas, engenharia hidráulica e gemas`,relations:[{label:`Thur-Kar`,to:`/cidades/thur-kar`},{label:`Martelo de Orun`,to:`/artefatos/martelo-de-orun`}],events:[`Abertura dos Portões`,`Guerra dos Túneis Vazios`],curiosities:[`Contratos são gravados em lâminas finas de ardósia.`],quotes:[`Pedra registra até o golpe que não a partiu.`]}),e({id:`valoria`,name:`Valoria`,subtitle:`Campos dourados e poder mercantil`,summary:`A planície fértil que alimenta boa parte do continente converteu trigo, cavalaria e crédito em influência política.`,description:`Valoria cresceu ao controlar rios navegáveis e celeiros. Grandes famílias rurais competem com corporações urbanas, produzindo uma corte rica e instável. A coroa consegue financiar guerras alheias, mas depende de camponeses que já interromperam colheitas para exigir preços mínimos e reparos nos diques.`,image:`/assets/images/kingdoms/kingdom-valoria-page.webp`,thumbnail:`/assets/images/kingdoms/kingdom-valoria-card.webp`,category:`Reino humano`,status:`Soberano`,location:`Planícies centrais`,capital:`Valóris`,symbol:`Leão dourado em campo vermelho`,government:`Monarquia de pactos agrários`,economy:`Grãos, cavalos, crédito e transporte fluvial`,relations:[{label:`Valóris`,to:`/cidades/valoris`},{label:`Casa Arden`,to:`/casas/arden`}],events:[`Revolta dos Celeiros`,`Pacto das Sete Pontes`],curiosities:[`A moeda valoriana é aceita nos portos de Eldemar, mas sofre deságio no norte.`],quotes:[`Quem controla o pão não precisa levantar a espada primeiro.`]}),e({id:`ravenhold`,name:`Ravenhold`,subtitle:`A coroa da guerra`,summary:`Reino de legiões disciplinadas e fortalezas austeras, dividido entre veteranos reformistas e uma aristocracia expansionista.`,description:`As fronteiras abertas de Ravenhold favoreceram uma cultura de fortificações e serviço militar. A eficiência de suas estradas contrasta com a vigilância nas cidades. Depois da Caça às Bruxas, oficiais mais jovens passaram a questionar os decretos que seus predecessores executaram, tornando o exército o principal palco político do reino.`,image:`/assets/images/kingdoms/kingdom-ravenhold-page.webp`,thumbnail:`/assets/images/kingdoms/kingdom-ravenhold-card.webp`,category:`Reino humano`,status:`Soberano`,location:`Leste central`,capital:`Ravencastle`,symbol:`Corvo negro sobre aço`,government:`Monarquia militar com Senado de Estandartes`,economy:`Armas, pedágios terrestres, cavalos e mercenários`,relations:[{label:`Ravencastle`,to:`/cidades/ravencastle`},{label:`Guerra da Cinza Branca`,to:`/guerras/guerra-da-cinza-branca`}],events:[`Reforma das Legiões`,`Guerra da Cinza Branca`],curiosities:[`Todo marco de estrada indica também a distância até o abrigo militar mais próximo.`],quotes:[`Disciplina sem consciência é apenas obediência bem vestida.`]}),e({id:`eldemar`,name:`Eldemar`,subtitle:`Senhores das marés`,summary:`Potência marítima que equilibra estaleiros, guildas de navegadores e rotas perigosas pelo Arquipélago das Brumas.`,description:`Eldemar é governado a partir de um porto construído sobre ilhas ligadas por pontes móveis. Sua frota protege comboios, cobra licenças e, em segredo, negocia informações com contrabandistas. A dependência de madeira de Sylvaris criou protocolos rígidos: apenas troncos caídos e marcados podem entrar nos estaleiros reais.`,image:`/assets/images/kingdoms/kingdom-eldemar-page.webp`,thumbnail:`/assets/images/kingdoms/kingdom-eldemar-card.webp`,category:`Reino humano`,status:`Soberano`,location:`Costa sul`,capital:`Porto de Eldemar`,symbol:`Tridente de prata sobre azul profundo`,government:`Monarquia marítima e Conselho das Marés`,economy:`Navegação, sal, pesca, mapas e construção naval`,relations:[{label:`Porto de Eldemar`,to:`/cidades/porto-de-eldemar`},{label:`Kraken de Eldemar`,to:`/criaturas/kraken-de-eldemar`}],events:[`Batalha das Águas Negras`,`Tratado da Madeira Caída`],curiosities:[`Cartas náuticas oficiais omitem enseadas usadas em rotas de evacuação.`],quotes:[`Nenhuma muralha é tão larga quanto o mar.`]}),e({id:`montanhas-cinzentas`,name:`Montanhas Cinzentas`,subtitle:`Refúgio dos que não possuem reino`,summary:`Território confederado de exilados, desertores e famílias perseguidas, onde Normus conheceu Namídia Bellatrix.`,description:`A região não possui rei nem capital permanente. Fortalezas independentes elegem uma Mesa de Vigias durante crises e voltam à autonomia quando o perigo passa. O clima severo limita lavouras, tornando cabras, cogumelos de caverna e pedágios de passagem essenciais. A Fortaleza do Véu, antiga casa de Namídia, é um reduto de reunião e protege arquivos sobre fugitivos da Caça às Bruxas, sem governar as demais fortalezas.`,image:`/assets/images/kingdoms/kingdom-montanhas-cinzentas-page.webp`,thumbnail:`/assets/images/kingdoms/kingdom-montanhas-cinzentas-card.webp`,category:`Território rebelde`,status:`Confederação autônoma`,location:`Nordeste montanhoso`,capital:`Sem capital permanente`,principalStronghold:`Fortaleza do Véu`,symbol:`Torre quebrada diante de três picos`,government:`Confederação temporária de fortalezas`,economy:`Criação de cabras, minério pobre, escolta e pedágios`,relations:[{label:`Namídia Bellatrix`,to:`/personagens/namidia-bellatrix`},{label:`Fortaleza do Véu`,to:`/cidades/fortaleza-do-veu`}],events:[`Cerco da Fortaleza do Véu`,`Refúgio de Normus Kayler`],curiosities:[`A ausência de capital formal é uma defesa contra conquista e corrupção.`],quotes:[`Quem perdeu uma pátria aprende a construir abrigo.`]})],b={winterfeld:{demographics:[`Humanos concentrados em vales termais`,`Comunidades de gigantes mantêm autonomia nos passos`,`Migração sazonal acompanha rebanhos e minas`],laws:[`Abrigo de emergência não pode ser recusado`,`Estoques públicos são auditados antes do inverno`,`Conselho dos Jarls confirma a sucessão`],military:[`Infantaria de passagem`,`Batedores de gelo`,`Vyrasul não integra as forças do reino`],internalConflicts:[`Jarls de mineração contra guardiões de aquíferos`,`Culto indevido a Vyrasul rejeitado pela Vigília da Última Brasa`],dailyLife:[`Banhos termais públicos`,`Conservação de alimento`,`Reparo coletivo de telhados antes das quarenta noites`]},sylvaris:{demographics:[`Elfos em cidades-jardim e comunidades de bosque`,`Estrangeiros concentrados em Porto Verde`,`Refugiados históricos protegidos por nomes cifrados`],laws:[`Cortar árvore viva exige consentimento dos Círculos`,`A coroa não pode vender território`,`Sucessão é escolha entre descendentes elegíveis`],military:[`Sentinelas florestais`,`Arqueiros de plataformas`,`Caminhos recolhidos funcionam como defesa, não magia`],internalConflicts:[`Sigilo do pacto Kayler`,`Debate entre isolamento e responsabilidade continental`,`Receio sobre a escolha de Elara`],dailyLife:[`Manejo por estação`,`Jardins memoriais`,`Ofícios representados nos Círculos da Memória`]},"kar-dum":{demographics:[`Anões organizados por salão, sangue e ofício`,`Mercadores de superfície nos portões externos`,`Bairros definidos por água e ventilação`],laws:[`Toda escavação responde aos Nove Ecos`,`Três salões aprovam abertura ancestral`,`Adoção de ofício não falsifica descendência de sangue`],military:[`Guardiões de túnel`,`Engenheiros de evacuação`,`Escudos adaptados a corredores`],internalConflicts:[`Tradição contra o Oitavo Golpe da inovação`,`Forjas contra guardiões de água`,`Dependência alimentar de Valoria`],dailyLife:[`Turnos regulados por sinos de ventilação`,`Contratos em ardósia`,`Ferramentas nomeadas e herdadas`]},valoria:{demographics:[`Maioria rural junto a diques e canais`,`Guildas de barqueiros nas cidades`,`Nobreza de celeiro e crédito`],laws:[`Preço de emergência para grãos`,`Sete Pontes confirmam a sucessão`,`Diques privados devem servir à drenagem pública`],military:[`Cavalaria leve`,`Guardas fluviais`,`Levas rurais politicamente contestadas`],internalConflicts:[`Ala expansionista contra pactos agrários`,`Corte contra associações rurais`,`Popularidade de Ilyra ameaça parentes`],dailyLife:[`Mercados de peso público`,`Festivais de abertura dos canais`,`Mutirões de dique`]},ravenhold:{demographics:[`Famílias militares nos anéis internos`,`Artesãos de armas e carroças`,`Veteranos reformistas em bairros periféricos`],laws:[`Serviço militar sujeito a registro civil`,`Senado confirma herdeiros`,`Direito à recusa de ordem criminosa ainda em disputa`],military:[`Legiões permanentes`,`Estradas e abrigos logísticos`,`Senado de Estandartes`],internalConflicts:[`Reformistas contra defensores da Caça às Bruxas`,`Vigilância urbana`,`Pretensão de Cassor Corven`],dailyLife:[`Bairros em antigos anéis defensivos`,`Treino cívico de incêndio`,`Mercados sob inspeção militar`]},eldemar:{demographics:[`Marinheiros e famílias portuárias`,`Guildas de pilotos do arquipélago`,`Comunidades de maré nos níveis baixos`],laws:[`Licença de navegação condiciona sucessão`,`Madeira de Sylvaris precisa de marca de queda`,`Sinos portuários têm código público`],military:[`Frota de escolta`,`Pilotos de águas rasas`,`Pontes móveis de defesa`],internalConflicts:[`Conselho das Marés contra a coroa`,`Reparações das Águas Negras`,`Relação ambígua com contrabandistas`],dailyLife:[`Turnos marcados por maré`,`Casas nos terraços altos`,`Juramentos em placas de cera`]},"montanhas-cinzentas":{demographics:[`Famílias exiladas de diversas origens`,`Pastores, mineiros e escoltas`,`Fortalezas com cidadania por serviço`],laws:[`Mesa de Vigias existe apenas durante crises`,`Títulos são dever temporário`,`Abrigar perseguido pode superar tratado externo`],military:[`Vigias de passagem`,`Defesa de cerco`,`Rotas cifradas de evacuação`],internalConflicts:[`Autonomia contra necessidade de coordenação`,`Segredos Bellatrix`,`Pedágios entre fortalezas`],dailyLife:[`Criação de cabras`,`Cogumelos de caverna`,`Inventários usados também como memória de refugiados`]}},x=y.map(e=>({...e,...b[e.id],...g[e.id]})),S=[e({id:`winterheim`,name:`Winterheim`,subtitle:`A cidadela sob o gelo`,summary:`Capital de Winterfeld, erguida em terraços de pedra negra ao redor de fontes termais.`,description:`Canais aquecidos mantêm oficinas e enfermarias funcionando durante o inverno. A cidade fecha seus portões externos por quarenta noites no auge do frio, mas conserva túneis de socorro conhecidos por guias juramentados.`,category:`Capital`,status:`Habitada`,kingdom:`Winterfeld`,location:`Winterfeld`,population:`38 mil habitantes`,economy:`Metalurgia, peles e abastecimento militar`,relations:[{label:`Winterfeld`,to:`/reinos/winterfeld`}]}),e({id:`lethariel`,name:`Lethariel`,subtitle:`A cidade entre raízes e estrelas`,summary:`Capital de Sylvaris, distribuída entre margens, plataformas vivas e salões escavados sem ferir as árvores.`,description:`Lethariel não possui muralha convencional. Trilhas mudam, pontes são recolhidas e sentinelas leem alterações no comportamento de aves e fungos. O Palácio da Seiva Clara guarda o pacto firmado entre Normus e a Rainha.`,category:`Capital`,status:`Habitada`,kingdom:`Sylvaris`,location:`Floresta Antiga`,population:`22 mil habitantes`,economy:`Cura, manuscritos, vidro vegetal e diplomacia`,image:`/assets/images/atlas-plates/lethariel-page.webp`,thumbnail:`/assets/images/atlas-plates/lethariel-card.webp`,relations:[{label:`Sylvaris`,to:`/reinos/sylvaris`},{label:`Elara`,to:`/personagens/elara`}]}),e({id:`thur-kar`,name:`Thur-Kar`,subtitle:`O salão das nove bigornas`,summary:`Centro político de Kar-Dûm e ponto de encontro entre nove redes subterrâneas.`,description:`Pontes de pedra cruzam um vazio iluminado por canais de magma controlados. A ventilação da cidade é uma obra tão valorizada quanto suas forjas: qualquer mestre que a comprometa perde o direito de trabalhar metal.`,category:`Capital subterrânea`,status:`Habitada`,kingdom:`Kar-Dûm`,location:`Cordilheira central`,population:`61 mil habitantes`,economy:`Forjas, bombas hidráulicas e cartografia subterrânea`,relations:[{label:`Kar-Dûm`,to:`/reinos/kar-dum`}]}),e({id:`valoris`,name:`Valóris`,subtitle:`Mercado das sete pontes`,summary:`Capital de Valoria, cortada por canais de irrigação e dominada por celeiros fortificados.`,description:`A praça central funciona ao mesmo tempo como mercado, bolsa de grãos e tribunal de pesos. Nos bairros baixos, associações de barqueiros exercem poder equivalente ao das famílias nobres.`,category:`Capital`,status:`Habitada`,kingdom:`Valoria`,location:`Planícies centrais`,population:`94 mil habitantes`,economy:`Grãos, crédito e transporte fluvial`,relations:[{label:`Valoria`,to:`/reinos/valoria`},{label:`Casa Arden`,to:`/casas/arden`}]}),e({id:`ravencastle`,name:`Ravencastle`,subtitle:`A fortaleza que virou cidade`,summary:`Capital escalonada de Ravenhold, organizada ao redor de antigos anéis defensivos.`,description:`Cada expansão preservou a muralha anterior, criando bairros circulares e gargalos fáceis de defender. A arquitetura oferece segurança, mas concentra multidões e torna incêndios um risco constante.`,category:`Capital fortificada`,status:`Habitada`,kingdom:`Ravenhold`,location:`Leste central`,population:`73 mil habitantes`,economy:`Armas, logística e administração militar`,relations:[{label:`Ravenhold`,to:`/reinos/ravenhold`}]}),e({id:`porto-de-eldemar`,name:`Porto de Eldemar`,subtitle:`A cidade das pontes móveis`,summary:`Capital marítima construída sobre ilhas rochosas, docas profundas e pontes que isolam distritos durante ataques.`,description:`O nível inferior pertence às marés e recebe armazéns de pedra; residências ocupam terraços superiores. Sinos codificados anunciam tempestades, incêndios ou monstros marinhos sem causar pânico desnecessário.`,category:`Capital portuária`,status:`Habitada`,kingdom:`Eldemar`,location:`Costa sul`,population:`81 mil habitantes`,economy:`Estaleiros, sal, pesca e cartografia`,relations:[{label:`Eldemar`,to:`/reinos/eldemar`}]}),e({id:`fortaleza-do-veu`,name:`Fortaleza do Véu`,subtitle:`Pedra para quem ficou sem bandeira`,summary:`Maior reduto das Montanhas Cinzentas e antiga residência da família Bellatrix.`,description:`Escavada atrás de uma queda-d’água sazonal, a fortaleza possui depósitos dispersos para resistir a cercos. Seus arquivos registram nomes verdadeiros apenas em cifras, protegendo descendentes de perseguidos.`,category:`Fortaleza`,status:`Habitada`,kingdom:`Montanhas Cinzentas`,location:`Montanhas Cinzentas`,population:`9 mil habitantes`,economy:`Escolta, mineração, criação e pedágios`,relations:[{label:`Montanhas Cinzentas`,to:`/reinos/montanhas-cinzentas`},{label:`Namídia Bellatrix`,to:`/personagens/namidia-bellatrix`}]}),e({id:`porto-verde`,name:`Porto Verde`,subtitle:`A margem aberta de Sylvaris`,summary:`Entreposto controlado onde estrangeiros negociam com Sylvaris sem penetrar os bosques internos.`,description:`Armazéns repousam sobre estacas para não alterar o curso das águas. Mercadores entregam armas na entrada e recebem fichas de madeira numeradas; qualquer fraude encerra o acesso de toda a companhia por uma estação.`,category:`Porto fluvial`,status:`Habitada`,kingdom:`Sylvaris`,location:`Costa oeste`,population:`7 mil habitantes`,economy:`Troca de ervas, vidro, tecidos e mapas`,relations:[{label:`Sylvaris`,to:`/reinos/sylvaris`}]})].map(e=>({...e,..._[e.id]})),C=(e,t,n)=>({title:e,period:t,body:n}),w={kayler:{foundation:`Origem anterior aos registros da Era da Magia; a tradição liga a linhagem a um dos três mortais marcados pela Primeira Tempestade, sem prova genealógica contínua.`,government:`Conselho doméstico de adultos manifestados; a Casa nunca reconheceu soberania territorial.`,succession:`Herança de sangue não cria chefia automática. Sirius é o último herdeiro público, mas não governa outros povos nem possíveis ramos desconhecidos.`,religion:`Doutrina das Três Correntes — Corrente Celeste.`,culture:`Treino do dom, serviço em crises e recusa a coroas fundadas em magia.`,customs:[`Registrar o custo de cada manifestação`,`Entregar Fulgarion apenas com instruções de limite`],festivals:[`Vigília da Primeira Tempestade — registro fragmentário`],alliesPolitical:[`Sylvaris por pacto de proteção`,`Kar-Dûm por cooperação histórica`],rivalsPolitical:[`Conselho dos Sete Reis`,`Facções que desejam controlar Fulgarion`],importantCharacters:[`Normus Kayler`,`Sirius Kayler`,`Namídia Bellatrix — vínculo familiar por companheirismo`],relevantPlaces:[`Floresta Antiga`,`Sylvaris`],currentSituation:`Sirius reapareceu e precisa decidir se “Casa Kayler” continuará sendo linhagem, dever público ou apenas nome familiar.`,rumors:[`Ramos sem manifestação podem ter sobrevivido sob nomes comuns`],narrativeImportance:`Une o protagonista, Fulgarion, a perseguição e o pacto de Sylvaris.`,publicReputation:`Heróis de guerra para comunidades protegidas; ameaça hereditária para a propaganda das coroas.`,biographyTitle:`História da Casa`,biography:[C(`A Corrente Celeste`,`Antes da Era da Magia`,`A origem é preservada como tradição, não cadeia documental. Os Kayler associaram tempestade a movimento e responsabilidade.`),C(`Prestígio e exposição`,`Era das Coroas`,`Intervenções públicas, culminando em Normus, tornaram a Casa famosa e fácil de identificar.`),C(`Perseguição e herança`,`Caça às Bruxas–1204 d.C.`,`A Casa foi dada como extinta. A sobrevivência de Sirius restitui o nome sem restaurar arquivos, território ou estrutura familiar.`)],additionalRelations:[{label:`Namídia Bellatrix — família por companheirismo`,to:`/personagens/namidia-bellatrix`},{label:`Fulgarion`,to:`/reliquias/fulgarion`},{label:`Caça às Bruxas`,to:`/historia/caca-bruxas`}]},nimbus:{foundation:`Tradição ligada ao segundo mortal da Primeira Tempestade; arquivos seguros começam apenas na Era da Magia.`,government:`Círculos de estratégia e disciplina, historicamente divididos sobre centralização.`,succession:`Desconhecida após a destruição pública. Nenhum pretendente autenticado.`,religion:`Corrente Escarlate da Doutrina das Três Correntes.`,culture:`Antecipação, informação e controle do medo; o excesso de controle produziu dissensos internos.`,customs:[`Debater três derrotas possíveis antes de aprovar campanha`,`Separar informantes para que ninguém detenha a rede inteira`],alliesPolitical:[`Alianças temporárias com cidades ameaçadas`],rivalsPolitical:[`Conselho dos Sete Reis`,`Fações internas rivais`],importantCharacters:[`Cassian Nimbus`,`Varel Nimbus`,`Sarya Nimbus`],currentSituation:`Considerada extinta; qualquer sobrevivente permanece informação contestada ou reservada ao autor.`,rumors:[`Crianças evacuadas podem ter recebido nomes comuns`],narrativeImportance:`Representa o custo de enfrentar a perseguição em combate aberto.`,publicReputation:`Lembrados como estrategistas; propaganda os retratou falsamente como manipuladores de toda guerra.`,biographyTitle:`História da Casa`,biography:[C(`A Corrente Escarlate`,`Era da Magia`,`Os Nimbus formalizaram disciplina, deslocamento e leitura de campo como dever de proteção.`),C(`Rivalidades de método`,`Era das Coroas`,`A busca por controle dividiu conselhos sem romper o Juramento Arcano.`),C(`Resistência final`,`Caça às Bruxas`,`A Casa escolheu combate aberto para cobrir evacuações e foi declarada destruída. A declaração não prova a morte de todos os ramos.`)],additionalRelations:[{label:`Guerra da Cinza Branca`,to:`/guerras/guerra-da-cinza-branca`},{label:`Genealogia Nimbus`,to:`/genealogias/nimbus`}]},rivs:{foundation:`A tradição mais antiga entre as três Casas; os próprios arquivos recusavam transformar mito de origem em genealogia comprovada.`,government:`Guardiões de arquivo distribuídos por ilhas e bacias.`,succession:`Desconhecida. Maelis e Oriel desapareceram; nenhum herdeiro público foi autenticado.`,religion:`Corrente Profunda da Doutrina das Três Correntes.`,culture:`Preservar conhecimento sem concentrá-lo numa única pessoa ou margem.`,customs:[`Mapear fontes antes de fronteiras`,`Copiar índices separadamente do conteúdo`],festivals:[`Leitura das Águas Baixas`],alliesPolitical:[`Barqueiros do Mar Interior`,`Pilotos de Eldemar em acordos antigos`],rivalsPolitical:[`Coroas interessadas nos arquivos`,`Necromantes que confundem memória e posse`],importantCharacters:[`Naira Rivs`,`Maelis Rivs`,`Oriel Rivs`],relevantPlaces:[`Mar Interior`,`Arquivo Submerso`],currentSituation:`O destino público permanece desconhecido. Escavações ilegais ameaçam vestígios e confundem prova com lenda.`,rumors:[`O arquivo teria atravessado uma Fratura`,`Índices separados continuam em circulação`],narrativeImportance:`Conecta memória, água, outros mundos e a possibilidade de que “extinção” seja um erro documental.`,publicReputation:`Respeitados por cartógrafos e acusados de ocultar conhecimento por governantes.`,biographyTitle:`História da Casa`,biography:[C(`A Corrente Profunda`,`Antes dos tratados`,`A Casa organizou arquivos em torno de água, conservação e rotas de fuga.`),C(`Abertura cautelosa`,`Era da Magia`,`Rivs negociaram acesso parcial, recusando entregar índices completos às coroas.`),C(`O desaparecimento`,`Caça às Bruxas`,`Bibliotecas e pessoas foram evacuadas ao mesmo tempo. O silêncio resultante é ausência de prova, não confirmação de morte.`)],additionalRelations:[{label:`Genealogia Rivs`,to:`/genealogias/rivs`},{label:`Caça às Bruxas`,to:`/historia/caca-bruxas`}]},bellatrix:{foundation:`Casa anterior às Montanhas Cinzentas, reorganizada depois de perder terras por recusar recrutamento forçado.`,government:`Guardião eleito pela fortaleza; títulos terminam com a crise ou podem ser retirados pelos vigias.`,succession:`Serviço e confiança, não primogenitura. Linhagem de sangue preserva memória familiar, não direito automático.`,religion:`Chama sem Coroa.`,culture:`Hospitalidade juramentada, resistência de cerco e arquivos que protegem perseguidos.`,customs:[`Quebrar a insígnia ao fim do mandato`,`Cifrar nomes em inventários separados`],festivals:[`Noite das Portas Abertas`],alliesPolitical:[`Fortalezas da Mesa de Vigias`,`Redes civis de refúgio`],rivalsPolitical:[`Coroas expansionistas`,`Redutos que vendem nomes`],importantCharacters:[`Namídia Bellatrix`,`Marek Bellatrix`,`Lena Bellatrix`],relevantPlaces:[`Fortaleza do Véu`],currentSituation:`A Casa continua ativa, mas o legado de Namídia atrai agentes interessados nas rotas de Sirius.`,rumors:[`Cópias parciais do caderno de Namídia sobreviveram`],narrativeImportance:`Demonstra que a sobrevivência de Sirius dependeu tanto de organização humana quanto de magia Kayler.`,publicReputation:`Símbolo rebelde nas Montanhas; família criminosa em antigos decretos reais.`,biographyTitle:`História da Casa`,biography:[C(`A perda das terras`,`Era das Coroas`,`Os Bellatrix recusaram entregar aldeões a uma campanha e perderam propriedades.`),C(`Título transformado`,`Exílio nas Montanhas`,`Príncipe deixou de significar proprietário e passou a nomear um guardião sujeito à eleição.`),C(`Namídia e o Véu`,`Caça às Bruxas`,`A Casa converteu logística de cerco em rede de refúgio e uniu seu destino aos Kayler sem adquirir magia.`)],additionalRelations:[{label:`Genealogia Bellatrix`,to:`/genealogias/bellatrix`},{label:`Chama sem Coroa`,to:`/religioes/chama-sem-coroa`}]},arden:{foundation:`Linhagem de administradores de diques reconhecida como Casa governante depois da fragmentação de Valoria.`,government:`Casa real limitada pelas Sete Pontes, guildas de barqueiros e pactos agrários.`,succession:`Descendência, quitação de dívidas públicas e confirmação das Sete Pontes.`,religion:`Coroa Dourada e Brasa Comum, com divisões entre corte e campo.`,culture:`Autoridade medida por colheita, manutenção e confiança de comunidades rurais.`,customs:[`Abrir livros de estoque em emergência`,`Serviço anual nos diques para membros da linha principal`],festivals:[`Mesa do Primeiro Pão`],alliesPolitical:[`Associações rurais`,`Parte das guildas fluviais`],rivalsPolitical:[`Parentes expansionistas`,`Especuladores de grão`],importantCharacters:[`Roderic Arden`,`Ilyra Arden`],relevantPlaces:[`Valóris`,`Campos Baixos`],currentSituation:`Ilyra é herdeira, mas sua oposição à guerra preventiva divide a família.`,rumors:[`A ala cortesã planeja usar dívidas fabricadas contra a herdeira`],narrativeImportance:`Sua disputa pode transformar sucessão familiar em crise alimentar continental.`,publicReputation:`Respeitada por manter infraestrutura e criticada por enriquecer com crédito agrícola.`,biographyTitle:`História da Casa`,biography:[C(`Diques antes do trono`,`Após a Queda`,`Os primeiros Arden ganharam autoridade coordenando água e estoque, não conquistando território.`),C(`Pacto das Sete Pontes`,`Era das Coroas`,`A família aceitou confirmação externa para encerrar uma fome e preservar a monarquia.`),C(`Ruptura presente`,`1204 d.C.`,`Ilyra tenta manter o pacto enquanto parentes desejam transformar excedente em expansão.`)],additionalRelations:[{label:`Genealogia de Valoria`,to:`/genealogias/valoria`},{label:`Sucessão de Valoria`,to:`/sucessoes/valoria`}]}},T=[e({id:`kayler`,name:`Casa Kayler`,subtitle:`Senhores da Tempestade`,summary:`A mais célebre linhagem bruxa, associada a tempestades, raios e domínio arcano superior.`,description:`A Casa Kayler entendia poder como obrigação de intervenção: seus membros escoltavam refugiados, encerravam cercos e enfrentavam criaturas que exércitos evitavam. Essa visibilidade trouxe prestígio e os tornou o primeiro alvo da perseguição. A magia Kayler é hereditária; treino refina o dom, mas jamais o cria em quem não nasceu na linhagem.`,category:`Linhagem bruxa`,status:`Quase extinta`,lineage:`Kayler`,origin:`Planícies centrais`,traits:`Cabelos brancos, olhos violetas e afinidade com tempestades`,motto:`O céu se curva, mas o sangue permanece.`,members:[`Normus Kayler`,`Sirius Kayler`],relations:[{label:`Normus Kayler`,to:`/personagens/normus-kayler`},{label:`Sirius Kayler`,to:`/personagens/sirius-kayler`}],curiosities:[`O brasão tradicional não representa uma coroa, mas um céu partido por três raios.`]}),e({id:`nimbus`,name:`Casa Nimbus`,subtitle:`Estrategistas da Serpente`,summary:`Linhagem de duelistas e planejadores, famosa por disciplina, ambição e leitura antecipada do campo de batalha.`,description:`Os Nimbus preferiam influenciar conflitos antes que começassem. Mantinham redes de informantes, estudavam logística e usavam magia para deslocamentos curtos e perturbação dos sentidos. Sua obsessão por controle gerou rivalidades internas. Registros oficiais os consideram extintos, mas arquivos incompletos impedem certeza.`,category:`Linhagem bruxa`,status:`Considerada extinta`,lineage:`Nimbus`,origin:`Leste de Avernor`,traits:`Cabelos brancos, olhos violetas, precisão e disciplina`,motto:`A vitória pertence a quem enxerga antes.`,members:[`Registros suprimidos`],relations:[{label:`Era da Magia`,to:`/historia/era-magia`}],curiosities:[`A serpente do brasão possui olhos abertos voltados para direções opostas.`]}),e({id:`rivs`,name:`Casa Rivs`,subtitle:`Guardiões das Águas`,summary:`A mais antiga linhagem conhecida, associada à água, neblina, gelo e preservação de conhecimento arcano.`,description:`Os Rivs ergueram arquivos em ilhas fluviais e aceitavam poucos visitantes. Sua magia era paciente: desviava correntes, ocultava travessias e conservava documentos contra umidade e fogo. Durante a Caça às Bruxas, os arquivos foram evacuados. O destino da família permanece desconhecido.`,category:`Linhagem bruxa`,status:`Destino desconhecido`,lineage:`Rivs`,origin:`Bacias do Mar Interior`,traits:`Cabelos brancos, olhos violetas, serenidade e memória ritual`,motto:`Toda verdade encontra seu caminho.`,members:[`Último registro: Maelis Rivs`],relations:[{label:`Arquivo Submerso`,to:`/lendas/arquivo-submerso`}],curiosities:[`Mapas Rivs marcam fontes de água antes de fronteiras políticas.`]}),e({id:`bellatrix`,name:`Casa Bellatrix`,subtitle:`A torre quebrada`,summary:`Família principesca rebelde que converteu uma fortaleza de fronteira em refúgio para perseguidos.`,description:`Os Bellatrix perderam terras ao recusar o recrutamento forçado de aldeões. Nas Montanhas Cinzentas, reorganizaram seus títulos: príncipe passou a significar guardião eleito da fortaleza, não proprietário do povo. Namídia herdou essa responsabilidade e abriu abrigo para Normus.`,category:`Casa rebelde`,status:`Ativa`,lineage:`Bellatrix`,kingdom:`Montanhas Cinzentas`,origin:`Fortaleza do Véu`,traits:`Austeridade, hospitalidade juramentada e resistência a cercos`,motto:`Do que foi quebrado faremos abrigo.`,members:[`Namídia Bellatrix`,`Marek Bellatrix`],relations:[{label:`Namídia Bellatrix`,to:`/personagens/namidia-bellatrix`},{label:`Fortaleza do Véu`,to:`/cidades/fortaleza-do-veu`}]}),e({id:`arden`,name:`Casa Arden`,subtitle:`Guardiões dos celeiros`,summary:`Família nobre de Valoria dividida entre a corte e os compromissos assumidos com comunidades rurais.`,description:`A riqueza Arden vem de diques, moinhos e armazéns, não de minas. Após uma fome, a casa aceitou limites públicos ao preço dos grãos. Ilyra Arden, herdeira e capitã, tenta preservar esse pacto enquanto parentes pressionam por expansão territorial.`,category:`Casa nobre`,status:`Ativa`,lineage:`Arden`,kingdom:`Valoria`,origin:`Valóris`,traits:`Administração rural, cavalaria leve e negociação`,motto:`Primeiro a colheita, depois a coroa.`,members:[`Ilyra Arden`],relations:[{label:`Ilyra Arden`,to:`/personagens/ilyra-arden`},{label:`Valoria`,to:`/reinos/valoria`}]})],E={kayler:{genealogyId:`kayler`,inheritance:[`Dom de tempestade transmitido pelo sangue`,`Sinais frequentes: cabelo branco e olhos violetas`,`Manifestação pode permanecer silenciosa por gerações`],vows:[`Corrente Celeste`,`Juramento Arcano contra governo dos povos`],survival:[`Normus deixou artefatos e pacto`,`Sirius é o último membro conhecido, não uma prova de extinção total`],rivalries:[`Coroas que buscavam domínio`,`Divergências filosóficas com o controle Nimbus`]},nimbus:{genealogyId:`nimbus`,inheritance:[`Magia de vontade, percepção e deslocamento`,`Olhos violetas e cabelo branco como sinais recorrentes`,`Expressão do dom varia com disciplina e medo`],vows:[`Corrente Escarlate`,`Proteção sem soberania`],survival:[`A casa escolheu combate aberto durante a perseguição`,`Registros oficiais declaram extinção, mas não comprovam todos os ramos`],rivalries:[`Conflitos internos por controle`,`Conselho dos Sete Reis`]},rivs:{genealogyId:`rivs`,inheritance:[`Afinidade com água, neblina, gelo e memória`,`Sinais físicos compartilhados pelas três Casas`,`Possível herança recessiva não confirmada`],vows:[`Corrente Profunda`,`Conhecimento deve continuar sem possuir quem o guarda`],survival:[`Bibliotecas evacuadas`,`Ramos e arquivos desapareceram juntos`],rivalries:[`Coroas interessadas nos arquivos`,`Necromantes em busca de memória preservada`]},bellatrix:{genealogyId:`bellatrix`,inheritance:[`Não possui magia hereditária`,`Título de guardião depende de eleição e serviço`],vows:[`A Chama sem Coroa`,`Abrigo acima de trono`],survival:[`Cifras de inventário esconderam descendentes`,`Fortaleza do Véu preserva ramos públicos`],rivalries:[`Coroas expansionistas`,`Fortalezas que rejeitam coordenação`]},arden:{genealogyId:`valoria`,inheritance:[`Terras e deveres de dique`,`Sucessão limitada pelas Sete Pontes`],vows:[`Primeiro a colheita, depois a coroa`],survival:[`Poder econômico distribuído por moinhos e armazéns`],rivalries:[`Ala cortesã contra pactos agrários`,`Ilyra contra parentes expansionistas`]}},D=T.map(e=>{let{additionalRelations:t=[],...n}=w[e.id];return{...e,...E[e.id],...n,relations:[...e.relations,...t]}}),O=p([e({id:`vyrasul`,name:`Vyrasul`,subtitle:`O dragão branco de Winterfeld`,summary:`Um dos três únicos dragões conhecidos, criatura natural que escolheu permanecer nas geleiras de Winterfeld.`,description:`Vyrasul não governa, não recebe tributos e não responde à coroa. O dragão foi encontrado ferido por gigantes do norte e sobreviveu graças a uma trégua entre caçadores e curadores. Desde então, ataca grandes ameaças próximas às geleiras, mas ignora conflitos políticos. Seu sopro retira calor rapidamente; usá-lo por longos períodos o deixa vulnerável.`,category:`Dragão`,status:`Vivo — avistado`,origin:`Desconhecida`,location:`Geleiras de Winterfeld`,race:`Dragão`,threat:`Lendária`,habitat:`Geleiras e picos`,relations:[{label:`Winterfeld`,to:`/reinos/winterfeld`}],curiosities:[`Marcas de voo sugerem que evita assentamentos durante migrações de animais.`]}),e({id:`alcarion`,name:`Alcarion`,subtitle:`O dragão das marés ausentes`,summary:`Segundo dos três dragões conhecidos; desapareceu sobre o Mar das Estrelas há mais de um século.`,description:`Relatos descrevem escamas escuras com brilho esverdeado e hábitos costeiros. Alcarion alimentava-se de grandes peixes e descansava em ilhas sem população. Seu desaparecimento coincide com uma anomalia marítima, mas não há evidência de morte ou cativeiro.`,category:`Dragão`,status:`Desaparecido`,origin:`Arquipélago das Brumas`,location:`Último registro: Mar das Estrelas`,race:`Dragão`,threat:`Lendária`,habitat:`Ilhas e mar aberto`,relations:[{label:`Eldemar`,to:`/reinos/eldemar`}],curiosities:[`Nenhum ovo de dragão foi autenticado por estudiosos.`]}),e({id:`mhazir`,name:`Mhazir`,subtitle:`O dragão de cobre`,summary:`Terceiro dragão conhecido, desaparecido após cruzar as Montanhas Cinzentas durante a Caça às Bruxas.`,description:`Mhazir possuía escamas de cobre fosco e caçava grandes herbívoros nas terras áridas. Uma cicatriz na asa direita tornava seu voo reconhecível. A última rota registrada segue para além do limite cartografado; teorias que o colocam à frente de um império são rejeitadas por falta de evidência e por contradizerem o comportamento natural dos dragões.`,category:`Dragão`,status:`Desaparecido`,origin:`Deserto de Zharak`,location:`Último registro: Montanhas Cinzentas`,race:`Dragão`,threat:`Lendária`,habitat:`Desertos e planaltos`,relations:[{label:`Montanhas Cinzentas`,to:`/reinos/montanhas-cinzentas`}],curiosities:[`Fragmentos atribuídos às suas escamas eram minério de cobre comum.`]}),e({id:`grifo-das-alturas`,name:`Grifo das Alturas`,subtitle:`Sentinela dos penhascos`,summary:`Predador alado territorial das montanhas, admirado por cavaleiros e temido por criadores de cabras.`,description:`Grifos formam pares sazonais e defendem ninhos em paredões inacessíveis. Não aceitam montaria; histórias de cavaleiros de grifo são alegorias militares. Sinos agudos e rebanhos cobertos reduzem ataques sem exigir extermínio.`,category:`Fera alada`,status:`Estável`,location:`Cordilheiras de Avernor`,race:`Fera`,threat:`Alta`,habitat:`Penhascos e montanhas`,relations:[{label:`Winterfeld`,to:`/reinos/winterfeld`}]}),e({id:`hidra-dos-pantanos`,name:`Hidra dos Pântanos`,subtitle:`A fome que se divide`,summary:`Réptil de múltiplos pescoços cuja regeneração torna combates prolongados quase impossíveis.`,description:`A hidra não cria cabeças infinitas: cada perda consome reservas corporais e exige alimento abundante. Caçadores experientes evitam feri-la e preferem conduzi-la para áreas sem presas. Fogo descontrolado é perigoso, pois pântanos secos podem queimar por meses.`,category:`Fera lacustre`,status:`Rara`,location:`Pântanos meridionais`,race:`Fera`,threat:`Extrema`,habitat:`Pântanos e lagos rasos`,relations:[{label:`Mar Interior`,to:`/locais/mar-interior`}]}),e({id:`kraken-de-eldemar`,name:`Kraken de Eldemar`,subtitle:`O peso sob as rotas`,summary:`Cefalópode colossal registrado em águas profundas, responsável por mudanças sazonais nas rotas mercantes.`,description:`O nome singular esconde a incerteza: estudiosos não sabem se os avistamentos pertencem ao mesmo animal. A criatura parece seguir correntes frias e cardumes. Navios que desligam sinos de casco e evitam despejar vísceras reduzem encontros.`,category:`Fera marinha`,status:`Avistamentos esporádicos`,location:`Mar das Estrelas`,race:`Fera`,threat:`Lendária`,habitat:`Mar profundo`,relations:[{label:`Eldemar`,to:`/reinos/eldemar`}]}),e({id:`cervo-do-nevoeiro`,name:`Cervo do Nevoeiro`,subtitle:`Guia das clareiras`,summary:`Grande herbívoro da Floresta Antiga cuja pelagem reflete tons do ambiente úmido.`,description:`A capacidade de parecer desaparecer vem de pelos translúcidos, silêncio e conhecimento das trilhas, não de teletransporte. Elfos observam seus deslocamentos para prever fungos tóxicos e alterações na água.`,category:`Fauna antiga`,status:`Protegido`,location:`Floresta Antiga`,race:`Animal`,threat:`Baixa`,habitat:`Bosques úmidos`,relations:[{label:`Sylvaris`,to:`/reinos/sylvaris`}]}),e({id:`lobo-de-vidro`,name:`Lobo de Vidro`,subtitle:`Caçador das salinas`,summary:`Canídeo de pelos rígidos cobertos por sais minerais, adaptado às noites frias das terras áridas.`,description:`Os pelos tilintam quando o animal corre, razão pela qual caça contra o vento. Bandos evitam fogo e assentamentos grandes, mas seguem caravanas debilitadas. A remoção dos depósitos minerais causa feridas e é proibida por caçadores responsáveis.`,category:`Predador terrestre`,status:`Estável`,location:`Deserto de Zharak`,race:`Animal`,threat:`Moderada`,habitat:`Salinas e desertos`,relations:[{label:`Deserto de Zharak`,to:`/locais/deserto-de-zharak`}]}),e({id:`vigia-de-pedra`,name:`Vigia de Pedra`,subtitle:`Colônia das cavernas profundas`,summary:`Organismo colonial mineralizado que reage a vibrações e é frequentemente confundido com estátua.`,description:`Cada “vigia” é formado por milhares de pequenos seres que depositam uma carapaça comum. Vibrações violentas provocam o fechamento súbito da colônia, capaz de bloquear túneis. Mineiros anões usam batidas ritmadas para anunciar passagem.`,category:`Organismo colonial`,status:`Raro`,location:`Kar-Dûm`,race:`Fauna subterrânea`,threat:`Moderada`,habitat:`Cavernas minerais`,relations:[{label:`Kar-Dûm`,to:`/reinos/kar-dum`}]})],n),k=p([e({id:`noite-das-doze-adagas`,name:`A Noite das Doze Adagas`,subtitle:`Regicídio ou última defesa?`,summary:`Relato sobre os doze conselheiros que encerraram a tirania de Marcellus Veyron e desapareceram antes do amanhecer.`,description:`Versões populares afirmam que doze lâminas atingiram o rei ao mesmo tempo. Arquivos médicos indicam menos ferimentos, sugerindo que “doze adagas” representa o conselho inteiro. A ausência das armas permitiu que cada reino reivindicasse um herói entre os conspiradores.`,category:`Lenda política`,status:`Parcialmente comprovada`,period:`Ano 158`,location:`Antiga capital de Avernor`,relations:[{label:`A Queda da Coroa`,to:`/historia/queda-coroa`}]}),e({id:`arquivo-submerso`,name:`O Arquivo Submerso`,subtitle:`A última memória dos Rivs`,summary:`História de uma biblioteca escondida sob águas que só recuam diante de alguém da linhagem Rivs.`,description:`Mapas Rivs indicam depósitos de documentos em ilhas fluviais, mas nenhum confirma uma biblioteca submarina. É possível que “águas que recuam” seja instrução para operar comportas. A lenda persiste porque caçadores nunca recuperaram os registros centrais da família.`,category:`Lenda arcana`,status:`Não localizado`,period:`Caça às Bruxas`,location:`Mar Interior`,relations:[{label:`Casa Rivs`,to:`/casas/rivs`}]}),e({id:`pacto-dos-descendentes`,name:`O Pacto dos Descendentes`,subtitle:`A promessa de Normus e Aelwen`,summary:`Acordo reservado entre Normus e Aelwen que protegeu o descendente Kayler sem transformar qualquer herdeiro em propriedade do outro.`,description:`O registro público confirma abrigo concedido a Sirius e a existência de obrigações ainda vigentes, mas não publica seu alcance, condições ou contrapartidas. Canções românticas o tratam como promessa de casamento; essa interpretação não consta nos fragmentos autênticos. Elara e Sirius preservam liberdade de escolha. Qualquer dever adicional permanece desconhecido fora da custódia autorizada de Sylvaris.`,category:`Pacto secreto`,status:`Ativo e incompleto`,truthStatus:`redacted`,knowledgeStatus:`secret`,period:`Fim da Era das Coroas`,location:`Sylvaris`,relations:[{label:`Normus Kayler`,to:`/personagens/normus-kayler`},{label:`Rainha Aelwen`,to:`/personagens/rainha-aelwen`},{label:`Elara`,to:`/personagens/elara`},{label:`Sirius Kayler`,to:`/personagens/sirius-kayler`}]}),e({id:`sinos-do-mar-de-cinzas`,name:`Os Sinos do Mar de Cinzas`,subtitle:`O aviso que sobe da água`,summary:`Marinheiros relatam sinos sob a superfície antes de nevoeiros que desorientam bússolas.`,description:`O som pode vir de rochas ocas movidas por correntes. Ainda assim, mapas de Eldemar tratam o fenômeno como aviso confiável e exigem redução de velas. A lenda ganhou tom sobrenatural após um navio reaparecer sem tripulação.`,category:`Lenda marítima`,status:`Fenômeno observado`,location:`Mar de Cinzas`,relations:[{label:`Eldemar`,to:`/reinos/eldemar`}]}),e({id:`barca-sem-remador`,name:`A Barca sem Remador`,subtitle:`O resgate que ninguém reivindicou`,summary:`Pilotos de Eldemar narram que uma pequena barca surge durante tempestades para marcar o canal seguro e desaparece antes do amanhecer.`,description:`A Barca sem Remador aparece em depoimentos separados por quase dois séculos: uma embarcação baixa, com vela recolhida e uma lanterna protegida, cruzaria à frente de navios perdidos até o Farol das Sete Marés. Nenhum relato confiável afirma que a barca navegue contra corrente ou sem tripulação; a expressão provavelmente nasceu porque ninguém era visto acima da amurada. Livros de resgate registram embarcações de pilotos que operavam sem identificação para evitar represálias de contrabandistas. A tradição, portanto, pode preservar uma rede humana apagada dos registros, embora sua continuidade até o presente seja baseada em rumor.`,category:`Lenda marítima`,status:`Contestada`,truthStatus:`disputed`,knowledgeStatus:`rumor`,confidence:`low`,period:`Relatos entre a Era das Coroas e 1204 d.C.`,location:`Costa de Eldemar`,archivalOverview:`O Arquivo conserva a lenda como memória de resgates anônimos, sem declarar uma embarcação sobrenatural ou um piloto imortal.`,provenance:`Cinco livros de bordo citam uma luz baixa conduzindo navios; apenas dois descrevem uma barca, e nenhum foi escrito pela mesma tripulação.`,publicKnowledge:[`O padrão de luz corresponde a sinais costeiros antigos e os relatos se concentram no canal meridional.`],knowledgeGaps:[`A identidade dos pilotos, a quantidade de embarcações e a existência de uma tradição organizada permanecem não registradas.`],culturalReadings:[`Marinheiros a tratam como dívida de resgate; sacerdotes do Horizonte falam em promessa que continua navegando.`],historicalSources:[`Livros de resgate de Eldemar`,`Depoimentos do cais sul`,`Códigos antigos de lanterna`],disputedClaims:[`A afirmação de que a barca atravessa tempestades sem tripulação não possui testemunho próximo o bastante para confirmação.`],narrativeImportance:`Oferece uma lenda sobre solidariedade clandestina e permite investigar quem foi apagado dos registros marítimos.`,imageBrief:`Barca pequena vista de um navio maior durante tempestade, lanterna baixa e Farol das Sete Marés distante, sem fantasma visível.`,sections:[{title:`O padrão dos avistamentos`,body:`As ocorrências preservadas compartilham canal, luz baixa e desaparecimento antes da identificação, mas divergem sobre casco, cor e distância.`},{title:`Hipótese dos pilotos ocultos`,body:`Códigos de resgate demonstram que pilotos já navegaram sem brasão para proteger famílias ameaçadas por redes de contrabando.`},{title:`O que permanece desconhecido`,body:`Não existe casco recuperado, lista de tripulantes ou cadeia documental que prove continuidade entre os relatos.`},{title:`Leitura dos cais`,body:`Tripulações deixam uma medida de óleo no farol depois de sobreviver a uma tormenta, gesto de gratidão e não tributo obrigatório.`}],relations:[{label:`Eldemar`,to:`/reinos/eldemar`},{label:`Farol das Sete Marés`,to:`/locais/farol-das-sete-mares`},{label:`Juramento do Horizonte`,to:`/religioes/juramento-do-horizonte`}]}),e({id:`sino-sob-a-geleira`,name:`O Sino sob a Geleira`,subtitle:`Um som contado pelos gigantes`,summary:`Cantos do norte descrevem um toque grave sob o gelo quando uma passagem antiga se torna perigosa.`,description:`O Sino sob a Geleira não é conhecido por observação pública direta. Comunidades gigantes de dois vales preservam cantos sobre uma pedra sonora enterrada pelo avanço do gelo, capaz de devolver vibrações diferentes quando a geleira se rompe por dentro. Guias humanos passaram a chamar o fenômeno de sino, embora os cantos não descrevam metal, torre ou mão que o faça soar. Medições recentes confirmam estalos de baixa frequência antes de alguns colapsos, mas não localizam um objeto. A versão de que o som anuncia a morte de reis surgiu em baladas meridionais e é rejeitada pelos povos que conservam a tradição.`,category:`Tradição dos gigantes`,status:`Conhecida apenas por determinado povo`,truthStatus:`documented`,knowledgeStatus:`people-only`,confidence:`medium`,period:`Anterior aos calendários de Winterfeld`,location:`Geleiras setentrionais`,archivalOverview:`O registro público apresenta a tradição como conhecimento territorial gigante parcialmente apoiado por observação geológica.`,provenance:`Dois ciclos de canto foram traduzidos com consentimento dos vales; sensores de Winterfeld registraram vibrações semelhantes, sem identificar sua fonte exata.`,publicKnowledge:[`O gelo profundo produz sons antes de certas rupturas, e guias gigantes ajustam rotas segundo ritmo, direção e duração.`],knowledgeGaps:[`A localização da pedra sonora, se ela existe como objeto distinto, permanece conhecida apenas pelos cantores ou pode ter sido perdida.`],culturalReadings:[`Gigantes leem o som como linguagem do território; humanos tendem a convertê-lo em presságio político.`],historicalSources:[`Cantos do Vale Sonoro`,`Cadernos de guias de Winterfeld`,`Medições do degelo de 1203`],disputedClaims:[`Não há evidência de que o fenômeno responda a coroas, guerras ou à presença de Vyrasul.`],narrativeImportance:`Reconhece conhecimento gigante sem apropriá-lo e pode orientar expedições quando instrumentos humanos oferecem dados incompletos.`,imageBrief:`Corte visual de geleira azul profunda com gigantes escutando a pedra pelo chão, nenhuma torre ou sino metálico literal.`,sections:[{title:`A tradição preservada`,body:`Os cantos descrevem escuta coletiva, comparação entre invernos e responsabilidade de fechar uma passagem antes do desastre.`},{title:`O registro de Winterfeld`,body:`Vigias confirmam sons graves e deslocamentos internos, mas seus instrumentos cobrem apenas uma fração das geleiras.`},{title:`Limite de acesso`,body:`Versos, nomes de rotas e locais de escuta não foram publicados porque pertencem às comunidades que os utilizam.`},{title:`A lenda meridional`,body:`Baladas sobre reis mortos são tardias, deslocadas do norte e rejeitadas como apropriação por cantores gigantes.`}],relations:[{label:`Winterfeld`,to:`/reinos/winterfeld`},{label:`Gigantes`,to:`/povos/gigantes`},{label:`Mosteiro da Brasa Tardia`,to:`/locais/mosteiro-da-brasa-tardia`},{label:`Vyrasul`,to:`/criaturas/vyrasul`}]}),e({id:`nona-porta`,name:`A Nona Porta`,subtitle:`A passagem que só existe quando uma obra deve parar`,summary:`Aprendizes de Kar-Dûm contam que toda grande escavação possui uma nona saída reservada à decisão de abandonar o trabalho.`,description:`A lenda da Nona Porta nasceu da arquitetura redundante de Kar-Dûm. Salões públicos costumam possuir oito acessos nomeados, mas histórias de oficina afirmam que mestres responsáveis sempre mantêm uma nona passagem fora das plantas cerimoniais. O Arquivo de Pedra confirma rotas de evacuação omitidas de cópias abertas, porém não reconhece uma porta universal nem um túnel que conecte todos os salões. Para aprendizes, “abrir a nona porta” significa aceitar que custo, orgulho e tradição não justificam continuar uma obra insegura. Seladores reinterpretaram a expressão como acesso secreto ao Véu; essa leitura permanece contestada e produziu invasões perigosas.`,category:`Lenda de ofício`,status:`Metáfora documentada; passagem contestada`,truthStatus:`disputed`,knowledgeStatus:`people-only`,confidence:`medium`,period:`Posterior aos primeiros códigos dos Nove Salões`,location:`Kar-Dûm`,archivalOverview:`O Arquivo registra a Nona Porta como princípio de segurança e tradição de oficina, não como estrutura única comprovada.`,provenance:`Provérbios, placas de evacuação e atas de obras interrompidas demonstram uso contínuo da expressão entre ofícios.`,publicKnowledge:[`Rotas de socorro são omitidas de mapas públicos e toda obra profunda precisa prever abandono seguro.`],knowledgeGaps:[`A origem do número nove e a primeira oficina a usar a expressão estão perdidas.`],culturalReadings:[`Engenheiros falam em humildade material; Seladores procuram um limiar literal que os arquivos não confirmam.`],historicalSources:[`Código das Profundezas`,`Placas de obras interrompidas`,`Provérbios dos aprendizes`],disputedClaims:[`Nenhuma evidência sustenta uma porta capaz de atravessar todos os salões ou tocar diretamente o Véu.`],narrativeImportance:`Converte segurança em valor cultural e cria conflito entre leitura técnica, ambição ritual e exploração de ruínas.`,imageBrief:`Galeria anã com oito arcos iluminados e uma abertura de evacuação discreta, ferramentas abandonadas com ordem e nenhuma porta mágica.`,sections:[{title:`A expressão de oficina`,body:`Mestres a empregam quando uma equipe precisa suspender trabalho sem transformar retirada em desonra.`},{title:`As rotas omitidas`,body:`Passagens reais existem, mas sua posição permanece conhecida apenas pelos ofícios responsáveis para impedir sabotagem.`},{title:`A leitura dos Seladores`,body:`A busca por uma estrutura universal ignora diferenças de idade, função e engenharia entre os salões.`},{title:`O ensinamento preservado`,body:`A lenda recorda que a obra mais valiosa pode ser a saída construída antes que alguém precise dela.`}],relations:[{label:`Kar-Dûm`,to:`/reinos/kar-dum`},{label:`Arquivo de Pedra`,to:`/locais/arquivo-de-pedra`},{label:`Guerra dos Túneis Vazios`,to:`/guerras/guerra-dos-tuneis-vazios`},{label:`Seladores`,to:`/faccoes/seladores`}]})],c),A={"cancao-do-primeiro-ceu":{originMyth:`A Vastidão Silenciosa é rompida quando uma voz pronuncia sete nomes.`,creationView:`Pedra, mar, fogo, vento, vida, morte e memória seriam fragmentos da ruptura; povos discordam se representam matéria, virtudes ou metáforas.`,deathView:`A morte é um dos fragmentos e, portanto, limite constitutivo, não erro a ser apagado.`,magicView:`Mana seria o eco invisível do sétimo fragmento, hipótese religiosa compatível com alguns fenômenos, mas não demonstrada.`,symbols:[`Círculo rompido em sete pontos`,`Céu sem estrelas`],rituals:[`Canto responsorial em sete vozes`,`Silêncio após o sétimo verso`],sacredDates:[`Noite sem Lua mais próxima do equinócio — data varia por região`],clergy:[`Não há sacerdócio comum; cantores, cronistas e filósofos preservam versões`],sacredPlaces:[`Ruínas associadas ao Primeiro Céu — atribuição contestada`],ancientTexts:[`Fragmentos da Canção`,`Comentário das Sete Margens`],heresies:[`Doutrina do Oitavo Fragmento`,`Leitura que identifica a voz com um rei humano`],regionalDifferences:[`Sylvaris trata os nomes como relações`,`Kar-Dûm os compara a responsabilidades materiais`,`Vertentes humanas os aproximam dos Sete Nomes`],politicalImpact:[`Coroas tentaram associar-se à voz criadora`,`Facções usam o sétimo nome para justificar abertura ou silêncio`],contradictions:[`As versões discordam sobre a ordem dos fragmentos`,`Algumas não mencionam mana`],modernInterpretations:[`Modelo poético de uma antiga Fratura`,`Memória cultural de fenômeno astronômico`],possiblyTrue:[`Diversas culturas preservam número e ruptura semelhantes`],unconfirmed:[`Identidade da voz`,`Existência literal do Primeiro Céu`,`Oitavo fragmento`]},"primeira-tempestade":{originMyth:`Uma tempestade violeta de sete noites teria marcado três mortais, ancestrais de Kayler, Nimbus e Rivs.`,creationView:`Não cria o mundo; explica a entrada pública da mana em certas linhagens.`,deathView:`Os mortos da tempestade retornariam ao Eco, mas essa formulação aparece apenas em cópias tardias.`,magicView:`Magia verdadeira seria herança dos três marcados, coerente com a existência das Casas sem provar a genealogia mítica.`,symbols:[`Três figuras sob um raio violeta`,`Sete marcas de chuva`],rituals:[`Vigília de sete horas`,`Três recipientes com água, cinza e metal`],sacredDates:[`Data original perdida; Casas usavam calendários diferentes`],clergy:[`Guardadores das três Correntes, hoje dispersos`],sacredPlaces:[`Locais de queda reivindicados por mais de uma região`],ancientTexts:[`Cântico dos Três Marcados`,`Tábuas da Chuva Fria`],heresies:[`Quarta pessoa marcada — rejeitada pelo cânone e sem prova`],regionalDifferences:[`Kayler enfatiza céu`,`Nimbus enfatiza vontade`,`Rivs enfatiza água`],politicalImpact:[`Usada para legitimar e depois perseguir as Casas`],contradictions:[`Ruínas “surgidas” podem ser apenas estruturas reveladas por erosão`],modernInterpretations:[`Evento climático com manifestação arcana`,`Mito posterior para unificar linhagens distintas`],possiblyTrue:[`Registros distantes convergem sobre céu violeta e água luminosa`],unconfirmed:[`Identidade dos três mortais`,`Local da tempestade`]},"doutrina-tres-correntes":{originMyth:`As Casas interpretam a Primeira Tempestade como origem de três responsabilidades complementares.`,creationView:`Aceita a Canção do Primeiro Céu como linguagem ética, sem exigir leitura literal.`,deathView:`A pessoa retorna ao Eco e não pode ser possuída por vivos.`,magicView:`Dom hereditário, limitado, incapaz de conferir direito de governo.`,symbols:[`Raio aberto`,`Serpente de olhos opostos`,`Três ondas concêntricas`],rituals:[`Iniciação dos três recipientes`,`Renovação do Juramento Arcano`],sacredDates:[`Vigílias familiares preservadas de modo fragmentário`],clergy:[`Mentores de linhagem, não sacerdotes soberanos`],sacredPlaces:[`Antigas casas e arquivos, em grande parte destruídos`],ancientTexts:[`Juramento Arcano`,`Comentários das Correntes`],heresies:[`Doutrina da Coroa Arcana, rejeitada pelas três Casas`],regionalDifferences:[`Cada Casa enfatiza sua Corrente sem negar as demais`],politicalImpact:[`Fundamentou recusas de Normus`,`Foi tratada como conspiração por perseguidores`],contradictions:[`Nimbus divergiu internamente sobre proteção e controle`],modernInterpretations:[`Código ético de poder hereditário`],possiblyTrue:[`Documentos confirmam o Juramento e as três linhagens`],unconfirmed:[`Origem sobrenatural das Correntes`]},"metamorfose-do-eco":{originMyth:`Alguns bruxos teriam aprendido a escutar a forma animal contida no Eco.`,creationView:`Não oferece cosmogonia própria.`,deathView:`Permanecer para sempre em forma animal é descrito como perda de identidade, não morte literal.`,magicView:`Aptidão rara de sangue, dependente de treino e mana.`,symbols:[`Olhos violetas em máscara animal`,`Duas marcas brancas`],rituals:[`Preparação em círculo seguro`,`Registro de roupas e objetos deixados`],sacredDates:[`Nenhuma`],clergy:[`Mentores das Casas; nenhum ofício sobreviveu publicamente`],sacredPlaces:[`Locais de treino perdidos`],ancientTexts:[`Bestiários de forma — fragmentários`],heresies:[`Transformação ilimitada`,`Animais sem marcas como prova de bruxaria`],regionalDifferences:[`Relatos Kayler privilegiam aves e predadores de tempestade; generalização não confirmada`],politicalImpact:[`Foi usada para acusar animais e viajantes durante a perseguição`],contradictions:[`Nem todo relato distingue metamorfose de ilusão`],modernInterpretations:[`Fenômeno arcano raro com forte risco psicológico`],possiblyTrue:[`Testemunhos confiáveis descrevem olhos violetas e marcas brancas`],unconfirmed:[`Formas de Sirius`,`Número histórico de praticantes`]},"credo-cicatriz-vermelha":{originMyth:`Khar-Ul fere o céu e da abertura caem elementos que formam vida, memória e sobrevivência.`,creationView:`O mundo nasce ferido e viver significa cuidar da ferida sem fingir que nunca existiu.`,deathView:`Mortos seguem ao Acampamento Além do Horizonte Vermelho pela fumaça do fogo comunal.`,magicView:`Magia de sangue não pertence naturalmente aos orcs; prodígios do credo são metáforas e tradição.`,symbols:[`Cicatriz vermelha`,`Brasa em tigela de pedra`],rituals:[`Nome de Brasa`,`Última Fumaça`,`Água Compartilhada`],sacredDates:[`Festival das Cicatrizes Contadas`],clergy:[`Guardadores de brasa e testemunhas de nome`],sacredPlaces:[`Poços de fundação`,`Lareiras comunais`],ancientTexts:[`Tradição oral; versões escritas são traduções recentes`],heresies:[`Sangue como direito absoluto de chefia`],regionalDifferences:[`Poços veneram Maara-Ghesh`,`Estradas invocam Zhur-Kaan`],politicalImpact:[`Nomes e juramentos definem mandato de emissários`],contradictions:[`Clãs divergem se Khar-Ul abriu o céu por escolha ou defesa`],modernInterpretations:[`Memória de migração por desastre`],possiblyTrue:[`Ritos e estrutura social são amplamente documentados`],unconfirmed:[`Existência literal das entidades`]},"memoria-primeira-raiz":{originMyth:`Ilyndra desperta o mundo de um sonho sem estação por meio de uma raiz que atravessa tempos e memórias.`,creationView:`Criação é despertar e relação contínua, não fabricação concluída.`,deathView:`Mortos tornam-se Folhas de Memória ligadas a lugares cuidados.`,magicView:`A Vontade da Floresta é relação ecológica e ritual, não magia individual ensinável.`,symbols:[`Raiz atravessando lua`,`Copa vazia`],rituals:[`Jardim memorial`,`Casamento das Duas Sombras`,`Vigília da Copa`],sacredDates:[`Primeira queda anual de folhas prateadas`],clergy:[`Guardiões de jardim e cantores de memória`],sacredPlaces:[`Primeira Raiz — localização ritual, não cartográfica`,`Jardins de Lethariel`],ancientTexts:[`Cantos de Ilyndra`,`Registro das Folhas`],heresies:[`Coroa como proprietária da floresta`],regionalDifferences:[`Bosques de margem aceitam mais símbolos estrangeiros`],politicalImpact:[`Limita venda de território e poder real`],contradictions:[`Versões discordam se Ilyndra é pessoa, árvore ou verbo`],modernInterpretations:[`Sistema de memória ecológica`],possiblyTrue:[`Práticas de manejo produzem respostas ambientais mensuráveis`],unconfirmed:[`Consciência literal da Primeira Raiz`]},"sete-golpes-primeira-forja":{originMyth:`Dorh-Mael desfere sete golpes que ordenam matéria, água, vida, memória e destino.`,creationView:`O mundo é obra inacabada, e toda criação gera dever de reparo.`,deathView:`Parte da pessoa permanece nas obras nomeadas; isso é memória social, não necromancia confirmada.`,magicView:`Qualidade excepcional não é magia; anões não possuem dom racial arcano.`,symbols:[`Martelo sobre sete ondas`,`Bigorna incompleta`],rituals:[`Sete Metais`,`Funeral da Ferramenta Nomeada`],sacredDates:[`Festival do Oitavo Golpe`],clergy:[`Sacerdotes-ferreiros e verificadores de medida`],sacredPlaces:[`Primeiras forjas de Thur-Kar`],ancientTexts:[`Placas dos Sete Golpes`],heresies:[`Oitavo Golpe como inovação contínua, segundo tradicionalistas`],regionalDifferences:[`Salões de água enfatizam o quarto golpe; forjas, o terceiro`],politicalImpact:[`Sustenta responsabilidade técnica e disputas sobre inovação`],contradictions:[`Nenhuma placa antiga contém texto idêntico`],modernInterpretations:[`Metáfora de especialização material`],possiblyTrue:[`Ritos e medidas preservam conhecimento antigo`],unconfirmed:[`Dorh-Mael como entidade literal`]},"pilares-adormecidos":{originMyth:`Montanhas são ancestrais que repousam e registram cada passagem sobre seus corpos.`,creationView:`Relevo e ancestralidade são uma mesma memória em escalas diferentes.`,deathView:`Mortos retornam ao vale e passam a integrar o canto territorial.`,magicView:`Percepção de vibração é adaptação e treino; não magia racial.`,symbols:[`Três picos como ombros`,`Círculo de pedras aberto ao norte`],rituals:[`Canto dos Passos`,`Círculo do Degelo`],sacredDates:[`Primeiro grande degelo`],clergy:[`Cantores de vale e testemunhas de tratado`],sacredPlaces:[`Pilares e passos associados às linhagens`],ancientTexts:[`Não há texto central; cantos são vinculados ao lugar`],heresies:[`Transportar integralmente um canto para arquivo humano`],regionalDifferences:[`Vales interpretam o Despertar como movimento ou cobrança`],politicalImpact:[`Tratados dependem da preservação dos marcos`],contradictions:[`Traduções confundem montanha ancestral e pessoa`],modernInterpretations:[`Sistema territorial de arquivo oral`],possiblyTrue:[`Gigantes detectam mudanças de gelo antes de observadores humanos`],unconfirmed:[`Despertar físico das montanhas`]}},j={"caminho-das-raizes":{originMyth:`Deriva da Memória da Primeira Raiz e de práticas anteriores à monarquia.`,creationView:`Viver é ocupar temporariamente uma relação que continuará depois da pessoa.`,deathView:`Mortos tornam-se memória vinculada a jardins e lugares cuidados.`,magicView:`Não concede magia; distingue ritual, ecologia e sangue arcano.`,symbols:[`Raiz em círculo aberto`,`Folha de prata`],rituals:[`Jardins memoriais`,`Estação sem colheita após luto`],sacredDates:[`Vigília da Copa Silenciosa`],clergy:[`Guardiões de jardim, sem casta sacerdotal única`],sacredPlaces:[`Jardins de Lethariel`,`Bosques memoriais`],ancientTexts:[`Registro das Folhas`],heresies:[`Propriedade real da floresta`],regionalDifferences:[`Porto Verde adapta ritos para famílias estrangeiras`],politicalImpact:[`Limita exploração e coroa`],contradictions:[`Guardadores discordam sobre proteção a Normus`],modernInterpretations:[`Ética ecológica e arquivo vivo`],possiblyTrue:[`Efeitos de manejo são verificáveis`],unconfirmed:[`Consciência sobrenatural da floresta`]},"culto-da-brasa-comum":{originMyth:`Não possui criação exclusiva; nasceu da manutenção de fogos públicos durante a Fome dos Sete Invernos.`,creationView:`O mundo não é possuído por uma casa; recursos só permanecem vivos quando compartilhados.`,deathView:`O nome do morto é lido enquanto seu lugar à mesa é oferecido a quem precisa.`,magicView:`Rejeita milagres como prova de autoridade.`,symbols:[`Brasa entre duas mãos`],rituals:[`Cozinha pública`,`Auditoria do último saco`],sacredDates:[`Noite da Última Panela antes do inverno`],clergy:[`Administradores de abrigo e cozinheiros juramentados`],sacredPlaces:[`Templos-cozinha e depósitos`],ancientTexts:[`Livros de estoque da Fome`],heresies:[`Fogo exclusivo de famílias nobres`],regionalDifferences:[`Valoria enfatiza grão; Winterfeld, abrigo térmico`],politicalImpact:[`Confronta controle aristocrático de doações`],contradictions:[`Alguns templos acumularam riqueza contrária ao princípio`],modernInterpretations:[`Religião cívica de segurança alimentar`],possiblyTrue:[`Origem histórica documentada`],unconfirmed:[`Nenhuma afirmação sobrenatural central`]},"nove-ecos":{originMyth:`Toda ação sobre a pedra retorna por nove caminhos de consequência.`,creationView:`Construir é participar de um mundo material que responde.`,deathView:`Obra e responsabilidade preservam o nome do morto.`,magicView:`Escuta da Pedra é técnica, não feitiço.`,symbols:[`Nove círculos em torno de uma abertura`],rituals:[`Resposta pública dos nove especialistas`],sacredDates:[`Calibração das Nove Bigornas`],clergy:[`Especialistas responsáveis, não sacerdotes milagrosos`],sacredPlaces:[`Câmara das Nove Bigornas`],ancientTexts:[`Código dos Ecos`],heresies:[`Abrir sem registrar dívida`],regionalDifferences:[`Cada salão prioriza eco ligado à própria função`],politicalImpact:[`Concede veto técnico a água e ventilação`],contradictions:[`Reformistas discutem um décimo eco social`],modernInterpretations:[`Ética de engenharia`],possiblyTrue:[`Consequências materiais são documentadas`],unconfirmed:[`Eco como consciência literal da pedra`]},"juramento-do-horizonte":{originMyth:`Primeiras tripulações teriam retornado porque nomes e obrigações as mantiveram ligadas à margem.`,creationView:`O horizonte separa e conecta; partir só é legítimo quando o retorno é assumido.`,deathView:`Promessas de mortos passam por audiência antes de serem encerradas.`,magicView:`Não concede navegação sobrenatural.`,symbols:[`Linha do horizonte atravessando placa de cera`],rituals:[`Registro antes da partida`,`Audiência de retorno`],sacredDates:[`Primeira maré segura da estação`],clergy:[`Escribas de cais e testemunhas de tripulação`],sacredPlaces:[`Casas de cera nos portos`],ancientTexts:[`Primeiros livros de viagem`],heresies:[`Perdão automático a capitães nobres`],regionalDifferences:[`Eldemar usa placas; vilas menores, cordas de nós`],politicalImpact:[`Obrigações podem impedir sucessão de capitão`],contradictions:[`Promessa impossível pode ser suspensa ou herdada conforme o porto`],modernInterpretations:[`Contrato comunitário marítimo`],possiblyTrue:[`Reduz abandono e disputa de dependentes`],unconfirmed:[`Atração literal do viajante pela promessa`]},"fe-dos-sete-nomes":{originMyth:`Sete virtudes teriam sido nomeadas quando comunidades precisaram reconstruir depois da primeira grande ruptura humana.`,creationView:`Não possui versão única; nomes ordenam conduta, não matéria.`,deathView:`Namar encerra dívidas e Veyra preserva testemunho.`,magicView:`Virtude não produz magia nem prova favor divino.`,symbols:[`Sete marcas sem rosto`],rituals:[`Leitura das sete perguntas`,`Funeral de Namar e Veyra`],sacredDates:[`Sem calendário único; cada vertente prioriza uma virtude`],clergy:[`Juízes, cuidadores e memorialistas conforme a vertente`],sacredPlaces:[`Templos e tribunais comunitários`],ancientTexts:[`Livro das Sete Perguntas`],heresies:[`Rei como encarnação de Edria`],regionalDifferences:[`Valoria enfatiza justiça e medida`,`Ravenhold, consciência`,`Winterfeld, coragem e abrigo`],politicalImpact:[`Usada tanto para legitimar coroas quanto para limitá-las`],contradictions:[`Instituições discordam se nomes são entidades ou conceitos`],modernInterpretations:[`Linguagem ética comum entre reinos`],possiblyTrue:[`Origem histórica das instituições`],unconfirmed:[`Existência pessoal dos Sete Nomes`]},"coroa-dourada":{originMyth:`Edria teria pesado uma coroa e um pão, escolhendo o pão quando a coroa não alimentou ninguém.`,creationView:`Herda versões dos Sete Nomes.`,deathView:`Dívidas de grão não passam automaticamente aos descendentes.`,magicView:`Nenhuma medida ou rito concede magia.`,symbols:[`Balança com pão e aro dourado`],rituals:[`Pesagem da primeira colheita`,`Abertura de celeiro de emergência`],sacredDates:[`Mesa do Primeiro Pão`],clergy:[`Magistrados de medida e guardiões de celeiro`],sacredPlaces:[`Tribunal dos Pesos`],ancientTexts:[`Comentários da Balança`],heresies:[`Coroa como corpo de Edria`],regionalDifferences:[`Campo Aberto rejeita símbolos monárquicos`],politicalImpact:[`Fundamenta limites aos Arden`],contradictions:[`Templos nobres e rurais discordam sobre propriedade`],modernInterpretations:[`Direito alimentar religioso`],possiblyTrue:[`Arquivos confirmam função histórica dos templos`],unconfirmed:[`Intervenção de Edria`]},"vigilia-ultima-brasa":{originMyth:`Uma brasa teria permanecido acesa até o último viajante encontrar abrigo.`,creationView:`O mundo habitável é produzido por quem mantém calor compartilhado.`,deathView:`Ninguém deve morrer sozinho fora dos portões fechados.`,magicView:`Rejeita culto mágico a Vyrasul.`,symbols:[`Brasa sob estrela de gelo`],rituals:[`Contagem de presença`,`Manutenção contínua do fogo público`],sacredDates:[`Quarenta noites de portões fechados`],clergy:[`Vigias de fogo e auditores de estoque`],sacredPlaces:[`Salões termais de abrigo`],ancientTexts:[`Livro das Quarenta Noites`],heresies:[`Vyrasul como emissário divino`],regionalDifferences:[`Jarls rurais mantêm fogos menores ligados à capital`],politicalImpact:[`Abrigo limita autoridade dos jarls`],contradictions:[`Algumas casas recusaram estrangeiros apesar do rito`],modernInterpretations:[`Instituição de sobrevivência climática`],possiblyTrue:[`Origem e função documentadas`],unconfirmed:[`A primeira brasa como objeto ainda existente`]},"vigilia-sol-negro":{originMyth:`O sol escurece quando obediência encobre a consciência.`,creationView:`Não explica a criação do mundo; examina o momento moral da decisão.`,deathView:`Ordens e recusas do morto são lidas para que memória não se torne propaganda.`,magicView:`Magia não determina culpa; atos e ordens são julgados.`,symbols:[`Disco negro sobre estandarte baixado`],rituals:[`Leitura de ordens`,`Vigília dos nomes restituídos`],sacredDates:[`Aniversário local da revogação de decretos da Cinza`],clergy:[`Veteranos memorialistas e juízes de consciência`],sacredPlaces:[`Arquivo das Ordens em Ravencastle`],ancientTexts:[`Livro das Ordens Recusadas`],heresies:[`Obediência absoluta como virtude`],regionalDifferences:[`Quartéis antigos resistem à reforma`],politicalImpact:[`Sustenta direito de recusa e oposição a Cassor`],contradictions:[`A própria tradição justificou perseguição no passado`],modernInterpretations:[`Religião penitencial militar`],possiblyTrue:[`Responsabilidade histórica é documentada`],unconfirmed:[`Nenhuma afirmação sobrenatural central`]},"chama-sem-coroa":{originMyth:`Uma chama sobrevive depois que a coroa que tentava possuí-la se rompe.`,creationView:`Comunidade precede governo; autoridade é ferramenta temporária.`,deathView:`Mortos são lembrados por atos e pessoas protegidas, não por títulos.`,magicView:`Poder mágico não santifica governo.`,symbols:[`Chama dentro de coroa quebrada`],rituals:[`Quebra da insígnia`,`Portas abertas a perseguidos`],sacredDates:[`Noite das Portas Abertas`],clergy:[`Não possui sacerdócio fixo; vigias conduzem ritos`],sacredPlaces:[`Fortaleza do Véu e mesas de abrigo`],ancientTexts:[`Cadernos de refúgio e declarações rebeldes`],heresies:[`Transformar um guardião em soberano vitalício`],regionalDifferences:[`Cada fortaleza define duração de mandato`],politicalImpact:[`Legitima resistência e limita títulos Bellatrix`],contradictions:[`Abrigo pode conflitar com segurança de comunidades pequenas`],modernInterpretations:[`Ética rebelde de governo temporário`],possiblyTrue:[`Origem histórica e ritos documentados`],unconfirmed:[`A primeira chama como objeto literal`]}},M=[e({id:`caminho-das-raizes`,name:`Caminho das Raízes`,subtitle:`Memória, reciprocidade e floresta`,summary:`Tradição de Sylvaris que entende os vivos como hóspedes temporários de uma memória ecológica maior.`,description:`Não há divindade central. Ritos registram nascimentos, mortes e mudanças no território. Decisões religiosas têm consequência prática: áreas de luto ficam sem colheita por uma estação para permitir recuperação do solo.`,category:`Tradição élfica`,status:`Praticada`,origin:`Sylvaris`,location:`Floresta Antiga`,relations:[{label:`Sylvaris`,to:`/reinos/sylvaris`}]}),e({id:`culto-da-brasa-comum`,name:`Culto da Brasa Comum`,subtitle:`Nenhum fogo pertence a uma só casa`,summary:`Prática comunitária humana centrada na manutenção de fogos públicos durante inverno, fome e guerra.`,description:`Templos funcionam como cozinhas, abrigos e depósitos. Sacerdotes são avaliados pela administração das reservas, não por milagres. O culto cresceu após a Fome dos Sete Invernos e frequentemente entra em conflito com nobres que desejam controlar doações.`,category:`Religião comunitária`,status:`Praticada`,origin:`Valoria`,location:`Reinos humanos`}),e({id:`nove-ecos`,name:`Os Nove Ecos`,subtitle:`A pedra devolve o que fazemos`,summary:`Filosofia anã segundo a qual toda obra produz consequências que retornam por caminhos materiais e sociais.`,description:`Cada eco representa uma responsabilidade: água, ar, estrutura, calor, trabalho, memória, troca, abrigo e reparo. Antes de uma grande escavação, nove especialistas respondem publicamente por esses efeitos.`,category:`Filosofia anã`,status:`Praticada`,origin:`Kar-Dûm`,location:`Salões anões`,relations:[{label:`Kar-Dûm`,to:`/reinos/kar-dum`}]}),e({id:`juramento-do-horizonte`,name:`Juramento do Horizonte`,subtitle:`A fé dos que partem e retornam`,summary:`Tradição marítima de Eldemar baseada em promessas registradas antes de cada viagem.`,description:`Tripulações escrevem obrigações com famílias e companheiros em placas de cera. Ao retornar, devem cumprir ou explicar cada promessa diante do cais. O rito reduz abandono de dependentes e funciona como contrato comunitário.`,category:`Tradição marítima`,status:`Praticada`,origin:`Eldemar`,location:`Portos de Avernor`,relations:[{label:`Eldemar`,to:`/reinos/eldemar`}]}),e({id:`fe-dos-sete-nomes`,name:`Fé dos Sete Nomes`,subtitle:`Sete virtudes, muitas instituições`,summary:`Família de religiões humanas que nomeia justiça, coragem, sabedoria, compaixão, memória, mudança e morte.`,description:`Os nomes são Avar, coragem que permanece; Edria, justiça sem proprietário; Saelor, sabedoria que pergunta; Miren, compaixão que abriga; Veyra, memória que testemunha; Ordan, mudança que abre caminho; e Namar, morte que encerra dívidas. Nenhuma vertente concede magia. Reis usam os nomes para legitimar-se, enquanto reformistas recordam que virtudes não pertencem a coroas.`,category:`Religião humana`,status:`Amplamente praticada`,origin:`Reino humano antigo`,location:`Reinos humanos`,truthStatus:`documented`,beliefs:[`Virtudes não são propriedade de governantes`,`Mortos são confiados a Namar e lembrados por Veyra`,`Avar não justifica guerra sem responsabilidade`],relations:[{label:`Humanos de Avernor`,to:`/povos/humanos`}]}),e({id:`coroa-dourada`,name:`Culto da Coroa Dourada`,subtitle:`A vertente valoriana dos Sete Nomes`,summary:`Tradição que mede justiça pela capacidade de manter colheitas, pesos e pactos públicos.`,description:`Templos funcionam como tribunais de medida e celeiros de emergência. A ala cortesã afirma que a coroa representa Edria; a ala do Campo Aberto responde que nenhuma pessoa pode encarnar uma virtude. A disputa alimenta reformas agrárias sem transformar fé em feitiço.`,category:`Vertente humana`,status:`Dividida`,origin:`Valoria`,location:`Valoria`,truthStatus:`documented`,relations:[{label:`Valoria`,to:`/reinos/valoria`},{label:`Casa Arden`,to:`/casas/arden`}]}),e({id:`vigilia-ultima-brasa`,name:`Vigília da Última Brasa`,subtitle:`A fé do abrigo setentrional`,summary:`Vertente de Winterfeld que mantém um fogo público até a última pessoa encontrar abrigo.`,description:`Durante as quarenta noites de portões fechados, vigias registram estoque e presença. Fanáticos já tentaram declarar o dragão Vyrasul emissário divino; o concílio local rejeita a tese e o trata como criatura natural. Abandonar alguém ao frio é a principal ruptura moral.`,category:`Vertente humana`,status:`Praticada`,origin:`Winterfeld`,location:`Winterfeld`,truthStatus:`documented`,relations:[{label:`Winterfeld`,to:`/reinos/winterfeld`},{label:`Vyrasul`,to:`/criaturas/vyrasul`}]}),e({id:`vigilia-sol-negro`,name:`Vigília do Sol Negro`,subtitle:`Memória e disciplina em Ravenhold`,summary:`Religião de veteranos que registra ordens recusadas, obedecidas e lamentadas.`,description:`O disco negro representa o momento em que obediência encobre consciência. Uma ala militar justificou a Caça às Bruxas; penitentes atuais preservam listas de vítimas e defendem direito formal à recusa. O conflito religioso atravessa o Senado de Estandartes.`,category:`Vertente humana`,status:`Em reforma`,origin:`Ravenhold`,location:`Ravenhold`,truthStatus:`documented`,relations:[{label:`Ravenhold`,to:`/reinos/ravenhold`},{label:`Caça às Bruxas`,to:`/historia/caca-bruxas`}]}),e({id:`chama-sem-coroa`,name:`A Chama sem Coroa`,subtitle:`Nenhum governante é sagrado`,summary:`Crença rebelde das Montanhas Cinzentas que coloca juramento ao povo acima de juramento ao trono.`,description:`Seu símbolo é uma chama dentro de uma coroa quebrada. Mortos são lembrados por atos, liberdade deve ser defendida e proteger perseguidos pode ser dever sagrado. Namídia Bellatrix renovou o rito ao abrir a Fortaleza do Véu a fugitivos, sem possuir magia ou autoridade divina.`,category:`Crença rebelde`,status:`Praticada`,origin:`Montanhas Cinzentas`,location:`Fortalezas rebeldes`,truthStatus:`documented`,beliefs:[`Nenhum governante é sagrado`,`Juramento ao povo supera juramento ao trono`,`Abrigar perseguidos pode ser dever sagrado`],relations:[{label:`Namídia Bellatrix`,to:`/personagens/namidia-bellatrix`},{label:`Fortaleza do Véu`,to:`/cidades/fortaleza-do-veu`}]})].map(e=>({...e,...j[e.id]})),N={"espada-da-trovoada":{ancientNames:[`Fulgarion`,`Espada dos Sete Trovões`],creator:`Forjada em Kar-Dûm por artífices não identificados e finalizada por Normus Kayler.`,materials:[`Aço de Kar-Dûm`,`Filamentos de prata meteórica`,`Isolantes minerais no punho`],appearance:`Lâmina longa de brilho frio, sulcada por sete canais condutores. A guarda não possui coroa; marcas da bainha registram reparos. Quando carregada, os sulcos assumem violeta irregular sem ocultar danos no metal.`,inscriptions:[`Sete marcas de manifestação`,`Notação anã de aterramento`,`Juramento Kayler abreviado`],powers:[`Conduz e distribui magia de tempestade`,`Permite sete manifestações progressivas`,`A função integral da sétima marca não é publicada`],limitations:[`Não cria magia`,`Exige sangue Kayler para manifestações`,`Umidade, aterramento e condição física limitam alcance`],costs:[`Sobrecarga nervosa`,`Tremores e perda de sensibilidade`,`Custo final não registrado publicamente`],formerBearers:[`Normus Kayler`],currentBearer:`Sirius Kayler`,events:[`Defesa de Kar-Dûm`,`Defesa de Sylvaris`,`Batalha final de Normus`,`Reabertura do baú em 1204`],rumors:[`A sétima marca teria aparecido apenas depois da batalha final`],activation:[`Contato com mana Kayler`,`Progressão depende de controle, não de palavra secreta`],destruction:[`Derreter os filamentos inutilizaria a condução, mas não há método seguro confirmado para destruir toda a lâmina`],risks:[`Descarga indiscriminada`,`Uso político do portador`,`Consequências não registradas da sétima manifestação`],historicalSources:[`Bainha de reparos`,`Registros de forja`,`Carta de Normus`],disputedClaims:[`Seladores afirmam que Fulgarion foi criada como chave; os registros materiais confirmam apenas uma arma condutora`]},"adaga-do-passo-velado":{ancientNames:[`Passo Velado; outros nomes não registrados`],creator:`Oficina rúnica de Sylvaris; artífice individual não publicado.`,materials:[`Liga élfica leve`,`Prata rúnica`,`Bainha com sais aquecedores`],appearance:`Adaga estreita de prata fosca, com runas que parecem se aproximar quando o destino está marcado. A bainha possui compartimentos térmicos e fios para assinalar pontos seguros.`,inscriptions:[`Runas de origem, destino e retorno`],powers:[`Dobra distância por um instante até ponto visível ou previamente marcado`],limitations:[`Curto alcance`,`Exige concentração contínua e esforço físico`,`Requer destino seguro, visível ou previamente marcado`,`Não corrige ponto de pouso perigoso`,`Não atravessa ferro meteórico`,`Carga e passageiros ampliam o risco`],costs:[`Perda de calor`,`Vertigem`,`Possível inconsciência após usos rápidos`],formerBearers:[`Portadores de treino não divulgados`],currentBearer:`Elara`,events:[`Treinamento de Elara`,`Missão nas margens de Sylvaris`],rumors:[`Uma runa apagada permitiria atravessar para outro mundo; sem prova`],activation:[`Contato com marca reconhecida`,`Visualização clara de área segura`,`Concentração e impulso físico consciente da portadora`],destruction:[`Runas podem ser inutilizadas por deformação, mas quebrar a lâmina durante ativação é risco não testado`],risks:[`Chegada desorientada`,`Pouso perigoso quando a área é mal avaliada`,`Hipotermia`,`Separação de passageiro`],historicalSources:[`Diário de treinamento`,`Arquivo de oficina`],disputedClaims:[`Não há confirmação de viagens além do alcance local`]},"medalhao-da-folha-partida":{ancientNames:[`Sinal das Duas Metades`],creator:`Artífices dos Círculos de Sylvaris sob acordo de Aelwen e Normus.`,materials:[`Prata vegetal`,`Resina de memória`,`Fio Kayler de condução mínima`],appearance:`Folha de prata dividida por um raio. Uma borda se encaixa apenas na metade conservada por Sylvaris; isoladas, ambas parecem incompletas.`,inscriptions:[`Juramento legível apenas quando as metades se encontram`],powers:[`Nenhum poder mágico confirmado`,`Autentica o pacto diante dos Círculos`],limitations:[`Não concede acesso automático a Sylvaris`,`Não obriga descendentes`],costs:[`Exibir a peça revela vínculo político e pode atrair perseguidores`],formerBearers:[`Normus Kayler`],currentBearer:`Sirius Kayler; segunda metade com Aelwen`,events:[`Pacto dos Descendentes`,`Herança de Sirius`],rumors:[`A inscrição completa incluiria uma ordem de casamento — alegação falsa e rejeitada`],activation:[`Reunião física das duas metades diante de testemunhas dos Círculos`],destruction:[`Pode ser derretido como metal, mas os registros do pacto continuariam existindo`],risks:[`Uso como falsa prova de domínio sobre Sirius ou Elara`],historicalSources:[`Atas dos Círculos`,`Carta de Normus`],disputedClaims:[`O texto completo permanece reservado até que os envolvidos estejam presentes`]},"martelo-de-orun":{ancientNames:[`Padrão de Orun`,`Nona Medida`],creator:`Orun da Pedra Medida e mestres de calibração de Thur-Kar.`,materials:[`Liga anã estável`,`Cabo de madeira mineralizada`,`Contrapesos internos selados`],appearance:`Martelo compacto, sem ornamentação militar, com nove linhas de aferição e marcas de reparo registradas.`,inscriptions:[`Nove responsabilidades da medida`],powers:[`Nenhum poder arcano`,`Serve como padrão material de massa e equilíbrio`],limitations:[`Autoridade depende de cadeia de custódia e comparação pública`],costs:[`Manutenção anual exige interrupção das balanças comerciais`],formerBearers:[`Orun da Pedra Medida`,`Sucessivos guardiões de calibração`],currentBearer:`Câmara das Nove Bigornas`,events:[`Padronização das forjas`,`Revisão após os Túneis Vazios`],rumors:[`Teria sido usado como arma; marcas não confirmam`],activation:[`Cerimônia anual de comparação`],destruction:[`Fusão destruiria o padrão; réplicas documentais permitiriam reconstrução aproximada`],risks:[`Fraude na cadeia de custódia`,`Transformação de precisão em autoridade religiosa absoluta`],historicalSources:[`Contratos em ardósia`,`Livros de calibração`],disputedClaims:[`Relatos de uso em combate não são sustentados pelas marcas físicas do objeto`]},"carta-de-normus":{ancientNames:[`Carta para o Filho sem Lembranças`],creator:`Normus Kayler, com trechos cifrados segundo método Bellatrix.`,materials:[`Papel resistente a umidade`,`Tinta ferrogálica`,`Lacre Kayler sem função mágica`],appearance:`Folhas dobradas e reparadas, com texto comum interrompido por inventários aparentemente banais que ocultam a cifra Bellatrix.`,inscriptions:[`Mensagem aberta de Normus`,`Trechos finais cifrados`],powers:[`Nenhum poder mágico`,`Valor probatório e emocional`],limitations:[`Cifra incompleta`,`A leitura depende de referências do caderno de Namídia`],costs:[`Revelar o conteúdo pode expor rotas e sobreviventes`],formerBearers:[`Normus Kayler`],currentBearer:`Sirius Kayler`,events:[`Preparação do baú`,`Leitura em 1204`],rumors:[`A carta nomearia todos os sobreviventes; improvável e não confirmado`],activation:[`Leitura comum e comparação dos trechos cifrados`],destruction:[`Papel pode ser destruído; cópias parciais podem existir`],risks:[`Falsificação`,`Manipulação emocional de Sirius`,`Exposição de redes`],historicalSources:[`O próprio documento`,`Caderno Bellatrix`],disputedClaims:[`O arquivo público não possui o texto integral por decisão de Sirius`]}},P={"medalhao-ultimo-sussurro":{ancientNames:[`Ouvido de Namar, em uma fonte contestada`],creator:`Desconhecido.`,origin:`Local não registrado; primeiras menções surgem em necrópoles humanas.`,period:`Data anterior à Caça às Bruxas, sem precisão.`,materials:[`Prata escurecida`,`Pedra porosa que retém calor`],appearance:`Medalhão oval marcado por uma boca quase apagada. A superfície aquece quando uma pergunta se liga emocionalmente ao morto.`,inscriptions:[`“Toda resposta ocupa o lugar de uma lembrança” — tradução aproximada`],powers:[`Alcança o último eco de um morto`],costs:[`Apaga memória pessoal relacionada à pergunta`],formerBearers:[`Nomes perdidos ou deliberadamente removidos`],currentBearer:`Desconhecido`,events:[`Três consultas registradas por Pastores dos Mortos`],rumors:[`Necromantes afirmam que o objeto fala com a pessoa inteira; testemunhos contradizem`],activation:[`Nomear o morto`,`Formular pergunta ligada a uma memória própria`],destruction:[`Nenhum método confirmado; separar pedra e aro silencia o objeto temporariamente segundo relato contestado`],risks:[`Perda de identidade`,`Atração de Retornados`,`Confundir fragmento com consentimento`],historicalSources:[`Relatórios dos Pastores`,`Inventário de uma necrópole saqueada`],disputedClaims:[`Localização e identidade do criador`]},fulgarion:{ancientNames:[`Espada dos Sete Trovões`],creator:`Forjas de Kar-Dûm e Normus Kayler.`,period:`Era das Coroas`,materials:[`Aço anão`,`Prata meteórica`],appearance:`Lâmina de sete canais condutores, reparada mais vezes do que ornamentada.`,inscriptions:[`Sete manifestações e juramento abreviado`],powers:[`Condução de tempestade`,`Porta da Tempestade`],costs:[`Mana, integridade nervosa e risco ao entorno`],formerBearers:[`Normus Kayler`],currentBearer:`Sirius Kayler`,events:[`Guerra dos Tronos`,`Caça às Bruxas`,`Retorno de Sirius`],rumors:[`Foi criada como chave — versão contestada`],activation:[`Sangue Kayler, controle e condições atmosféricas`],destruction:[`Inutilização dos filamentos é possível; destruição completa não confirmada`],risks:[`Fratura`,`Apropriação política`,`Sobrecarga`],historicalSources:[`Registro detalhado em /artefatos/espada-da-trovoada`],disputedClaims:[`Função original da sétima manifestação`]},aelysar:{ancientNames:[`Arco da Primeira Raiz`],creator:`Artífices e guardiões de Sylvaris; nomes individuais não publicados.`,period:`Era das Coroas`,materials:[`Madeira caída da Copa Antiga`,`Fibras de prata vegetal`],appearance:`Arco dourado-esverdeado cujo desenho acompanha seis encaixes de flecha. Não exibe corda quando guardado.`,inscriptions:[`Seis obrigações da coroa`],powers:[`Seis flechas rúnicas ligadas a deveres específicos`],limitations:[`Não concede magia de sangue`,`Flecha só retorna quando a obrigação correspondente é cumprida`],costs:[`Cada disparo cria responsabilidade política verificável`],formerBearers:[`Portadores reais não divulgados sem documentação suficiente`],currentBearer:`Guardado pelos Círculos; destinado a Elara apenas após coroação legítima`,events:[`Ritos sucessórios de Sylvaris`],rumors:[`O arco escolheria soberano sozinho — versão rejeitada`],activation:[`Reconhecimento dos Círculos`,`Aceitação consciente da portadora`],destruction:[`Não registrada; Sylvaris proíbe testes`],risks:[`Usar a relíquia para substituir consentimento político`],historicalSources:[`Atas sucessórias`,`Cantos das Seis Flechas`],disputedClaims:[`A função exata do Último Ramo permanece redigida`]},"varkhael-seryn":{ancientNames:[`Fúria e Ferida, em tradução antiga`],creator:`Desconhecido; forja atribuída a Morvath sem prova.`,period:`Não registrado.`,materials:[`Metal escuro não identificado`,`Sulcos que retêm cinza`],appearance:`Duas lâminas gêmeas de perfis diferentes: Varkhael possui fio vermelho; Seryn, brilho pálido. Marcas surgem conforme a emoção do portador.`,inscriptions:[`Nomes parcialmente queimados`],powers:[`Transformam fúria e dor em calor`,`Juntas podem queimar nomes e memória próxima`],limitations:[`Não distinguem justiça de obsessão`,`Separadas possuem alcance menor`],costs:[`Amplificação emocional`,`Perda de memória coletiva`],formerBearers:[`Portadores citados sem cadeia documental confiável`],currentBearer:`Separadas; localizações não confirmadas`,events:[`Apagamentos atribuídos às lâminas, todos contestados`],rumors:[`A Corte de Cinza possui Varkhael`],activation:[`Emoção intensa e intenção dirigida`],destruction:[`Nenhum método conhecido; resfriamento interrompe efeito por pouco tempo`],risks:[`Apagar inocentes`,`Dependência emocional`,`Reunificação das lâminas`],historicalSources:[`Relatos de nomes ausentes`,`Catálogos de armas incompletos`],disputedClaims:[`Origem, portadores e até a identidade de cada lâmina`]},ishara:{ancientNames:[`Véu da Última Cura`],creator:`Desconhecido; tradições atribuem a curadores de mundos diferentes.`,period:`Não registrado.`,materials:[`Tecido claro de fibra não identificada`,`Bordados que escurecem ao absorver dor`],appearance:`Véu leve cuja superfície acumula desenhos escuros semelhantes a feridas fechadas.`,inscriptions:[`Nenhuma escrita; bordados podem funcionar como registro`],powers:[`Transfere dor`,`Pode curar ferimentos ao reduzir vida ou armazenar sofrimento`],limitations:[`Nada é eliminado`,`Capacidade de armazenamento desconhecida`],costs:[`Dor, tempo de vida ou liberação futura do sofrimento`],formerBearers:[`Curadores anônimos em relatos separados`],currentBearer:`Localização desconhecida`,events:[`Curas impossíveis seguidas de colapso tardio`],rumors:[`Uma facção pretende acumular dor de um exército inteiro`],activation:[`Contato com ferida`,`Escolha de quem recebe o custo; consentimento continua questão ética`],destruction:[`Queima comum falhou em um relato; nenhum método autenticado`],risks:[`Transferência sem consentimento`,`Liberação simultânea`,`Uso político para esconder consequências`],historicalSources:[`Relatos de curadores`,`Bordados reproduzidos em códices`],disputedClaims:[`Se o véu escolhe ou apenas obedece ao portador`]}},F=[e({id:`espada-da-trovoada`,name:`Fulgarion, a Espada dos Sete Trovões`,subtitle:`A lâmina herdada de Normus`,summary:`Espada deixada para Sirius, construída para conduzir — e não criar — a magia de tempestade dos Kayler.`,description:`A lâmina contém filamentos de prata meteórica que distribuem carga e impedem que ela atravesse o braço do portador. Suas sete manifestações culminam na Porta da Tempestade. Sem um bruxo Kayler, é apenas uma espada pesada e bem forjada; sobrecarga derrete os filamentos e pode ferir todos ao redor.`,category:`Arma arcana e Relíquia`,status:`Em posse de Sirius`,origin:`Forjas de Kar-Dûm e acabamento de Normus`,location:`Com Sirius`,period:`Era das Coroas`,abilities:[`Despertar`,`Passo Celeste`,`Corrente Partida`,`Céu Descendente`,`Tempestade Interior`,`Julgamento Violeta`,`Porta da Tempestade`],relations:[{label:`Registro entre as Cinco Relíquias`,to:`/reliquias/fulgarion`},{label:`Sirius Kayler`,to:`/personagens/sirius-kayler`},{label:`Normus Kayler`,to:`/personagens/normus-kayler`}],curiosities:[`As marcas da bainha registram reparos, não vitórias.`]}),e({id:`adaga-do-passo-velado`,name:`Adaga do Passo Velado`,subtitle:`A lâmina rúnica de Elara`,summary:`Adaga élfica capaz de transportar Elara por distâncias curtas até pontos visíveis ou previamente marcados.`,description:`Runas gravadas no metal dobram a distância por um instante. Cada salto exige concentração contínua, esforço físico e um destino visível ou previamente marcado que ofereça área segura para chegada. A adaga não atravessa ferro meteórico, não pode levar grandes cargas e não corrige um ponto de pouso perigoso. Cada uso retira calor do corpo da portadora; três saltos rápidos podem causar perda de consciência.`,category:`Artefato rúnico`,status:`Ativo`,origin:`Sylvaris`,location:`Com Elara`,period:`Era atual`,limitations:[`Exige destino visível ou marcado`,`Exige concentração e esforço físico`,`Requer ponto de chegada seguro`,`Não atravessa ferro meteórico`,`Uso repetido causa hipotermia e vertigem`],relations:[{label:`Elara`,to:`/personagens/elara`}],curiosities:[`A bainha contém sais aquecedores para reduzir o risco de hipotermia.`]}),e({id:`medalhao-da-folha-partida`,name:`Medalhão da Folha Partida`,subtitle:`Sinal do pacto entre Kayler e Sylvaris`,summary:`Medalhão élfico deixado por Normus entre os pertences de Sirius.`,description:`Duas metades de prata vegetal formam uma folha atravessada por um raio. O objeto não concede magia; serve como prova reconhecida pelos guardiões de Sylvaris. Uma das inscrições permanece cifrada e depende da metade conservada pela Rainha.`,category:`Insígnia diplomática`,status:`Preservado`,origin:`Sylvaris`,location:`Com Sirius`,period:`Caça às Bruxas`,relations:[{label:`Pacto dos Descendentes`,to:`/lendas/pacto-dos-descendentes`},{label:`Sirius Kayler`,to:`/personagens/sirius-kayler`}]}),e({id:`martelo-de-orun`,name:`Martelo de Orun`,subtitle:`Padrão das nove forjas`,summary:`Ferramenta cerimonial usada para calibrar pesos e resolver disputas entre os salões de Kar-Dûm.`,description:`O martelo não é uma arma mágica. Sua importância vem da precisão: a cabeça mantém massa e equilíbrio mesmo após séculos de reparo. Réplicas comerciais são comparadas ao original uma vez por ano.`,category:`Relíquia cívica`,status:`Em uso cerimonial`,origin:`Kar-Dûm`,location:`Thur-Kar`,period:`Era da Magia`,relations:[{label:`Kar-Dûm`,to:`/reinos/kar-dum`}]}),e({id:`carta-de-normus`,name:`Carta de Normus`,subtitle:`Palavras para um filho sem lembranças`,summary:`Documento selado entregue a Sirius com ouro, espada, medalhão e pertences do pai.`,description:`A carta explica parte da perseguição e pede que Sirius não confunda vingança com memória. Trechos finais usam uma cifra Bellatrix, possivelmente para proteger a localização de sobreviventes. O Arquivo registra sua existência, mas não publica o texto integral por escolha de Sirius.`,category:`Documento pessoal`,status:`Parcialmente decifrado`,origin:`Normus Kayler`,location:`Com Sirius`,period:`Caça às Bruxas`,relations:[{label:`Normus Kayler`,to:`/personagens/normus-kayler`},{label:`Namídia Bellatrix`,to:`/personagens/namidia-bellatrix`}]})].map(e=>({...e,...N[e.id]})),I=(e,t,n)=>({date:e,title:t,description:n}),L={"guerra-dos-tres-herdeiros":{additionalRelations:[{label:`Dinastia Averen`,to:`/dinastias/averen`},{label:`Sucessões de Avernor`,to:`/sucessoes`}],aliases:[`Guerra dos Três Estandartes`,`Primeiro Cisma das Legiões`],duration:`Cerca de cem anos, com tréguas regionais descontínuas.`,background:`A Coroa Una dependia de doze legiões, celeiros reais e uma rede de estradas. Edric Averen não estabeleceu uma regra aceita de primazia, e cada filho controlava uma parte suficiente do Estado para impedir a vitória dos outros.`,trigger:`Morte de Edric Averen no ano 0 e divulgação de três interpretações incompatíveis de sua última ordem.`,commanders:[`Aldren Averen`,`Kaelor Averen`,`Theron Averen`,`Marcellus Veyron na fase de reunificação`],armies:[`Doze Legiões divididas`,`Levas de governadores`,`Guardas de celeiro e companhias de estrada`],alliances:[`Alianças mudavam conforme colheitas e casamentos; nenhum bloco permaneceu intacto por todo o conflito`],objectives:[`Controlar a Coroa Una`,`Garantir celeiros e estradas`,`Negar legitimidade aos irmãos`],strategies:[`Quebra deliberada de pontes`,`Cerco de armazéns`,`Compra de lealdade legionária`,`Casamentos regionais de curta duração`],mainBattles:[`Cisma das Doze Legiões`,`Cerco dos Três Estandartes`,`Campanhas das Estradas Partidas`,`Tratado das Cinzas`],losses:[`Estimativas tardias falam em milhões de mortos, sem censo confiável`,`Oito grandes cidades perderam mais da metade da população registrada`,`Quatro legiões deixaram de existir como unidades reconhecíveis`],territorialChanges:[`Fim prático da administração continental`,`Governadores tornaram-se senhores regionais`,`Fronteiras militares passaram a orientar futuros reinos`],politicalImpact:[`Destruição da legitimidade automática dos Averen`,`Ascensão de Marcellus Veyron sobre territórios exaustos`],economicImpact:[`Colapso de pedágios comuns`,`Fomes causadas por cerco e destruição de canais`],culturalImpact:[`Calendários regionais`,`Baladas incompatíveis sobre cada herdeiro`,`Desconfiança duradoura de sucessão sem regra escrita`],historicalAccounts:[`Crônicas das Doze Legiões — incompletas`,`Livros de grão de Valoria`,`Cantos funerários regionais`],disputedClaims:[`Cada tradição atribui a primeira quebra de trégua a um irmão diferente`,`Não há prova de que Edric pretendesse dividir o reino`],secretEventsStatus:`Versões reservadas podem existir, mas nenhum acontecimento secreto é publicado como fato.`,legacy:`Transformou uma questão doméstica em modelo continental de crise sucessória e criou as condições para a tirania reunificadora de Veyron.`,detailedTimeline:[I(`Ano 0`,`Morte de Edric`,`Três herdeiros reclamam a Coroa e as legiões dividem juramentos.`),I(`Anos 1–12`,`Campanhas dos estandartes`,`Pontes, celeiros e capitais provinciais tornam-se objetivos centrais.`),I(`Anos 13–63`,`Guerra regionalizada`,`Frentes se fragmentam; governadores e cidades passam a combater por sobrevivência própria.`),I(`Anos 64–91`,`Exaustão dos Averen`,`Ramos sucessórios perdem comando e legitimidade enquanto fomes se acumulam.`),I(`Anos 92–100`,`Ascensão de Veyron`,`Marcellus incorpora legiões remanescentes, encerra focos de resistência e promete reconstrução.`)]},"guerra-da-cinza-branca":{additionalRelations:[{label:`Casa Nimbus`,to:`/casas/nimbus`},{label:`Casa Rivs`,to:`/casas/rivs`},{label:`Normus Kayler`,to:`/personagens/normus-kayler`},{label:`Namídia Bellatrix`,to:`/personagens/namidia-bellatrix`},{label:`Fortaleza do Véu`,to:`/cidades/fortaleza-do-veu`}],aliases:[`Caçada Continental`,`Campanhas do Edito Branco`],duration:`76 anos entre o primeiro Edito e a batalha final de Normus.`,background:`Durante a Era das Coroas, governantes dependeram dos bruxos e simultaneamente temeram sua recusa a servir. Crises econômicas e propaganda transformaram as três Casas em explicação conveniente para guerras que as coroas haviam iniciado.`,trigger:`O Conselho dos Sete Reis aprovou o Edito da Cinza Branca, exigindo registro, serviço compulsório e entrega de crianças com sinais das linhagens.`,commanders:[`Sete soberanos cujos votos completos permanecem parcialmente suprimidos`,`Normus Kayler na resistência final`,`Comandantes Nimbus não preservados integralmente`,`Guardiões Rivs responsáveis pela evacuação`],armies:[`Legiões e inquisidores reais`,`Defensores das Casas`,`Milícias de fortalezas e redes civis de refúgio`],alliances:[`Conselho dos Sete Reis`,`Pacto fragmentado entre Casas e abrigos`,`Apoio discreto de Sylvaris`],objectives:[`Registrar ou eliminar as três Casas`,`Confiscar arquivos e artefatos`,`Evacuar crianças, pessoas e conhecimento`],strategies:[`Propaganda de medo`,`Cerco de propriedades`,`Separação de famílias`,`Resistência aberta Nimbus`,`Dispersão de arquivos Rivs`,`Rotas cifradas Bellatrix`],mainBattles:[`Resistência final Nimbus`,`Queda do Arquivo Rivs`,`Cerco da Fortaleza do Véu`,`Batalha final de Normus`],losses:[`Casa Nimbus considerada destruída`,`Casa Rivs desaparecida`,`Milhares de civis mortos, deslocados ou renomeados`,`Arquivos inteiros queimados ou fragmentados`],territorialChanges:[`Terras das Casas confiscadas e redistribuídas`,`Montanhas Cinzentas ampliaram redes de abrigo`,`Sylvaris fechou rotas externas`],politicalImpact:[`Normalização de registro por sangue`,`Fortalecimento temporário das coroas`,`Crise moral posterior em Ravenhold`],economicImpact:[`Confisco de propriedades`,`Perda de conhecimento hidráulico e logístico`,`Fortalezas sobrecarregadas por refugiados`],culturalImpact:[`Apagamento de nomes`,`Estigma sobre olhos violetas e cabelos brancos`,`Cultos memoriais e movimentos de reparação`],historicalAccounts:[`Editos reais — versões divergentes`,`Cifras Bellatrix`,`Arquivos dos Círculos`,`Propaganda inquisitorial`],disputedClaims:[`O número e a identidade dos Sete Reis não são uniformes nas cópias`,`Extinção Nimbus e Rivs não foi comprovada indivíduo por indivíduo`],secretEventsStatus:`Sobreviventes ou rotas secretas pertencem ao arquivo do autor e não são revelados no site público.`,legacy:`Define a infância de Sirius, a culpa institucional das coroas e a diferença entre desaparecimento documental e extinção real.`,detailedTimeline:[I(`628 d.C.`,`Edito da Cinza Branca`,`Registro compulsório e entrega de crianças tornam perseguição política de Estado.`),I(`Décadas de 630–680`,`Cerco às Casas`,`Propriedades são tomadas; redes civis criam rotas e nomes de proteção.`),I(`Antes de 688 d.C.`,`Resistência Nimbus`,`A Casa cobre evacuações em combate aberto e é declarada destruída.`),I(`Final do século VII`,`Evacuação Rivs`,`Pessoas, índices e arquivos desaparecem de forma coordenada.`),I(`704 d.C.`,`Fortaleza, nascimento e batalha final`,`Namídia protege Sirius; Normus encerra a última frente registrada e morre.`)]},"batalha-das-aguas-negras":{additionalRelations:[{label:`Porto de Eldemar`,to:`/cidades/porto-de-eldemar`},{label:`Arquipélago das Brumas`,to:`/locais/arquipelago-das-brumas`}],aliases:[`Noite dos Faróis Apagados`],duration:`Uma noite de combate e vários dias de resgate.`,background:`A Liga das Brumas pretendia quebrar o controle de Eldemar sobre estaleiros, licenças e cartas marítimas. O porto tinha menos navios pesados, mas conhecia marés e recifes.`,trigger:`A frota invasora avançou durante lua nova depois de receber sinais falsos de que parte da guarda havia deixado o porto.`,commanders:[`Comando de Eldemar não preservado de forma unânime`,`Almirantes da Liga das Brumas — nomes divergentes nos registros`],armies:[`Frota de escolta de Eldemar`,`Pilotos civis`,`Navios da Liga das Brumas`],alliances:[`Guildas de pilotos apoiaram a coroa em troca de revisão futura de licenças`],objectives:[`Tomar docas e mapas`,`Preservar o porto sem enfrentar a frota em mar aberto`],strategies:[`Apagar faróis oficiais`,`Acender sinais falsos em recifes`,`Atrair navios pesados para águas rasas`,`Isolar distritos por pontes móveis`],mainBattles:[`Engodo dos recifes`,`Combate das docas baixas`,`Retirada pela maré crescente`],losses:[`Navios invasores encalhados ou capturados`,`Pilotos e guardas de Eldemar mortos`,`Vilas costeiras destruídas no corredor usado como isca`],territorialChanges:[`Nenhuma anexação permanente`,`Eldemar ampliou fiscalização das enseadas`],politicalImpact:[`Conselho das Marés ganhou poder sobre a coroa`,`Vilas exigiram representação e reparação`],economicImpact:[`Estaleiros preservados`,`Pesca costeira interrompida`,`Reparações incompletas`],culturalImpact:[`Vitória celebrada e lamentada na mesma cerimônia`,`Faróis apagados tornaram-se símbolo ambíguo`],historicalAccounts:[`Livros de bordo`,`Sinos codificados`,`Depoimentos das vilas`],disputedClaims:[`Não há consenso sobre quem autorizou usar as vilas como parte do engodo`],secretEventsStatus:`Nenhuma versão secreta publicada; atas fechadas do Conselho permanecem inacessíveis.`,legacy:`Provou que informação e geografia podiam derrotar superioridade naval, mas deixou uma dívida política ainda ativa.`,detailedTimeline:[I(`552 d.C., entardecer`,`Sinais de invasão`,`Pilotos confirmam a aproximação da Liga.`),I(`552 d.C., primeira vigília`,`Faróis apagados`,`Eldemar fecha pontes e acende sinais falsos.`),I(`552 d.C., maré baixa`,`Encurralamento`,`Navios pesados ficam presos nos recifes.`),I(`552 d.C., amanhecer`,`Vitória e perda`,`O porto permanece, mas as vilas usadas no engodo estão destruídas.`),I(`Após 552 d.C.`,`Reparações`,`Conselho promete compensação que permanece incompleta em 1204.`)]},"guerra-dos-tuneis-vazios":{additionalRelations:[{label:`Thur-Kar`,to:`/cidades/thur-kar`},{label:`Anões de Kar-Dûm`,to:`/povos/anoes`}],aliases:[`Campanha dos Lacres Rompidos`],duration:`Quatro anos de mobilização subterrânea.`,background:`Salões rivais competiam por novos veios e consideravam excessivamente lenta a Escuta da Pedra. Lacres ancestrais eram tratados como obstáculos econômicos sem documentação suficiente.`,trigger:`Duas equipes abriram lados distintos do mesmo sistema lacrado, alterando ventilação e liberando gases, colapsos e criaturas.`,commanders:[`Conselho de emergência dos Nove Salões`,`Chefes de evacuação cujos nomes permanecem em arquivos de ofício`],armies:[`Guardiões de túnel`,`Engenheiros`,`Curadores e equipes de evacuação`],alliances:[`Nove Salões sob comando temporário`,`Fornecimento alimentar de Valoria`],objectives:[`Evacuar bairros`,`Restaurar ventilação`,`Conter criaturas`,`Selar acessos sem destruir aquíferos`],strategies:[`Mapeamento acústico`,`Fechamento por setores`,`Escudos de corredor`,`Desvio temporário de água`],mainBattles:[`Colapso do Salão Baixo`,`Defesa das Bombas de Ar`,`Selamento da Galeria Sem Eco`],losses:[`Mineiros intoxicados`,`Bairros e aquedutos perdidos`,`Registros de três salões destruídos`],territorialChanges:[`Galerias interditadas`,`Novas fronteiras técnicas entre salões`],politicalImpact:[`Criação do Código das Profundezas`,`Poder ampliado dos guardiões de água e ar`],economicImpact:[`Perda de veios minerais`,`Dependência temporária de importações`],culturalImpact:[`O termo “guerra” passou a incluir ameaça sem exército`,`O Oitavo Golpe ganhou força entre reformistas`],historicalAccounts:[`Placas de lacre`,`Registros de ventilação`,`Memórias de ofício`],disputedClaims:[`A identidade do salão que rompeu primeiro o lacre não pode ser provada`],secretEventsStatus:`Hipóteses sobre Fraturas permanecem classificadas como arcanas, não como segredo confirmado.`,legacy:`Criou regras de abertura e um precedente para cooperação técnica que hoje orienta o debate sobre o Véu.`,detailedTimeline:[I(`487 d.C.`,`Primeiro rompimento`,`Lacres abertos alteram o ar de galerias vizinhas.`),I(`488 d.C.`,`Evacuação dos bairros baixos`,`Engenheiros abandonam veios para preservar água e ventilação.`),I(`489–490 d.C.`,`Campanha por setores`,`Guardiões retomam bombas e isolam criaturas.`),I(`491 d.C.`,`Galeria Sem Eco`,`O último grande acesso é selado.`),I(`Após 491 d.C.`,`Código das Profundezas`,`Três salões passam a ser necessários para qualquer abertura ancestral.`)]},"guerra-dos-tronos":{additionalRelations:[{label:`Sylvaris`,to:`/reinos/sylvaris`},{label:`Kar-Dûm`,to:`/reinos/kar-dum`},{label:`Orcs de Vul’Gar`,to:`/povos/orcs`},{label:`Fulgarion`,to:`/artefatos/espada-da-trovoada`}],aliases:[`Guerra das Três Correntes`,`Disputa das Coroas`],duration:`46 anos entre pactos coercitivos e o juramento final de Normus.`,background:`A consolidação dos reinos criou competição por metais, passagens e prestígio. Kayler, Nimbus e Rivs podiam alterar campanhas, mas o Juramento Arcano impedia fidelidade soberana baseada no sangue.`,trigger:`Tratados de “proteção” incompatíveis exigiram serviço exclusivo das Casas e permitiram que uma disputa diplomática se transformasse em bloqueios e guerras por procuração.`,commanders:[`Normus Kayler como defensor independente`,`Conselhos de Kar-Dûm e Sylvaris`,`Comandantes reais humanos não preservados de forma completa`,`Chefes orcs contratados e aliados em lados distintos`],armies:[`Coroas humanas rivais`,`Guardiões anões`,`Sentinelas élficas`,`Companhias orcs identificadas por clã`],alliances:[`Acordos variáveis entre coroas`,`Defesa de Kar-Dûm`,`Aliança de Normus com Sylvaris`],objectives:[`Controlar apoio das três Casas`,`Garantir metais e passagens`,`Preservar autonomia de Kar-Dûm e Sylvaris`],strategies:[`Bloqueio de alimento`,`Contratos indiretos com clãs`,`Cerco subterrâneo`,`Defesa de caminhos florestais`],mainBattles:[`Guerra diplomática das cortes`,`Defesa de Kar-Dûm`,`Campanhas contra as margens de Sylvaris`,`Juramento público de Normus`],losses:[`Aldeias deslocadas`,`Companhias orcs destruídas por contratos humanos`,`Rotas de alimento interrompidas`,`Número militar total não registrado`],territorialChanges:[`Fronteiras pouco alteradas`,`Tratados de passagem reescritos`,`Sylvaris restringiu acesso`],politicalImpact:[`Nenhuma coroa obteve exclusividade`,`Normus ganhou prestígio que alimentou medo posterior`],economicImpact:[`Escassez de metal e alimento`,`Pedágios militares prolongados`],culturalImpact:[`Orcs culpados coletivamente em narrativas humanas`,`Cavaleiro de Honra tornou-se título sem precedente`],historicalAccounts:[`Atas de Kar-Dûm`,`Memórias dos Círculos`,`Contratos de clã preservados em Vul’Gar`],disputedClaims:[`A responsabilidade pelas primeiras invasões de Sylvaris é atribuída a intermediários diferentes`,`Nenhum povo orc agiu como unidade`],secretEventsStatus:`Tratados secretos existem como documentos incompletos; o site não publica autores não confirmados.`,legacy:`A recusa de Normus impediu monopólio imediato, mas convenceu reis de que bruxos livres eram ameaça, preparando a Caça às Bruxas.`,detailedTimeline:[I(`566–575 d.C.`,`Guerra dos tratados`,`Coroas oferecem proteção em troca de serviço exclusivo.`),I(`Décadas de 580–590`,`Bloqueios centrais`,`Metal, alimento e passagens substituem declarações formais de guerra.`),I(`Final do século VI`,`Defesa de Kar-Dûm`,`Normus combate sob plano anão e impede tomada das forjas.`),I(`Início do século VII`,`Campanhas de Sylvaris`,`Clãs contratados e forças humanas pressionam as margens.`),I(`612 d.C.`,`Juramento de Normus`,`A defesa termina com reconhecimento em Sylvaris e nenhuma coroa controla as Casas.`)]}},R=[e({id:`guerra-dos-tres-herdeiros`,name:`Guerra dos Três Herdeiros`,subtitle:`O conflito que dividiu as Doze Legiões`,summary:`Um século de campanhas sucessórias destruiu o reino indiviso e transformou governadores em soberanos regionais.`,description:`Aldren, Kaelor e Theron, filhos de Edric Averen, herdaram exércitos, mas não legitimidade suficiente. Nenhum lado reuniu força para vencer sem devastar as terras que pretendia governar. Depois de milhões de mortes e da exaustão dos herdeiros, Marcellus Veyron reunificou o que restava.`,category:`Guerra sucessória`,status:`Encerrada`,period:`Ano 0–100`,era:`Grande Guerra`,location:`Todo o continente`,belligerents:[`Forças de Aldren Averen`,`Forças de Kaelor Averen`,`Forças de Theron Averen`],outcome:`Devastação continental e ascensão de Marcellus Veyron`,causes:[`Morte de Edric sem sucessor declarado`,`Divisão das Doze Legiões`,`Disputa pelo controle de celeiros e estradas`],phases:[`Campanhas dos três estandartes`,`Cerco prolongado das rotas centrais`,`Exaustão das casas Averen`,`Reunificação por Veyron`],consequences:[`Milhões de mortos`,`Fim da unidade política legítima`,`Precedentes para dinastias regionais`],civilianImpact:[`Fomes recorrentes`,`Deslocamento de aldeias inteiras`,`Estradas destruídas para impedir exércitos`],events:[`Cisma das Doze Legiões`,`Cerco dos Três Estandartes`,`Tratado das Cinzas`],relations:[{label:`Genealogia Averen`,to:`/genealogias/averen`},{label:`A Grande Guerra`,to:`/historia/grande-guerra`}]}),e({id:`guerra-da-cinza-branca`,name:`Guerra da Cinza Branca`,subtitle:`A perseguição transformada em política continental`,summary:`Campanhas coordenadas pelo Conselho dos Sete Reis contra as três linhagens bruxas.`,description:`O Edito da Cinza Branca exigiu registro, serviço obrigatório e entrega de crianças. Os Nimbus enfrentaram os exércitos e foram destruídos; os Rivs evacuaram bibliotecas e desapareceram. Redes civis esconderam perseguidos. A guerra terminou após a batalha final de Normus, quando quase não restavam alvos públicos.`,category:`Perseguição e guerra civil`,status:`Encerrada — consequências ativas`,period:`Ano 628–704`,era:`Caça às Bruxas`,location:`Avernor central e oriental`,belligerents:[`Conselho dos Sete Reis`,`Casas Kayler, Nimbus e Rivs`,`Redes de refúgio`],outcome:`Quase desaparecimento das linhagens bruxas`,causes:[`Medo político do poder hereditário`,`Interesse em terras e arquivos das Casas`,`Recusa ao registro e ao serviço forçado`],phases:[`Edito da Cinza Branca`,`Resistência Nimbus`,`Evacuação Rivs`,`Cerco da Fortaleza do Véu`,`Batalha final de Normus`],consequences:[`Nimbus considerados extintos`,`Rivs desaparecidos`,`Sirius mantido em segredo por cinco séculos`],civilianImpact:[`Crianças separadas de famílias`,`Fortalezas convertidas em refúgios`,`Arquivos e identidades deliberadamente apagados`],events:[`Edito da Cinza Branca`,`Queda do Arquivo Rivs`,`Cerco da Fortaleza do Véu`],relations:[{label:`Casa Kayler`,to:`/casas/kayler`},{label:`Caça às Bruxas`,to:`/historia/caca-bruxas`}]}),e({id:`batalha-das-aguas-negras`,name:`Batalha das Águas Negras`,subtitle:`A noite em que Eldemar apagou os faróis`,summary:`Confronto naval decidido por pilotos costeiros, marés e informação falsa, não por superioridade numérica.`,description:`Uma frota de saqueadores tentou tomar as docas de Eldemar durante lua nova. O Conselho das Marés apagou faróis oficiais e acendeu sinais em recifes desabitados. Pequenos navios conduziram parte da frota invasora para águas rasas, onde a maré descendente a imobilizou. O plano salvou o porto, mas destruiu vilas costeiras usadas como isca, dívida ainda debatida.`,category:`Batalha naval`,status:`Encerrada`,period:`Ano 552`,era:`Era das Coroas`,location:`Costa de Eldemar`,belligerents:[`Frota de Eldemar`,`Liga das Brumas`],outcome:`Vitória de Eldemar com perdas civis`,causes:[`Tentativa de capturar os estaleiros e o monopólio cartográfico`],phases:[`Apagamento dos faróis`,`Desvio para recifes`,`Bloqueio pela maré baixa`],consequences:[`Sobrevivência do porto`,`Poder ampliado do Conselho das Marés`],civilianImpact:[`Vilas costeiras destruídas como parte do engodo`,`Reparações ainda incompletas`],relations:[{label:`Eldemar`,to:`/reinos/eldemar`}]}),e({id:`guerra-dos-tuneis-vazios`,name:`Guerra dos Túneis Vazios`,subtitle:`Quando Kar-Dûm lutou contra a própria expansão`,summary:`Campanha subterrânea para conter colapsos, gases e criaturas após salões rivais romperem lacres antigos.`,description:`Não houve exército inimigo único. A guerra recebeu esse nome porque exigiu mobilização total: engenheiros fecharam galerias, soldados evacuaram bairros e curadores trataram intoxicações. O conflito terminou com o Código das Profundezas, que exige consenso de três salões antes de abrir um túnel ancestral.`,category:`Crise subterrânea`,status:`Encerrada`,period:`Ano 487–491`,era:`Era das Coroas`,location:`Kar-Dûm`,belligerents:[`Nove Salões`,`Ameaças subterrâneas`],outcome:`Criação do Código das Profundezas`,causes:[`Competição mineral entre salões`,`Rompimento de lacres sem Escuta da Pedra`],phases:[`Primeiros colapsos`,`Evacuação dos bairros baixos`,`Selamento coordenado`],consequences:[`Código das Profundezas`,`Limite político à expansão`],civilianImpact:[`Intoxicação de mineiros`,`Perda de moradias e aquedutos`],relations:[{label:`Kar-Dûm`,to:`/reinos/kar-dum`}]}),e({id:`guerra-dos-tronos`,name:`Guerra dos Tronos`,subtitle:`Quando as coroas disputaram as três Correntes`,summary:`Conflito da Era das Coroas em que reis tentaram obter exclusividade sobre Kayler, Nimbus e Rivs.`,description:`A guerra começou por pactos de proteção que escondiam exigências de serviço. Normus recusou todos os tronos, defendeu Kar-Dûm durante um cerco subterrâneo e depois Sylvaris contra invasores orcs contratados por intermediários humanos. A atribuição de culpa coletiva aos orcs é falsa: clãs distintos combateram em lados diferentes.`,category:`Guerra continental`,status:`Encerrada`,period:`Ano 566–612`,era:`Era das Coroas`,location:`Rotas centrais, Kar-Dûm e Sylvaris`,belligerents:[`Coroas humanas rivais`,`Forças de Kar-Dûm e Sylvaris`,`Clãs orcs contratados e aliados`],outcome:`Nenhuma coroa controlou as três Casas`,causes:[`Competição pelo apoio dos bruxos`,`Disputa de passagens e metais`,`Tratados secretos incompatíveis`],phases:[`Guerra diplomática das cortes`,`Defesa de Kar-Dûm`,`Invasões contra Sylvaris`,`Juramento de Normus`],consequences:[`Normus nomeado Cavaleiro de Honra`,`Medo das coroas prepara a Caça às Bruxas`,`Tratados orcs passam a exigir identidade dos contratantes`],civilianImpact:[`Fechamento de rotas de alimento`,`Aldeias de fronteira deslocadas`,`Clãs orcs culpados coletivamente por decisões humanas`],relations:[{label:`Normus Kayler`,to:`/personagens/normus-kayler`},{label:`Era das Coroas`,to:`/historia/era-coroas`}]})].map(e=>{let{additionalRelations:t=[],...n}=L[e.id];return{...e,...n,relations:[...e.relations,...t]}}),z={winterfeld:{kingdom:`Winterfeld`,location:`Norte glacial`,climate:`Glacial, com neve persistente e degelos breves.`},montanhas:{kingdom:`Montanhas Cinzentas`,location:`Cordilheira setentrional`,climate:`Frio e seco, com ventos de altitude e vales de pouca luz.`},nevoeiro:{kingdom:`Sem soberania única`,location:`Extremo nordeste marítimo`,climate:`Marítimo frio, encoberto por bancos de neblina.`},sylvaris:{kingdom:`Sylvaris`,location:`Floresta Antiga`,climate:`Úmido e temperado sob a copa.`},valoria:{kingdom:`Valoria`,location:`Planícies centrais`,climate:`Temperado, com cheias e verões de colheita.`},ravenhold:{kingdom:`Ravenhold`,location:`Fronteira oriental`,climate:`Continental, seco e sujeito a grande variação sazonal.`},sombras:{kingdom:`Controle interdito`,location:`Terras Sombrias`,climate:`Seco, com poeira metálica e água de qualidade incerta.`},"kar-dum":{kingdom:`Kar-Dûm`,location:`Cordilheira central`,climate:`Subterrâneo estável, com extremos próximos às forjas.`},brumas:{kingdom:`Sem soberania única`,location:`Arquipélago das Brumas`,climate:`Marítimo, úmido e sujeito a neblina.`},"vul-gar":{kingdom:`Vul’Gar`,location:`Planaltos orientais`,climate:`Seco e quente, com estações de pouca água.`},zharak:{kingdom:`Sem soberania única`,location:`Deserto de Zharak`,climate:`Árido, com forte amplitude térmica.`}};function B({region:t,id:n,name:r,category:i,summary:a,description:o,geography:s,status:c=`Condição atual não registrada`,truthStatus:l=`witnessed`}){let u=z[t];return e({id:n,name:r,category:i,summary:a,description:o,geography:s,subtitle:`Topônimo preservado na carta oficial`,status:c,kingdom:u.kingdom,location:u.location,climate:u.climate,currentSituation:`A existência e a posição regional são testemunhadas pelo raster oficial; ocupação, governo local e condição em 1204 d.C. não foram registrados em fonte textual independente.`,rumors:[`Não há rumor autenticado anexado a este verbete; versões orais permanecem não registradas.`],narrativeImportance:`O topônimo amplia a malha pública do Atlas e permite relacionar viagens e acontecimentos futuros a ${r} sem antecipar fatos ainda desconhecidos.`,knowledgeStatus:`unrecorded`,confidence:`Alta para o topônimo e a posição regional; baixa para detalhes não desenhados.`,sourceType:`Testemunho cartográfico`,sourceReliability:`Carta oficial preservada; leitura aproximada de símbolo, relevo e rótulo.`,sourceStatus:`Baseado no raster oficial do Atlas`,truthStatus:l,updatedAt:`2026-08-12`,relations:[{label:`Localizar no Atlas`,to:`/atlas?ponto=${n}`}]})}var V=[B({region:`winterfeld`,id:`fortaleza-gelida`,name:`Fortaleza Gélida`,category:`Fortaleza`,summary:`Reduto fortificado assinalado no extremo norte de Winterfeld, acima das rotas habitadas da coroa.`,description:`A carta mostra uma fortificação isolada entre gelo e relevo elevado, distante dos núcleos urbanos conhecidos. Seu fundador, sua guarnição e o vínculo administrativo com Winterheim não foram registrados; apenas nome, natureza defensiva e posição setentrional são testemunhados.`,geography:`Esporão rochoso cercado por gelo e acessos estreitos, conforme a leitura do símbolo cartográfico.`,relation:{label:`Winterfeld`,to:`/reinos/winterfeld`}}),B({region:`winterfeld`,id:`passagem-da-geada`,name:`Passagem da Geada`,category:`Passagem`,summary:`Corredor de altitude marcado entre os campos de gelo e as montanhas do norte.`,description:`O topônimo acompanha uma abertura estreita no relevo gelado, indicando passagem possível sem estabelecer estrada permanente. A duração do trânsito, os meses de abertura e eventuais pedágios são desconhecidos; a carta apenas confirma que cartógrafos distinguiam este corredor das geleiras vizinhas.`,geography:`Passo montanhoso sujeito a neve, gelo e fechamento sazonal não documentado.`,relation:{label:`Winterfeld`,to:`/reinos/winterfeld`}}),B({region:`montanhas`,id:`acampamento-da-liberdade`,name:`Acampamento da Liberdade`,category:`Acampamento`,summary:`Acampamento nomeado nas Montanhas Cinzentas, próximo às rotas de vigia do maciço.`,description:`Barracas e paliçadas aparecem na carta em uma clareira de altitude. O nome sugere uma memória política, mas atribuir fundadores, refugiados ou batalha seria especulação: autoria, população e duração do assentamento permanecem não registradas em fontes públicas.`,geography:`Clareira alta cercada por encostas rochosas e acessos que convergem para o acampamento.`,relation:{label:`Montanhas Cinzentas`,to:`/reinos/montanhas-cinzentas`}}),B({region:`montanhas`,id:`pico-da-vigia`,name:`Pico da Vigia`,category:`Pico`,summary:`Cume destacado no setor oriental das Montanhas Cinzentas.`,description:`O desenho do Atlas associa o nome a um pico dominante sobre vales e passagens próximas. A função de observação é uma leitura do topônimo, não prova de torre ou guarnição atual; acesso, altitude e ocupantes são desconhecidos.`,geography:`Pico de grande visibilidade regional, com encostas abruptas representadas na carta.`,relation:{label:`Montanhas Cinzentas`,to:`/reinos/montanhas-cinzentas`}}),B({region:`montanhas`,id:`fortaleza-esquecida`,name:`A Fortaleza Esquecida`,category:`Ruína fortificada`,summary:`Fortificação remota assinalada a leste da cordilheira, fora dos redutos de governo conhecido.`,description:`O Atlas preserva um nome que já expressa perda documental. Não há registro público de construtores, queda ou habitantes; mesmo sua condição de ruína é inferida pelo isolamento do símbolo e deve permanecer contestada até nova fonte.`,geography:`Fortificação sobre relevo elevado no limite nordeste conhecido da cordilheira.`,relation:{label:`Montanhas Cinzentas`,to:`/reinos/montanhas-cinzentas`},truthStatus:`disputed`}),B({region:`nevoeiro`,id:`ilhas-do-nevoeiro`,name:`Ilhas do Nevoeiro`,category:`Arquipélago`,summary:`Grupo insular desenhado no extremo nordeste do mapa, separado das coroas continentais.`,description:`A carta distingue várias ilhas entre bancos de névoa e mar aberto. Nenhum porto, povo soberano ou rota segura está confirmado no acervo textual; o registro reconhece somente o arquipélago e sua posição relativa.`,geography:`Ilhas rochosas dispersas em águas frias e frequentemente encobertas.`,relation:{label:`Atlas oficial`,to:`/atlas`}}),B({region:`valoria`,id:`campo-belo`,name:`Campo Belo`,category:`Povoado rural`,summary:`Assentamento das planícies de Valoria representado entre áreas agrícolas e travessias fluviais.`,description:`O símbolo da carta situa Campo Belo em terreno aberto ligado ao corredor de Valória. Produção, população e família governante não foram registradas; sua leitura como povoado agrário decorre apenas da posição entre campos desenhados.`,geography:`Planície cultivável próxima a cursos d’água e caminhos de travessia.`,relation:{label:`Valoria`,to:`/reinos/valoria`}}),B({region:`valoria`,id:`ponte-dourada`,name:`Ponte Dourada`,category:`Ponte`,summary:`Travessia nomeada no eixo oriental das planícies valorianas.`,description:`O Atlas marca uma ponte sobre curso d’água a leste do núcleo agrário. O material, a origem do nome e a autoridade que cobra passagem são desconhecidos; não deve ser confundida com as Sete Pontes de Valóris sem documento que prove essa relação.`,geography:`Travessia fluvial em corredor de planície, com acessos pelas duas margens.`,relation:{label:`Valoria`,to:`/reinos/valoria`}}),B({region:`ravenhold`,id:`muralha-de-pedra`,name:`Muralha de Pedra`,category:`Muralha`,summary:`Obra defensiva linear assinalada na fronteira de Ravenhold.`,description:`O traço fortificado da carta acompanha o limite ocidental de um corredor militar. Extensão, construtores e estado de conservação não estão documentados; o verbete evita transformá-la em fronteira política absoluta.`,geography:`Linha defensiva sobre planalto, vinculada a estradas e terrenos abertos.`,relation:{label:`Ravenhold`,to:`/reinos/ravenhold`}}),B({region:`ravenhold`,id:`campo-de-treinamento`,name:`Campo de Treinamento`,category:`Instalação militar`,summary:`Área militar nomeada nas proximidades das fortalezas centrais de Ravenhold.`,description:`A carta registra um campo aberto com função de treino, mas não informa qual legião, casa ou contingente o utiliza em 1204 d.C. Exercícios, capacidade e regras de acesso permanecem não registrados.`,geography:`Terreno nivelado de planalto, ligado por estrada a núcleos fortificados.`,relation:{label:`Ravenhold`,to:`/reinos/ravenhold`}}),B({region:`ravenhold`,id:`rio-torrente`,name:`Rio Torrente`,category:`Rio`,summary:`Curso d’água nomeado que atravessa a faixa meridional de Ravenhold.`,description:`O rio aparece como corredor natural entre planaltos e zonas fortificadas. Nascente, vazão sazonal e navegabilidade não possuem medição pública; qualquer uso militar ou comercial além do desenho cartográfico é desconhecido.`,geography:`Rio de planalto com direção regional indicada pelo raster, sem hidrografia detalhada.`,relation:{label:`Ravenhold`,to:`/reinos/ravenhold`}}),B({region:`ravenhold`,id:`fortaleza-solar`,name:`Fortaleza Solar`,category:`Fortaleza`,summary:`Fortaleza assinalada ao sul dos anéis centrais de Ravenhold.`,description:`O símbolo mostra uma obra defensiva conectada à malha oriental, mas nenhuma fonte pública identifica comandante, casa guardiã ou origem do epíteto Solar. Sua condição atual deve ser tratada como não registrada.`,geography:`Elevação fortificada próxima a estrada e ao sistema de rios do planalto.`,relation:{label:`Ravenhold`,to:`/reinos/ravenhold`}}),B({region:`sombras`,id:`necropole-de-valthor`,name:`Necrópole de Valthor`,category:`Necrópole`,summary:`Complexo funerário nomeado nas Terras Sombrias, a leste das rotas vigiadas.`,description:`O Atlas confirma o topônimo e um conjunto de estruturas em área interditada. Quem foi sepultado, quando o lugar recebeu o nome e se Valthor designa pessoa, povo ou cidade perdida são questões não registradas; relatos de atividade sobrenatural permanecem rumor.`,geography:`Ruínas funerárias em terreno seco, próximas a estradas abandonadas e zonas contaminadas.`,relation:{label:`Terras Sombrias`,to:`/locais/terras-sombrias`},status:`Acesso interdito`}),B({region:`sylvaris`,id:`clarifonte`,name:`Clarifonte`,category:`Assentamento`,summary:`Assentamento florestal desenhado junto a uma fonte ou curso d’água de Sylvaris.`,description:`A carta preserva Clarifonte entre árvores e água, sem distinguir vila, santuário ou posto de margem. População, círculo responsável e acesso para estrangeiros não estão registrados; a associação hídrica decorre apenas do nome e do desenho.`,geography:`Clareira arborizada junto a água corrente no interior de Sylvaris.`,relation:{label:`Sylvaris`,to:`/reinos/sylvaris`}}),B({region:`sylvaris`,id:`enaril`,name:`Enaril`,category:`Assentamento`,summary:`Núcleo nomeado no setor central da Floresta Antiga.`,description:`Enaril aparece como ponto habitado entre trilhas e copas densas. Não há fonte pública que esclareça governo, idade ou função ritual; sua existência cartográfica não autoriza tratar o local como cidade aberta.`,geography:`Assentamento sob copa fechada, conectado a trilhas internas não publicadas.`,relation:{label:`Sylvaris`,to:`/reinos/sylvaris`}}),B({region:`sylvaris`,id:`narin-falas`,name:`Narin’falas`,category:`Assentamento`,summary:`Topônimo élfico preservado no sul da Floresta Antiga.`,description:`O Atlas situa Narin’falas em área arborizada próxima aos caminhos meridionais. Tradução, população e relação com os Círculos da Memória permanecem conhecidas apenas pelos povos locais ou não registradas no arquivo comum.`,geography:`Bosque meridional de Sylvaris, entre elevações suaves e trilhas sazonais.`,relation:{label:`Sylvaris`,to:`/reinos/sylvaris`}}),B({region:`sylvaris`,id:`vale-das-estrelas`,name:`Vale das Estrelas`,category:`Vale`,summary:`Vale nomeado na borda sudoeste da Floresta Antiga.`,description:`O nome aparece sobre uma depressão aberta entre bosques. Não existe registro público de observatório, culto ou acontecimento celeste associado; tais leituras devem permanecer rumor até testemunho adicional.`,geography:`Vale de clareiras amplas cercado por mata e colinas baixas.`,relation:{label:`Sylvaris`,to:`/reinos/sylvaris`}}),B({region:`kar-dum`,id:`portao-de-karak`,name:`Portão de Karak`,category:`Portão fortificado`,summary:`Entrada monumental assinalada na face ocidental das montanhas de Kar-Dûm.`,description:`A carta reconhece um portão de superfície, mas não revela as galerias que ele protege. Guarnição, juramentos de entrada e significado de Karak são conhecidos apenas pelos registros anões ou permanecem não publicados.`,geography:`Portal escavado em encosta rochosa com acesso a redes subterrâneas não cartografadas.`,relation:{label:`Kar-Dûm`,to:`/reinos/kar-dum`}}),B({region:`kar-dum`,id:`salao-dos-forgemantes`,name:`Salão dos Forgemantes`,category:`Salão subterrâneo`,summary:`Salão de ofício nomeado na carta de Kar-Dûm, próximo às rotas centrais de forja.`,description:`A grafia do topônimo foi transcrita do raster e pode refletir tradição local ou erro de copista. Função, linhagens de ofício e acesso atual não foram confirmados por fonte textual; o registro conserva a forma cartográfica sem corrigi-la por conjectura.`,geography:`Complexo subterrâneo ligado a galerias de forja e ventilação.`,relation:{label:`Kar-Dûm`,to:`/reinos/kar-dum`},truthStatus:`disputed`}),B({region:`kar-dum`,id:`minas-de-ferro`,name:`Minas de Ferro`,category:`Minas`,summary:`Distrito de extração indicado no setor meridional de Kar-Dûm.`,description:`O símbolo cartográfico identifica minas de ferro sem informar veios ativos, salão proprietário ou volume de produção. Galerias internas não aparecem no mapa público, e sua condição de segurança é desconhecida.`,geography:`Encostas e galerias subterrâneas em zona mineral da cordilheira central.`,relation:{label:`Kar-Dûm`,to:`/reinos/kar-dum`}}),B({region:`brumas`,id:`ancoradouro-dos-piratas`,name:`Ancoradouro dos Piratas`,category:`Ancoradouro`,summary:`Enseada nomeada entre as ilhas ocidentais do Arquipélago das Brumas.`,description:`A carta assinala um abrigo marítimo ligado a piratas, mas não identifica frota, capitão ou permanência de ocupação. A designação pode ser advertência de navegadores e não reconhecimento de autoridade local.`,geography:`Enseada protegida por ilhas, recifes e canais rasos dependentes de piloto.`,relation:{label:`Arquipélago das Brumas`,to:`/locais/arquipelago-das-brumas`}}),B({region:`vul-gar`,id:`cidade-de-gron`,name:`Cidade de Gron`,category:`Cidade`,summary:`Cidade oriental registrada em território cultural de Vul’Gar.`,description:`O Atlas confirma um núcleo murado associado ao nome Gron. Não há fonte pública suficiente para ligá-lo a uma pessoa específica, definir clã governante ou população; a forma “cidade” reproduz a classificação cartográfica.`,geography:`Núcleo urbano em planalto seco, próximo a rotas de clãs e fontes dispersas.`,relation:{label:`Vul’Gar`,to:`/reinos/vul-gar`}}),B({region:`vul-gar`,id:`fortaleza-kring`,name:`Fortaleza Kring`,category:`Fortaleza`,summary:`Reduto oriental marcado entre os planaltos de Vul’Gar.`,description:`Uma estrutura fortificada aparece junto ao topônimo Kring. Sua casa, clã, função e relação com a Cidade de Gron são desconhecidos; qualquer vínculo de vassalagem seria invenção sem documento adicional.`,geography:`Fortaleza em elevação árida, voltada para corredores de aproximação do leste.`,relation:{label:`Vul’Gar`,to:`/reinos/vul-gar`}}),B({region:`vul-gar`,id:`acampamento-dos-clas`,name:`Acampamento dos Clãs`,category:`Acampamento`,summary:`Concentração de tendas assinalada no sul de Vul’Gar.`,description:`O raster representa um grande acampamento, mas não registra quais clãs o ocupam nem se a reunião é sazonal. O nome plural impede atribuir o lugar a uma única autoridade e reforça sua condição política não unificada.`,geography:`Planície seca apta a acampamentos móveis, próxima a rotas e pontos de água não nomeados.`,relation:{label:`Vul’Gar`,to:`/reinos/vul-gar`}}),B({region:`zharak`,id:`porto-da-serpente`,name:`Porto da Serpente`,category:`Porto`,summary:`Porto desenhado no limite entre os caminhos áridos e as águas meridionais.`,description:`O Atlas registra cais e embarcações junto ao topônimo, confirmando função portuária sem revelar governantes, mercadorias ou origem do emblema da serpente. Sua soberania permanece não registrada.`,geography:`Ancoradouro costeiro em margem árida, conectado a rotas de poços e caravanas.`,relation:{label:`Deserto de Zharak`,to:`/locais/deserto-de-zharak`}}),B({region:`zharak`,id:`oasis-perdido`,name:`Oásis Perdido`,category:`Oásis`,summary:`Fonte interior nomeada entre as rotas do Deserto de Zharak.`,description:`O símbolo mostra água e vegetação em zona desértica, mas o epíteto Perdido impede presumir acesso atual. Coordenadas são regionais, vazão e habitantes são desconhecidos, e relatos de cidade soterrada permanecem rumor.`,geography:`Depressão desértica com água e vegetação isoladas entre salinas e rocha.`,relation:{label:`Deserto de Zharak`,to:`/locais/deserto-de-zharak`},status:`Localização aproximada`}),B({region:`zharak`,id:`cidade-da-areia`,name:`Cidade da Areia`,category:`Cidade`,summary:`Cidade murada representada no setor oriental do Deserto de Zharak.`,description:`A carta confirma um assentamento de porte urbano cercado por dunas e caminhos de caravana. Nome antigo, população, poço fundador e forma de governo não foram registrados; o verbete não atribui soberania inexistente.`,geography:`Cidade em terreno árido, ligada a rotas de caravana e fontes não detalhadas.`,relation:{label:`Deserto de Zharak`,to:`/locais/deserto-de-zharak`}})],H=[e({id:`farol-das-sete-mares`,name:`Farol das Sete Marés`,subtitle:`A luz que responde às correntes`,summary:`Torre costeira de Eldemar cujas sete câmaras de luz orientam embarcações por corrente, calado e direção do vento.`,description:`Erguido sobre uma agulha de basalto ao sul do Porto de Eldemar, o Farol das Sete Marés não projeta uma única chama. Sete lanternas protegidas por lâminas de mica são abertas em combinações diferentes, formando um código que informa corrente, neblina, recife e autorização de entrada. O posto tornou-se indispensável depois que sucessivos naufrágios demonstraram que um simples ponto luminoso podia conduzir navios ao canal errado. Os nomes dos primeiros faroleiros foram perdidos num incêndio de arquivo; a instituição atual, porém, é documentada em livros de óleo, turnos e resgates.`,category:`Farol e posto marítimo`,status:`Operacional`,kingdom:`Eldemar`,location:`Costa meridional de Eldemar`,period:`Fundação contestada; operação atual documentada`,climate:`Marítimo, com sal, ventos fortes e neblina de corrente fria.`,geography:`Agulha de basalto ligada à costa por uma ponte estreita e alcançada por uma doca de maré baixa.`,architecture:`Torre octogonal de pedra escura, sete câmaras de mica e depósitos de óleo abaixo da linha principal de luz.`,culture:`Faroleiros são escolhidos entre pilotos aposentados, vidreiros e vigias; nenhuma família possui direito hereditário ao posto.`,currentSituation:`Duas câmaras precisam de nova mica, e a guilda debate se deve aceitar material de Kar-Dûm ou manter o vidro costeiro tradicional.`,rumors:[`Uma oitava combinação de luzes indicaria uma rota de evacuação Rivs; a afirmação é baseada em rumor e não aparece no código público.`],narrativeImportance:`Torna a navegação de Eldemar uma prática coletiva e oferece um ponto de observação para chegadas clandestinas, tempestades e alterações do Mar das Estrelas.`,historicalSources:[`Livros de óleo do Conselho das Marés`,`Cadernos de pilotos do canal sul`,`Inventário das sete câmaras`],knowledgeStatus:`documented`,confidence:`high`,relations:[{label:`Eldemar`,to:`/reinos/eldemar`},{label:`Porto de Eldemar`,to:`/cidades/porto-de-eldemar`},{label:`Mar das Estrelas`,to:`/locais/mar-das-estrelas`},{label:`Juramento do Horizonte`,to:`/religioes/juramento-do-horizonte`}]}),e({id:`mosteiro-da-brasa-tardia`,name:`Mosteiro da Brasa Tardia`,subtitle:`Abrigo antes de doutrina`,summary:`Casa de passagem de Winterfeld onde calor, sopa e registro de viajantes precedem qualquer rito religioso.`,description:`O Mosteiro da Brasa Tardia ocupa uma garganta protegida do vento entre Winterheim e os vales setentrionais. Seus guardiões mantêm uma fornalha contínua, dormitórios baixos e um muro de pedras gravadas com as datas em que viajantes foram encontrados na neve. Embora associado à Vigília da Última Brasa, o abrigo não exige profissão de fé: a regra inscrita sobre a porta determina que perguntas só podem ser feitas depois que a pessoa estiver aquecida. A fundação exata é desconhecida, pois três tradições locais atribuem a primeira chama a comunidades diferentes.`,category:`Mosteiro e abrigo de estrada`,status:`Habitado`,kingdom:`Winterfeld`,location:`Garganta ocidental de Winterheim`,period:`Anterior ao registro unificado dos jarls`,climate:`Subártico, com ventos canalizados pela garganta e nevascas de curta visibilidade.`,geography:`Terraço rochoso próximo a uma fonte morna e a uma passagem sazonal.`,architecture:`Pedra encaixada, corredores baixos, teto de turfa e uma fornalha central ligada a bancos aquecidos.`,culture:`O serviço é temporário e inclui religiosos, guias, curandeiros e antigos devedores de abrigo.`,currentSituation:`O degelo abriu uma fissura no depósito oriental; monges e engenheiros aguardam uma inspeção conjunta de Winterheim e Kar-Dûm.`,rumors:[`Algumas pedras do muro teriam nomes apagados de sobreviventes Nimbus; a leitura é contestada e não há inscrição autenticada.`],narrativeImportance:`Materializa a lei de hospitalidade de Winterfeld e cria um encontro plausível entre viajantes, jarls, gigantes e expedições do norte.`,historicalSources:[`Livro das Porções`,`Pedras de resgate do pátio`,`Atas de inspeção dos jarls`],knowledgeStatus:`people-only`,confidence:`medium`,relations:[{label:`Winterfeld`,to:`/reinos/winterfeld`},{label:`Winterheim`,to:`/cidades/winterheim`},{label:`Vigília da Última Brasa`,to:`/religioes/vigilia-ultima-brasa`},{label:`Ordem da Última Brasa`,to:`/faccoes/ordem-ultima-brasa`}]}),e({id:`arquivo-de-pedra`,name:`Arquivo de Pedra`,subtitle:`Onde toda falha recebe uma placa`,summary:`Repositório de Kar-Dûm que preserva projetos aprovados, erros de engenharia e os nomes de quem interrompeu obras perigosas.`,description:`O Arquivo de Pedra ocupa galerias secas acima de Thur-Kar e reúne milhares de placas de ardósia organizadas por salão, material e grau de risco. Ao contrário dos salões de glória, ele preserva obras recusadas, pontes que cederam e cálculos corrigidos; apagar uma falha é considerado mais vergonhoso do que cometê-la e registrá-la. O público pode consultar cópias de superfície, enquanto mapas de ventilação e lacres profundos permanecem conhecidos apenas pelos ofícios responsáveis. Uma ala inteira relativa aos Túneis Vazios foi perdida durante uma evacuação, e nenhuma reconstrução posterior é tratada como equivalente ao original.`,category:`Arquivo técnico`,status:`Consulta parcial`,kingdom:`Kar-Dûm`,location:`Galerias superiores de Thur-Kar`,period:`Ampliado após a Guerra dos Túneis Vazios`,climate:`Subterrâneo seco e estável, com controle rigoroso de fuligem e umidade.`,geography:`Galerias elevadas ligadas ao vazio central por pontes de serviço.`,architecture:`Nichos numerados, estantes de pedra inclinada, portas corta-fogo e canais de ventilação independentes.`,culture:`Aprendizes copiam relatórios de erro antes de receber autorização para assinar projetos próprios.`,currentSituation:`O Conselho dos Nove discute o acesso dos Seladores a placas que podem descrever estruturas do Véu.`,rumors:[`Um índice apagado mencionaria um décimo salão; a alegação é contestada e o fragmento não foi apresentado à auditoria pública.`],narrativeImportance:`Conecta ofício, memória e política de segurança, além de fornecer evidências materiais para investigações sobre Fraturas e Fulgarion.`,historicalSources:[`Índice dos Nove Salões`,`Placas de falha pública`,`Catálogo posterior aos Túneis Vazios`],knowledgeStatus:`people-only`,confidence:`high`,relations:[{label:`Kar-Dûm`,to:`/reinos/kar-dum`},{label:`Thur-Kar`,to:`/cidades/thur-kar`},{label:`Guerra dos Túneis Vazios`,to:`/guerras/guerra-dos-tuneis-vazios`},{label:`Vigia de Pedra`,to:`/criaturas/vigia-de-pedra`}]}),e({id:`jardim-das-pontes-silenciosas`,name:`Jardim das Pontes Silenciosas`,subtitle:`Memória sem estátua`,summary:`Jardim memorial de Sylvaris onde pontes removíveis conduzem a clareiras dedicadas a comunidades deslocadas.`,description:`O Jardim das Pontes Silenciosas foi cultivado na margem externa de Lethariel para lembrar aldeias que acolheram perseguidos e depois desapareceram dos mapas públicos. Não existem estátuas individuais: cada clareira preserva espécies, sementes e materiais associados a uma comunidade, enquanto pequenas pontes são recolhidas durante períodos de luto ou quando descendentes pedem privacidade. Os nomes completos permanecem conhecidos apenas pelos Círculos e pelas famílias autorizadas. Visitantes recebem um roteiro público que explica a história sem revelar rotas de refúgio ainda utilizáveis.`,category:`Jardim memorial`,status:`Protegido`,kingdom:`Sylvaris`,location:`Margem externa de Lethariel`,period:`Organizado depois da Caça às Bruxas`,climate:`Úmido e ameno sob copa manejada.`,geography:`Clareiras ligadas por canais rasos e passarelas que podem ser removidas sem ferir raízes.`,architecture:`Pontes leves, bancos de madeira caída, placas vegetais e casas discretas para guardiões.`,culture:`O direito de lembrar não anula o direito de ocultar pessoas ainda vulneráveis.`,currentSituation:`Uma ponte permanece recolhida por decisão de famílias que identificaram buscas recentes por antigas rotas Bellatrix.`,rumors:[`Canções afirmam que uma clareira responde à presença Kayler; os guardiões classificam a versão como interpretação poética.`],narrativeImportance:`Expõe a tensão entre memória pública e proteção, dando consequência civil à perseguição sem transformar refugiados em decoração heroica.`,historicalSources:[`Roteiro público dos Círculos`,`Catálogo botânico das clareiras`,`Atas de custódia com nomes omitidos`],knowledgeStatus:`people-only`,confidence:`high`,relations:[{label:`Sylvaris`,to:`/reinos/sylvaris`},{label:`Lethariel`,to:`/cidades/lethariel`},{label:`Caça às Bruxas`,to:`/historia/caca-bruxas`},{label:`Crônicas Perdidas de Sylvaris`,to:`/biblioteca/cronicas-perdidas-de-sylvaris`}]}),e({id:`mercado-dos-tres-ventos`,name:`Mercado dos Três Ventos`,subtitle:`Preço, procedência e passagem`,summary:`Feira de Valoria onde caravanas do rio, das planícies e do sudeste submetem pesos e contratos a uma auditoria comum.`,description:`O Mercado dos Três Ventos se reúne num campo elevado próximo a Valóris, no encontro das rotas fluvial, oriental e meridional. Toldos são organizados por procedência, não por riqueza, e toda balança precisa receber o selo temporário dos magistrados de peso antes da abertura. A feira ganhou importância durante anos de cheia, quando seus depósitos secos impediram que o comércio fosse concentrado dentro das muralhas da capital. Comunidades de Zharak e Vul’Gar mantêm intérpretes próprios e contestam taxas que a corte tenta apresentar como antigas.`,category:`Feira e entreposto`,status:`Sazonal e ativo`,kingdom:`Valoria`,location:`Planície elevada a sudeste de Valóris`,period:`Registro contínuo desde a Era das Coroas`,climate:`Temperado, exposto a ventos secos do leste e chuvas do corredor fluvial.`,geography:`Terraço natural acima da zona de cheia, junto a três estradas e um cais sazonal.`,architecture:`Depósitos de tijolo, pavilhões desmontáveis, torre de pesos e cisternas públicas.`,culture:`Contratos são lidos em mais de um idioma quando envolvem comunidades de fronteira.`,currentSituation:`A próxima feira ocorrerá sob auditoria ampliada depois da descoberta de pesos adulterados em dois armazéns nobres.`,rumors:[`Agentes da Corte de Cinza comprariam grão sob nomes falsos; a acusação ainda não possui prova pública.`],narrativeImportance:`Mostra como alimento, idioma e crédito conectam Valoria ao oriente, oferecendo cenário para diplomacia, espionagem e crises de abastecimento.`,historicalSources:[`Selos anuais dos magistrados`,`Contratos trilíngues preservados`,`Cadastros dos depósitos elevados`],knowledgeStatus:`documented`,confidence:`high`,relations:[{label:`Valoria`,to:`/reinos/valoria`},{label:`Valóris`,to:`/cidades/valoris`},{label:`Deserto de Zharak`,to:`/locais/deserto-de-zharak`},{label:`Corte de Cinza`,to:`/faccoes/corte-de-cinza`}]}),e({id:`torre-da-chuva-negra`,name:`Torre da Chuva Negra`,subtitle:`Um observatório confundido com mau presságio`,summary:`Ruína de fronteira de Ravenhold cujos coletores escurecidos registravam chuva, poeira e fumaça antes das marchas.`,description:`A Torre da Chuva Negra ergue-se num planalto oriental, distante o bastante das estradas principais para ter sobrevivido à expansão de Ravencastle. Canais de cobre conduziam chuva a vasos graduados, enquanto placas claras recolhiam poeira transportada do leste; quando fuligem de grandes incêndios tingia a água, vigias baixavam um estandarte negro. Crônicas militares posteriores transformaram o procedimento em profecia de guerra. A função meteorológica é documentada, mas o construtor e a data exata permanecem não registrados.`,category:`Observatório em ruínas`,status:`Estável sob inspeção`,kingdom:`Ravenhold`,location:`Planalto oriental de Ravenhold`,period:`Provavelmente anterior à Casa Corven`,climate:`Continental e seco, com tempestades rápidas e poeira trazida das fronteiras.`,geography:`Esporão de rocha sobre uma bacia rasa, visível de antigas estradas de patrulha.`,architecture:`Torre cilíndrica, canais de cobre corroído, nichos de medição e plataforma de sinais.`,culture:`Veteranos reformistas usam o lugar para ensinar a diferença entre observação, ordem militar e propaganda.`,currentSituation:`Uma equipe civil reabriu os coletores para comparar incêndios reais com relatos de ataques de fronteira.`,rumors:[`Contrabandistas dizem ouvir chuva dentro da torre em noites secas; nenhuma inspeção confirmou o fenômeno.`],narrativeImportance:`Fornece evidência contra operações de bandeira falsa e revela como dados comuns podem ser convertidos em presságio político.`,historicalSources:[`Placas meteorológicas recuperadas`,`Ordens de sinalização das legiões`,`Relatório civil de estabilização`],knowledgeStatus:`documented`,confidence:`medium`,relations:[{label:`Ravenhold`,to:`/reinos/ravenhold`},{label:`Ravencastle`,to:`/cidades/ravencastle`},{label:`Vigília do Sol Negro`,to:`/religioes/vigilia-sol-negro`},{label:`Códice dos Estandartes Baixos`,to:`/biblioteca/codice-dos-estandartes-baixos`}]})],U=[...[e({id:`floresta-antiga`,name:`Floresta Antiga`,subtitle:`Onde caminhos guardam memória`,summary:`Grande floresta do oeste, lar de Sylvaris e refúgio de Sirius durante a perseguição.`,description:`A floresta reúne zonas manejadas, áreas sagradas e regiões nunca ocupadas. Trilhas mudam porque pontes são recolhidas, vegetação cresce rápido e guardiões desviam invasores — não porque o território ignore as leis naturais.`,image:`/assets/images/locations/jornada-floresta-antiga-banner.webp`,thumbnail:`/assets/images/locations/jornada-floresta-antiga-card.webp`,category:`Floresta`,status:`Protegida`,kingdom:`Sylvaris`,location:`Oeste de Avernor`,relations:[{label:`Sylvaris`,to:`/reinos/sylvaris`}]}),e({id:`mar-das-estrelas`,name:`Mar das Estrelas`,subtitle:`A rota de Eldemar`,summary:`Mar meridional conhecido por plâncton luminoso, bancos de neblina e rotas comerciais disputadas.`,description:`O brilho noturno permite navegar sem tochas em algumas estações, mas confunde a percepção de distância. Correntes frias trazem grandes animais, incluindo os avistamentos atribuídos ao kraken.`,category:`Mar`,status:`Navegado`,location:`Sul de Avernor`,relations:[{label:`Eldemar`,to:`/reinos/eldemar`},{label:`Kraken de Eldemar`,to:`/criaturas/kraken-de-eldemar`}]}),e({id:`deserto-de-zharak`,name:`Deserto de Zharak`,subtitle:`Sal, vento e cidades de poço`,summary:`Terras áridas cujo povoamento depende de aquíferos antigos e rotas de sal.`,description:`Comunidades constroem ao redor de poços compartilhados e usam torres de vento para resfriar depósitos. Guerras abertas são raras perto da água, pois contaminar um aquífero condenaria vencedores e vencidos.`,category:`Deserto`,status:`Habitado`,location:`Sudeste de Avernor`,relations:[{label:`Lobo de Vidro`,to:`/criaturas/lobo-de-vidro`},{label:`Espelho de Sal`,to:`/portais/espelho-de-sal`}]}),e({id:`arquipelago-das-brumas`,name:`Arquipélago das Brumas`,subtitle:`Ilhas sem uma só bandeira`,summary:`Conjunto de ilhas que abriga pescadores, observatórios, contrabandistas e portos independentes.`,description:`Canais rasos impedem grandes frotas e favorecem pilotos locais. A ausência de autoridade única cria liberdade comercial, mas também torna resgates e julgamentos dependentes de pactos entre vilas.`,category:`Arquipélago`,status:`Fragmentado`,location:`Sudoeste de Avernor`,relations:[{label:`Eldemar`,to:`/reinos/eldemar`}]}),e({id:`terras-sombrias`,name:`Terras Sombrias`,subtitle:`A fronteira marcada pela peste`,summary:`Região oriental abandonada após uma doença que deixou cidades vazias e solos contaminados por metais.`,description:`Histórias sobre mortos-vivos exageram um perigo real: minas abertas contaminaram água e a peste eliminou comunidades inteiras. Expedições usam máscaras de carvão, analisam poços e evitam ruínas instáveis.`,category:`Zona interditada`,status:`Acesso restrito`,location:`Extremo leste`,relations:[{label:`Necromancia`,to:`/necromancia/necromancia`}]}),e({id:`mar-interior`,name:`Mar Interior`,subtitle:`A água entre as coroas`,summary:`Sistema de lagos e estreitos que conecta rotas de Valoria, Sylvaris e Kar-Dûm.`,description:`Pontes e balsas fizeram do Mar Interior o principal corredor econômico do continente. As margens guardam ruínas Rivs e antigos postos das Doze Legiões.`,category:`Mar interior`,status:`Navegado`,location:`Centro-oeste de Avernor`,relations:[{label:`Arquivo Submerso`,to:`/lendas/arquivo-submerso`}]})].map(e=>({...e,...v[e.id]})),...V,...H],W=p([e({id:`o-ultimo-bruxo`,name:`I — O Último Bruxo`,subtitle:`O legado desperta`,summary:`Sirius recebe os pertences de Normus e descobre que a paz de seu isolamento foi construída sobre um pacto incompleto.`,description:`O primeiro volume acompanha a saída de Sirius da Floresta Antiga, o encontro com Elara e a abertura da carta cifrada de Normus. O conflito central não é dominar um poder novo, mas decidir em quem confiar quando reinos tentam transformar sua existência em vantagem política.`,category:`Saga de Sirius Kayler`,status:`Em desenvolvimento`,period:`Era atual`,relations:[{label:`Sirius Kayler`,to:`/personagens/sirius-kayler`},{label:`Elara`,to:`/personagens/elara`}],events:[`A entrega da herança`,`O salto de Elara`,`A estrada para Valoria`]}),e({id:`a-carta-e-a-tempestade`,name:`II — A Carta e a Tempestade`,subtitle:`Verdade em linguagem de cerco`,summary:`A cifra Bellatrix conduz Sirius e Elara às Montanhas Cinzentas enquanto Ravenhold fecha as passagens.`,description:`Fragmentos da carta revelam que a perseguição pode ter poupado membros das Casas Nimbus e Rivs. Para seguir a pista, o grupo precisa atravessar Valoria sem provocar intervenção real e alcançar a Fortaleza do Véu antes das primeiras neves.`,category:`Saga de Sirius Kayler`,status:`Planejado`,period:`Era atual`,relations:[{label:`Namídia Bellatrix`,to:`/personagens/namidia-bellatrix`},{label:`Fortaleza do Véu`,to:`/cidades/fortaleza-do-veu`}]}),e({id:`cronicas-perdidas-de-sylvaris`,name:`Crônicas Perdidas de Sylvaris`,subtitle:`Registros da Caça às Bruxas`,summary:`Compilação clandestina de testemunhos preservados pelos Círculos da Memória.`,description:`O texto reúne listas de refugiados, decisões controversas da Rainha e relatos sobre a morte de Namídia. Nomes de sobreviventes permanecem ocultos. O exemplar público é uma edição comentada, não o arquivo integral.`,category:`Crônica histórica`,status:`Acesso parcial`,origin:`Sylvaris`,period:`Caça às Bruxas`,relations:[{label:`Caça às Bruxas`,to:`/historia/caca-bruxas`}]}),e({id:`atlas-das-sete-rotas`,name:`Atlas das Sete Rotas`,subtitle:`Estradas, rios e custos de travessia`,summary:`Manual de cartógrafos que descreve deslocamento, pedágios, estações e riscos entre os principais reinos.`,description:`Atualizado por viajantes credenciados, o atlas registra distâncias por tempo e carga, não apenas por léguas. Divergências entre edições ajudam historiadores a reconstruir guerras, pontes destruídas e mudanças de fronteira.`,category:`Atlas`,status:`Atualizado anualmente`,origin:`Eldemar e Valoria`,relations:[{label:`Atlas de Avernor`,to:`/atlas`}]}),e({id:`tratado-das-linhagens`,name:`Tratado das Linhagens`,subtitle:`O que a magia é — e o que não é`,summary:`Estudo que diferencia magia hereditária das três Casas, artefatos rúnicos e práticas religiosas.`,description:`A obra insiste que pessoas sem sangue Kayler, Nimbus ou Rivs não podem aprender magia verdadeira. Técnicas rúnicas dependem de objetos e conhecimento artesanal; ritos religiosos organizam comunidades, mas não concedem o dom hereditário.`,category:`Tratado arcano`,status:`Preservado com lacunas`,origin:`Arquivo Rivs`,period:`Era da Magia`,relations:[{label:`Casa Kayler`,to:`/casas/kayler`},{label:`Casa Nimbus`,to:`/casas/nimbus`},{label:`Casa Rivs`,to:`/casas/rivs`}]}),e({id:`caderno-de-namidia`,name:`Caderno de Namídia`,subtitle:`Inventários que escondem pessoas`,summary:`Livro de administração da Fortaleza do Véu cuja contabilidade contém cifras sobre rotas de fuga.`,description:`Linhas aparentemente dedicadas a grãos, óleo e sal escondem nomes e destinos. O caderno comprova que Namídia organizou uma rede maior do que as histórias heroicas sugerem: dezenas de pessoas comuns mantiveram postos, mulas e abrigos.`,category:`Documento pessoal`,status:`Em decifração`,origin:`Fortaleza do Véu`,period:`Caça às Bruxas`,relations:[{label:`Namídia Bellatrix`,to:`/personagens/namidia-bellatrix`}]}),e({id:`livro-dos-caminhos-fechados`,name:`Livro dos Caminhos Fechados`,subtitle:`Por que uma estrada deixou de existir`,summary:`Registro de Sylvaris que documenta rotas recolhidas, seus motivos e as condições necessárias para uma possível reabertura.`,description:`O Livro dos Caminhos Fechados não é um mapa secreto nem um catálogo de atalhos. Cada verbete público descreve uma passagem que deixou de ser mantida por erosão, luto, risco ecológico, guerra ou pedido das comunidades ligadas a ela. Coordenadas utilizáveis são removidas das cópias abertas; permanecem o motivo, a autoridade responsável e a data de revisão. A prática impede que uma trilha desapareça da memória apenas porque sumiu do terreno, mas também evita que curiosidade histórica exponha refúgios e áreas de recuperação. Algumas folhas anteriores à Caça às Bruxas estão perdidas, e cópias humanas frequentemente inventam destinos para preencher as lacunas.`,category:`Registro territorial`,status:`Edição pública com coordenadas omitidas`,truthStatus:`redacted`,knowledgeStatus:`people-only`,confidence:`high`,origin:`Círculos da Memória de Sylvaris`,period:`Compilação contínua`,archivalOverview:`O códice preserva razões e responsabilidades associadas a rotas encerradas sem publicar caminhos capazes de ameaçar comunidades.`,provenance:`Colofões sazonais, atas dos Círculos e marcas botânicas permitem distinguir revisões autênticas de cópias de viajantes.`,publicKnowledge:[`Toda rota recolhida deve ter uma justificativa, um responsável e uma data de reavaliação.`],knowledgeGaps:[`Coordenadas de refúgio, nomes protegidos e folhas destruídas durante a perseguição não integram a edição pública.`],culturalReadings:[`Sylvaris o lê como compromisso com território e memória; mercadores estrangeiros o acusam de ocultar vantagens comerciais.`],historicalSources:[`Edição pública comentada`,`Atas sazonais dos Círculos`,`Catálogo de folhas perdidas`],disputedClaims:[`Cópias que prometem uma estrada direta até Lethariel não possuem proveniência autenticada.`],narrativeImportance:`Dá contexto às mudanças de rota da Floresta Antiga e sustenta investigações sem revelar automaticamente caminhos ainda sensíveis.`,imageBrief:`Códice élfico verde-escuro aberto sobre mesa de madeira caída, diagramas de pontes recolhidas sem mapa legível nem texto gerado.`,sections:[{title:`Critério de fechamento`,body:`A interrupção precisa registrar dano possível, consulta às comunidades e quem responderá pela revisão futura.`},{title:`Edição pública`,body:`Leitores recebem contexto histórico e ecológico, mas não direções capazes de reabrir a passagem por conta própria.`},{title:`Folhas perdidas`,body:`Incêndios, fuga e remoção deliberada deixaram lacunas que permanecem declaradas, nunca preenchidas como certeza.`},{title:`Uso contemporâneo`,body:`Elara e os guardiões consultam o livro quando rotas antigas reaparecem em cartas ligadas à perseguição.`}],relations:[{label:`Sylvaris`,to:`/reinos/sylvaris`},{label:`Floresta Antiga`,to:`/locais/floresta-antiga`},{label:`Jardim das Pontes Silenciosas`,to:`/locais/jardim-das-pontes-silenciosas`},{label:`Elara`,to:`/personagens/elara`}]}),e({id:`registro-das-aguas-partilhadas`,name:`Registro das Águas Partilhadas`,subtitle:`Tratados que começam no poço`,summary:`Coleção multilíngue de acordos sobre poços, canais e travessias entre Valoria, cidades de Zharak e clãs de Vul’Gar.`,description:`O Registro das Águas Partilhadas reúne cópias de tratados que não pertencem a uma única coroa. Cada acordo aparece nos idiomas dos signatários, acompanhado por medidas de vazão, períodos de seca e obrigações de reparo. A coleção demonstra que comunidades consideradas rivais suspenderam hostilidades perto de poços muito antes de diplomatas transformarem a prática em lei escrita. Nem todos os pactos continuam vigentes: canais mudaram, assentamentos desapareceram e alguns selos são contestados. A edição pública identifica essas diferenças e se recusa a apresentar costume vivo como concessão histórica de Valoria.`,category:`Coleção de tratados`,status:`Vigência variável por documento`,truthStatus:`documented`,knowledgeStatus:`documented`,confidence:`high`,origin:`Copistas de Valoria, Zharak e Vul’Gar`,period:`Documentos de diferentes eras`,archivalOverview:`A coleção preserva pactos de água como acordos multilaterais e materiais, não como prova de soberania de um povo sobre outro.`,provenance:`Selos, traduções paralelas, marcas de vazão e testemunhos comunitários permitem verificar a maioria dos documentos.`,publicKnowledge:[`Poços de trégua e reparos compartilhados antecedem várias fronteiras políticas atuais.`],knowledgeGaps:[`Três pactos citam assentamentos não localizados e dois anexos de rota foram perdidos.`],culturalReadings:[`Valoria enfatiza a força contratual; comunidades de Zharak e Vul’Gar destacam que o costume existia antes da escrita cortesã.`],historicalSources:[`Placas de poço`,`Cópias das Sete Pontes`,`Memórias orais verificadas pelos clãs`],disputedClaims:[`Um selo Arden em cópia tardia não prova que a Casa tenha criado ou governado a trégua original.`],narrativeImportance:`Oferece base histórica para evitar guerra por água e evidencia falsificações usadas para justificar pedágios ou ocupação.`,imageBrief:`Três conjuntos de documentos, placas de argila e tigela de água sobre mesa diplomática, selos diferentes e nenhuma escrita legível.`,sections:[{title:`A trégua do poço`,body:`A regra suspende violência no círculo de acesso e obriga todos os presentes a impedir contaminação.`},{title:`Medidas incompatíveis`,body:`Copistas registram equivalências entre calendários, vazões e unidades para impedir vantagem por tradução.`},{title:`Pactos contestados`,body:`Documentos sem comunidade viva ou sem fonte de água localizável permanecem históricos, não automaticamente vigentes.`},{title:`Uso na crise atual`,body:`Mercadores e emissários consultam a coleção quando secas reduzem poços orientais e elevam a tensão com Ravenhold.`}],relations:[{label:`Valoria`,to:`/reinos/valoria`},{label:`Deserto de Zharak`,to:`/locais/deserto-de-zharak`},{label:`Orcs`,to:`/povos/orcs`},{label:`Mercado dos Três Ventos`,to:`/locais/mercado-dos-tres-ventos`}]}),e({id:`codice-dos-estandartes-baixos`,name:`Códice dos Estandartes Baixos`,subtitle:`Ordens recusadas, civis protegidos e comando sob revisão`,summary:`Compilação de Ravenhold dedicada a decisões militares interrompidas por oficiais, soldados e comunidades durante a perseguição.`,description:`O Códice dos Estandartes Baixos foi organizado depois que a Caça às Bruxas revelou a insuficiência de registrar apenas ordens cumpridas. Suas páginas reúnem cópias de comandos recusados, justificativas apresentadas em conselho, punições posteriores e testemunhos de civis que sobreviveram graças à demora ou à desobediência. O título vem do gesto de baixar o estandarte de uma unidade quando sua autoridade é suspensa para investigação. A obra não transforma toda recusa em heroísmo: algumas esconderam deserção, pilhagem ou rivalidade. Nomes de testemunhas vulneráveis são omitidos da edição pública, e anexos de responsabilidade ainda passam por auditoria.`,category:`Crônica militar e cívica`,status:`Edição pública revisada`,truthStatus:`documented`,knowledgeStatus:`documented`,confidence:`high`,origin:`Arquivo das Ordens de Ravencastle`,period:`Compilado após a Caça às Bruxas`,archivalOverview:`O códice documenta consciência, responsabilidade e consequência dentro de uma cultura militar sem absolver o aparato de perseguição.`,provenance:`Ordens numeradas, registros de guarnição e depoimentos civis convergem em parte substancial dos casos publicados.`,publicKnowledge:[`Ravenhold preserva ordens recusadas e distingue suspensão legal, desobediência responsável e abandono criminoso.`],knowledgeGaps:[`Anexos selados, nomes protegidos e cadeias de comando incompletas impedem atribuição definitiva em alguns episódios.`],culturalReadings:[`Reformistas o tratam como base de direito cívico; tradicionalistas afirmam que ele enfraquece comando em fronteira.`],historicalSources:[`Arquivo das Ordens`,`Atas do Senado de Estandartes`,`Depoimentos de bairros de Ravencastle`],disputedClaims:[`Listas tardias que atribuem toda recusa a uma única facção não coincidem com os livros de guarnição.`],narrativeImportance:`Coloca a disputa sucessória de Ravenhold diante de provas históricas e oferece ferramentas para avaliar ordens atuais de bandeira falsa.`,imageBrief:`Códice militar de couro escuro, estandarte dobrado, selo senatorial e folhas de ordens sobre mesa austera, sem texto legível.`,sections:[{title:`Por que o arquivo mudou`,body:`A perseguição mostrou que registrar somente execução tornava invisíveis escolhas, recusas e alternativas disponíveis.`},{title:`Casos preservados`,body:`Cada entrada separa ordem, contexto, resposta, consequência disciplinar e testemunho civil quando existe.`},{title:`Nomes protegidos`,body:`A edição pública omite pessoas que poderiam sofrer represália sem apagar seu papel histórico.`},{title:`Debate no presente`,body:`A sucessão Corven e ataques de fronteira renovaram a disputa sobre quando consciência integra o juramento militar.`}],relations:[{label:`Ravenhold`,to:`/reinos/ravenhold`},{label:`Ravencastle`,to:`/cidades/ravencastle`},{label:`Torre da Chuva Negra`,to:`/locais/torre-da-chuva-negra`},{label:`Caça às Bruxas`,to:`/historia/caca-bruxas`}]})],u),G=(e,t,n)=>({title:e,period:t,body:n}),K={humanos:{origin:`Populações diversas reunidas pela antiga Coroa Una; nenhuma origem cultural única é aceita.`,geography:`Presentes em todos os reinos, portos e fronteiras.`,government:`Monarquias, conselhos urbanos, fortalezas autônomas e guildas.`,religion:`Fé dos Sete Nomes, Brasa Comum, Chama sem Coroa e tradições regionais.`,architecture:`Varia de muralhas setentrionais a canais de Valoria e pontes marítimas.`,attire:[`Lã e couro no norte`,`Linho e capas enceradas nas planícies e portos`,`Insígnias políticas variáveis`],culture:`Fragmentada por reino, ofício, clima e memória de guerra.`,customs:[`Contratos escritos amplamente usados`,`Calendários locais coexistem com a contagem das eras`],festivals:[`Datas agrícolas, marítimas e memoriais variam por território`],cuisine:[`Grãos e raízes no centro`,`Peixes no sul`,`Conservas no norte`],military:[`Legiões, cavalaria, frotas e milícias locais`],internalConflicts:[`Memória da Coroa Una`,`Desigualdade entre campo e corte`,`Legado da Caça às Bruxas`],currentSituation:`Os reinos cooperam comercialmente enquanto disputas sucessórias e medo do retorno Kayler reabrem velhas divisões.`,rumors:[`Censos da perseguição esconderiam descendentes das três Casas`],narrativeImportance:`A diversidade humana impede que coroas, religiões ou guerras sejam tratadas como vontade de um povo inteiro.`,biographyTitle:`História dos povos humanos`,biography:[G(`Antes e durante a Coroa Una`,`Antes do ano 0`,`Comunidades com línguas e economias próprias foram reunidas por estradas, legiões e impostos.`),G(`Fragmentação`,`Cinco Eras`,`Guerras produziram reinos distintos. A descoberta pública da magia e a perseguição revelaram como instituições humanas podiam proteger ou apagar minorias.`),G(`Presente`,`1204 d.C.`,`Nenhum reino representa todos os humanos. A volta de Sirius testa leis, medos e alianças de formas diferentes.`)]},elfos:{origin:`Comunidades da Floresta Antiga anteriores aos calendários humanos.`,geography:`Sylvaris, Porto Verde e pequenos bosques ligados por memória ritual.`,government:`Círculos da Memória, assembleias de ofício e monarquia limitada.`,religion:`Caminho das Raízes e Memória da Primeira Raiz.`,architecture:`Plataformas, encaixes removíveis e materiais cultivados ou recolhidos sem dano permanente.`,attire:[`Fibras vegetais`,`Couro de animais encontrados mortos ou caçados sob manejo`,`Metais usados com parcimônia`],culture:`Longevidade exige instituições capazes de revisar juramentos antigos sem esquecer seu custo.`,customs:[`Associar nomes de mortos a jardins`,`Pedir consentimento territorial antes de grandes obras`],festivals:[`Vigília da Copa Silenciosa`,`Retorno das Folhas`],cuisine:[`Frutas, sementes, fungos e peixes de rio`],military:[`Sentinelas de margem`,`Arqueiros de plataforma`],internalConflicts:[`Isolamento contra responsabilidade continental`,`Ritmo lento de decisão`,`Sucessão de Elara`],currentSituation:`A floresta enfrenta pressões comerciais e o retorno de um pacto preservado por séculos.`,rumors:[`Alguns Círculos teriam recusado partes do pacto Kayler`],narrativeImportance:`Elfos ligam memória ecológica, sucessão de Elara e proteção histórica às três Casas.`,biographyTitle:`História élfica`,biography:[G(`Antes dos tratados`,`Antiguidade`,`Bosques e cidades-jardim já possuíam calendários quando humanos chegaram às margens.`),G(`Abertura controlada`,`Era da Magia`,`Tratados permitiram intercâmbio sem reconhecer a floresta como propriedade negociável.`),G(`Pacto e presente`,`Caça às Bruxas–1204 d.C.`,`Sylvaris protegeu rotas e provas. A chegada de Sirius obriga os elfos a discutir as consequências do silêncio.`)]},orcs:{origin:`Clãs e cidades de Vul’Gar, ligados por rotas de poço e memória da Cicatriz Vermelha.`,geography:`Terras áridas orientais, cidades de poço e fronteira de Ravenhold.`,government:`Conselhos de clã, assembleias temporárias e emissários com mandato enumerado.`,religion:`Credo da Cicatriz Vermelha e Brasa do Clã.`,architecture:`Pátios sombreados, torres de vento, muralhas baixas e cisternas comuns.`,attire:[`Tecidos leves`,`Couro endurecido`,`Marcas de serviço e faixas de clãs signatários`],culture:`Nome adulto, água e abrigo definem responsabilidade mais que sangue isolado.`,customs:[`Receber nome após serviço`,`Suspender vingança quando água é compartilhada`,`Adoção pública pela Brasa`],festivals:[`Cicatrizes Contadas`,`Última Fumaça`],cuisine:[`Pães achatados`,`Carnes secas`,`Frutas de poço e caldos salgados`],military:[`Infantaria de clã`,`Guardas de poço`,`Escoltas de comboio`],internalConflicts:[`Chefes de saque contra rotas civis`,`Clãs urbanos contra pastoris`,`Memória de contratos humanos abusivos`],currentSituation:`Kharza negocia com Ravenhold enquanto agentes de bandeira falsa tentam produzir guerra.`,rumors:[`Um contratante humano da Guerra dos Tronos ainda financia provocadores`],narrativeImportance:`Desmonta a versão de “horda única” e torna responsabilidade por guerra uma questão de contratos e escolhas.`,biographyTitle:`História dos clãs e cidades`,biography:[G(`Rotas de Brasa`,`Antes da Era da Magia`,`Poços e acampamentos formaram redes sem rei comum.`),G(`Contratos da Era das Coroas`,`Era das Coroas`,`Clãs combateram em lados diferentes, muitas vezes por intermediários humanos. Culpa coletiva apagou essa diversidade.`),G(`Fronteira presente`,`1204 d.C.`,`Emissários tentam construir tratados que nomeiem cada signatário e impeçam nova generalização.`)]},anoes:{origin:`Salões subterrâneos da cordilheira central, unidos por dependência de água, ar e rotas.`,geography:`Kar-Dûm e postos comerciais de superfície.`,government:`Nove Salões com regras distintas de sangue, ofício e eleição.`,religion:`Nove Ecos e Sete Golpes da Primeira Forja.`,architecture:`Pedra de compressão, ventilação redundante, pontes e registros gravados.`,attire:[`Tecidos resistentes à fuligem`,`Protetores auriculares e oculares de ofício`,`Insígnias de salão separadas de nomes de sangue`],culture:`Obra, medida e reparo constituem responsabilidade moral.`,customs:[`Adoção de ofício`,`Nomeação de ferramentas`,`Registro público de falhas`],festivals:[`Sete Metais`,`Oitavo Golpe, contestado`],cuisine:[`Fungos, peixes de caverna e queijos importados`],military:[`Guardiões de corredor`,`Engenheiros de evacuação`],internalConflicts:[`Sangue contra ofício`,`Tradição contra inovação`,`Dependência alimentar`],currentSituation:`Debates sobre lacres antigos aproximam engenharia, religião e disputa pelo Véu.`,rumors:[`Algumas placas antigas registram vibrações anteriores aos anões`],narrativeImportance:`Fornece a tecnologia que limita artefatos e uma tradição capaz de distinguir fenômeno material de magia.`,biographyTitle:`História dos salões`,biography:[G(`Salões independentes`,`Antiguidade`,`Comunidades cresceram ao redor de veios e águas, desenvolvendo regras próprias.`),G(`Confederação e abertura`,`Era da Magia`,`Dependência material criou os Nove Salões e tratados com a superfície.`),G(`Memória dos colapsos`,`Era atual`,`Os Túneis Vazios ainda orientam qualquer debate sobre Fraturas e expansão.`)]},gigantes:{origin:`Comunidades setentrionais cuja memória associa ancestralidade a vales e pilares naturais.`,geography:`Passos altos, geleiras e vales do extremo norte.`,government:`Assembleias de canto e guardiões temporários de passagem.`,religion:`Pilares Adormecidos.`,architecture:`Abrigos de grandes blocos, círculos de pedra e marcos que também armazenam cantos.`,attire:[`Peles e lã em camadas`,`Cordões minerais que identificam vales`],culture:`Parentesco pode ser territorial e abrigo cria obrigação temporária.`,customs:[`Recitar tratados no local que os testemunhou`,`Confirmar cada geração por duas comunidades`],festivals:[`Círculo do Degelo`,`Canto dos Passos Antigos`],cuisine:[`Carne curada`,`Raízes de altitude`,`Leite fermentado`],military:[`Guardiões de avalanche`,`Defesa comunitária, sem exército central`],internalConflicts:[`Migração provocada por degelo`,`Traduções humanas que distorcem parentesco`],currentSituation:`Mudanças no gelo ameaçam lugares onde tratados só podem ser integralmente recitados.`,rumors:[`O Grande Despertar seria cobrança política, não catástrofe física`],narrativeImportance:`Liga clima, memória territorial e legitimidade de Winterfeld.`,biographyTitle:`História das comunidades`,biography:[G(`Cantos de vale`,`Antiguidade`,`Genealogias e tratados foram vinculados a lugares, não a arquivos móveis.`),G(`Pacto com Winterfeld`,`Período pós-Queda`,`Gigantes aceitaram proteger passagens em troca de autonomia e abrigo recíproco.`),G(`Degelo`,`1204 d.C.`,`A transformação física dos lugares ameaça apagar ou reinterpretar obrigações antigas.`)]},dragoes:{origin:`Origem biológica não documentada; apenas três indivíduos são conhecidos.`,geography:`Vyrasul no norte, Alcarion em território próprio e Mhazir em habitat separado.`,government:`Não se aplica: dragões não constituem povo ou Estado.`,religion:`Não possuem culto organizado conhecido.`,architecture:`Não se aplica: nenhum assentamento construído por dragões foi autenticado.`,attire:[`Não se aplica; adornos descritos em lendas não aparecem nos registros naturais`],culture:`Não há evidência de cultura coletiva. Cada indivíduo demonstra memória e escolha próprias.`,customs:[`Nenhum costume coletivo autenticado`],festivals:[`Não se aplica: não há calendário coletivo conhecido`],cuisine:[`Dieta animal varia por habitat; não existe culinária`],military:[`Não integram exércitos por direito; associações políticas são projeções humanas`],internalConflicts:[`Não documentados`],currentSituation:`Três indivíduos conhecidos, nenhum ovo autenticado e nenhuma autorização canônica para ampliar a espécie.`,rumors:[`Avistamentos adicionais são classificados como erro, lenda ou criatura não identificada`],narrativeImportance:`Impede que raridade natural seja convertida em império, raça política ou recurso militar.`,biographyTitle:`Registro dos três indivíduos`,biography:[G(`Avistamentos separados`,`Eras históricas`,`Vyrasul, Alcarion e Mhazir surgem em documentos de regiões distintas sem prova de contato entre si.`),G(`Apropriação humana`,`Era das Coroas`,`Coroas e cultos tentaram transformar presença territorial em aliança ou divindade. Nenhuma alegação se sustenta.`),G(`Limite canônico`,`Era atual`,`O arquivo mantém exatamente três dragões conhecidos e trata todo novo relato como não confirmado.`)]}},q=[e({id:`humanos`,name:`Humanos de Avernor`,subtitle:`Muitos reinos, nenhuma essência única`,summary:`Povo majoritário e politicamente fragmentado, capaz de construir instrumentos arcanos, mas incapaz de produzir magia verdadeira sem sangue das três linhagens.`,description:`Os humanos descendem das populações reunidas pela antiga Coroa Una. A fragmentação criou calendários locais, sotaques, leis e interesses incompatíveis. Ferramentas rúnicas, engenharia e religião ampliam suas capacidades, mas não concedem magia: apenas descendentes Kayler, Nimbus ou Rivs nascem bruxos.`,category:`Povo mortal`,status:`Numeroso`,location:`Todo o continente`,truthStatus:`documented`,beliefs:[`Brasa Comum nos reinos centrais`,`Chama sem Coroa nas fortalezas rebeldes`,`Juramento do Horizonte nos portos`],abilities:[`Adaptação institucional`,`Engenharia e escrita disseminadas`,`Grandes redes agrícolas e comerciais`],limitations:[`Não possuem dom racial mágico`,`Divisões políticas recorrentes`,`Memória histórica vulnerável à propaganda`],curiosities:[`“Humano” descreve um povo, não uma cultura única.`],relations:[{label:`Culto da Brasa Comum`,to:`/religioes/culto-da-brasa-comum`},{label:`As Cinco Eras`,to:`/historia`}]}),e({id:`elfos`,name:`Elfos de Sylvaris`,subtitle:`A floresta também participa`,summary:`Povo longevo cuja memória coletiva, política e religião reconhecem a Floresta Antiga como agente vivo, nunca como propriedade.`,description:`Elfos percebem padrões de crescimento, água e comportamento animal com precisão cultivada por gerações. A Vontade da Floresta não é feitiço individual: é a soma de relações ecológicas, memórias rituais e respostas do território. A coroa depende dos Círculos da Memória e não pode ordenar exploração irrestrita.`,category:`Povo antigo`,status:`Protegido por Sylvaris`,location:`Floresta Antiga`,truthStatus:`documented`,beliefs:[`Caminho das Raízes`,`A memória exige reciprocidade`,`Nomes de mortos permanecem ligados a lugares cuidados`],abilities:[`Longevidade`,`Leitura ecológica refinada`,`Arco, manejo e memória ritual`],limitations:[`Não possuem magia verdadeira por natureza`,`Decisões coletivas podem ser lentas`,`Distância da floresta reduz referências sensoriais`],relations:[{label:`Sylvaris`,to:`/reinos/sylvaris`},{label:`Elara`,to:`/personagens/elara`}]}),e({id:`orcs`,name:`Orcs de Vul’Gar`,subtitle:`Clãs unidos pela Brasa`,summary:`Povo de cidades, clãs e rotas orientais que entende identidade como fogo compartilhado e responsabilidade recíproca.`,description:`A Brasa do Clã é um vínculo social mantido por lareiras comunais, testemunhos e obrigações. Não controla mentes nem produz magia. Clãs podem divergir, misturar-se ou expulsar chefes que quebram o abrigo comum. Vul’Gar designa uma região cultural; não uma horda ou vontade única.`,category:`Povo mortal`,status:`Confederações autônomas`,location:`Vul’Gar e fronteira oriental`,truthStatus:`documented`,beliefs:[`Brasa do Clã`,`O nome adulto deve ser confirmado por serviço`,`Água compartilhada suspende vinganças`],abilities:[`Resistência física`,`Logística em terras áridas`,`Diplomacia interclânica`],limitations:[`Não possuem magia verdadeira`,`Acordos dependem dos clãs signatários`,`Estereótipos humanos sabotam tratados`],relations:[{label:`Kharza Gron`,to:`/personagens/kharza-gron`},{label:`Facções de Avernor`,to:`/faccoes`}]}),e({id:`anoes`,name:`Anões de Kar-Dûm`,subtitle:`Escutar antes de romper a pedra`,summary:`Povo subterrâneo organizado por salões de sangue, ofício e responsabilidade material.`,description:`A Escuta da Pedra combina acústica, observação de fraturas e memória profissional. Estrangeiros a confundem com magia, mas nenhum anão conjura por herança racial. Parentesco de ofício pode ser tão vinculante quanto sangue, embora apenas o sangue determine algumas sucessões domésticas.`,category:`Povo antigo`,status:`Confederação soberana`,location:`Kar-Dûm`,truthStatus:`documented`,beliefs:[`Os Nove Ecos`,`Toda abertura cria uma dívida`,`Uma obra sem registro é uma obra sem responsável`],abilities:[`Engenharia subterrânea`,`Audição treinada para estruturas`,`Metalurgia e hidráulica`],limitations:[`Não possuem magia verdadeira`,`Superfície aberta desorienta alguns habitantes`,`Disputas entre sangue e ofício atrasam decisões`],relations:[{label:`Kar-Dûm`,to:`/reinos/kar-dum`},{label:`Os Nove Ecos`,to:`/religioes/nove-ecos`}]}),e({id:`gigantes`,name:`Gigantes das Montanhas`,subtitle:`A memória carregada pelo relevo`,summary:`Comunidades raras do norte que preservam tratados por cantos associados a vales, geleiras e passos.`,description:`A chamada Memória da Montanha é um sistema oral e espacial: cada trecho de um pacto é cantado no lugar que o testemunhou. Gigantes percebem vibrações de avalanche e mudança de gelo antes da maioria dos povos, uma adaptação natural transformada em tradição sagrada.`,category:`Povo antigo`,status:`Comunidades dispersas`,location:`Extremo norte`,truthStatus:`witnessed`,beliefs:[`Montanhas lembram consequências`,`Mover um marco sem testemunhas é roubar memória`,`Abrigo cria parentesco temporário`],abilities:[`Força e longevidade`,`Leitura de gelo e avalanche`,`Memória oral territorial`],limitations:[`Não possuem magia verdadeira`,`Baixa natalidade`,`Calor prolongado causa exaustão rápida`],relations:[{label:`Winterfeld`,to:`/reinos/winterfeld`},{label:`Vyrasul`,to:`/criaturas/vyrasul`}]}),e({id:`dragoes`,name:`Dragões conhecidos`,subtitle:`Instinto, território e memória`,summary:`Exatamente três criaturas naturais conhecidas: Vyrasul, Alcarion e Mhazir; não formam povo político, reino ou civilização.`,description:`Dragões acumulam memória instintiva de rotas, presas e ameaças. Sua inteligência permite escolha e reconhecimento, mas não linguagem estatal, culto organizado ou governo. Não há ovos autenticados nem evidência de outros indivíduos; ausência de prova não autoriza ampliar o número canônico.`,category:`Fauna lendária`,status:`Três indivíduos conhecidos`,location:`Habitats separados`,truthStatus:`documented`,abilities:[`Voo`,`Memória territorial longa`,`Adaptações naturais individuais`],limitations:[`Não produzem sociedade política`,`São vulneráveis durante recuperação de grandes esforços`,`Reprodução desconhecida`],relations:[{label:`Vyrasul`,to:`/criaturas/vyrasul`},{label:`Alcarion`,to:`/criaturas/alcarion`},{label:`Mhazir`,to:`/criaturas/mhazir`}]})].map(e=>({...e,...K[e.id]})),J=[e({id:`cancao-do-primeiro-ceu`,name:`A Canção do Primeiro Céu`,subtitle:`Sete nomes contra a Vastidão Silenciosa`,summary:`Mito compartilhado segundo o qual sete nomes romperam o Primeiro Céu e originaram pedra, mar, fogo, vento, vida, morte e memória.`,description:`Antes de terra, tempo, luz ou morte havia a Vastidão Silenciosa. Uma voz desconhecida pronunciou sete nomes; o sétimo fragmento permaneceu invisível no mundo como mana, o Eco do Primeiro Céu. A ruptura também criou o Véu. Povos discordam sobre a voz, sua intenção e a possibilidade de um oitavo fragmento; nenhuma versão é verdade absoluta.`,category:`Mito cosmogônico`,status:`Múltiplas versões`,truthStatus:`legendary`,events:[`Ruptura do Primeiro Céu`,`Nascimento dos sete fragmentos`,`Formação do Véu`],disputedClaims:[`Criação voluntária, guerra ou sacrifício`,`Existência de um oitavo fragmento`],relations:[{label:`O Véu`,to:`/cosmologia/o-veu`},{label:`A Primeira Tempestade`,to:`/mitologia/primeira-tempestade`}]}),e({id:`primeira-tempestade`,name:`A Primeira Tempestade`,subtitle:`Sete noites sob um céu violeta`,summary:`Todas as culturas preservam uma versão da tempestade em que raios não queimaram, águas brilharam e três mortais teriam sido marcados pela mana.`,description:`Durante sete noites o céu permaneceu violeta, ruínas surgiram e animais nasceram alterados. A tradição dos bruxos identifica três mortais marcados como ancestrais de Kayler, Nimbus e Rivs. Cronistas aceitam a convergência do fenômeno, mas não a genealogia literal nem uma explicação única.`,category:`Mito de origem`,status:`Núcleo convergente`,truthStatus:`disputed`,events:[`Céu violeta`,`Raios sem fogo`,`Águas luminosas`,`Marca dos três mortais`],relations:[{label:`Casa Kayler`,to:`/casas/kayler`},{label:`Doutrina das Três Correntes`,to:`/mitologia/doutrina-tres-correntes`}]}),e({id:`doutrina-tres-correntes`,name:`Doutrina das Três Correntes`,subtitle:`A responsabilidade dos sangues tocados`,summary:`Filosofia religiosa das três linhagens bruxas: Celeste para Kayler, Escarlate para Nimbus e Profunda para Rivs.`,description:`A Corrente Celeste reúne céu, liberdade, transformação e equilíbrio; a Escarlate, vontade, disciplina, proteção e domínio do medo; a Profunda, água, memória, cura e continuidade. Seu Juramento Arcano estabelece: “Nenhum sangue tocado pelo Primeiro Céu deverá sentar-se acima dos povos.” O juramento explica a recusa de Normus em aceitar uma coroa.`,category:`Filosofia dos bruxos`,status:`Fragmentada`,truthStatus:`documented`,beliefs:[`Poder de sangue não concede direito de governo`,`Mana é herança e responsabilidade`,`Mortos retornam ao Eco, não à posse dos vivos`],events:[`Iniciação diante de três recipientes`,`Vigília funerária sem trono`,`Renovação pública do Juramento Arcano`],relations:[{label:`Normus Kayler`,to:`/personagens/normus-kayler`},{label:`Era da Magia`,to:`/historia/era-magia`}]}),e({id:`metamorfose-do-eco`,name:`Metamorfose do Eco`,subtitle:`A forma animal que também transforma quem a assume`,summary:`Alegação contestada de que certos integrantes das três linhagens assumiriam uma ou duas formas animais ligadas à própria essência.`,description:`Cantos tardios descrevem transformação mediante treino e mana, com roupas e armas deixadas no ponto de partida, olhos violetas e marcas brancas. Nenhum protocolo verificável, corpo transformado ou testemunho contemporâneo autenticado sobreviveu. Permanência longa, instinto animal e dificuldade de retorno pertencem às versões folclóricas, não a uma capacidade confirmada. Relatos sobre uma forma de corvo de Sirius são classificados como rumor.`,category:`Tradição arcana contestada`,status:`Não confirmada`,truthStatus:`disputed`,knowledgeStatus:`rumor`,limitations:[`No máximo uma ou duas formas`,`Consumo crescente de mana`,`Risco de absorção de instintos`,`Retorno difícil após uso excessivo`],relations:[{label:`As três Casas`,to:`/casas`},{label:`Doutrina das Três Correntes`,to:`/mitologia/doutrina-tres-correntes`}]}),e({id:`credo-cicatriz-vermelha`,name:`Credo da Cicatriz Vermelha`,subtitle:`O céu ferido por Khar-Ul`,summary:`Mitologia orc sobre a ferida primordial da qual caíram sangue, dentes, lágrimas, cinzas e sopro.`,description:`Khar-Ul, o Primeiro Ferido, abre o céu. Maara-Ghesh guarda as brasas, Vokhar caça na fumaça e Zhur-Kaan testemunha juramentos. Nomes adultos são recebidos diante do fogo comunal; mortos são enviados ao Acampamento Além do Horizonte Vermelho. Regiões de poço valorizam Maara-Ghesh, enquanto guardiões de estrada invocam Zhur-Kaan.`,category:`Mitologia orc`,status:`Praticada`,truthStatus:`legendary`,events:[`Cerimônia do Nome de Brasa`,`Funeral da Última Fumaça`,`Festival das Cicatrizes Contadas`],relations:[{label:`Orcs de Vul’Gar`,to:`/povos/orcs`}]}),e({id:`memoria-primeira-raiz`,name:`Memória da Primeira Raiz`,subtitle:`O sonho de Ilyndra`,summary:`Tradição élfica em que uma raiz atravessa terra, água, sonhos, tempo e memória, ligando os mortos à Copa Silenciosa.`,description:`Ilyndra não cria o mundo; desperta-o de um sonho sem estação. Mortos tornam-se Folhas de Memória lembradas em jardins vivos. Guardiões discutem se a proteção concedida a Normus foi reciprocidade legítima ou risco imposto à floresta. O medalhão do pacto é valioso como testemunho, não como fonte de poder.`,category:`Mitologia élfica`,status:`Praticada`,truthStatus:`legendary`,events:[`Jardins memoriais`,`Casamento das Duas Sombras`,`Vigília da Copa Silenciosa`],relations:[{label:`Caminho das Raízes`,to:`/religioes/caminho-das-raizes`},{label:`Rainha Aelwen`,to:`/personagens/rainha-aelwen`}]}),e({id:`sete-golpes-primeira-forja`,name:`Os Sete Golpes da Primeira Forja`,subtitle:`A obra de Dorh-Mael`,summary:`Mito anão em que sete golpes originam montanhas, metais, fogo, águas subterrâneas, vida, memória e destino.`,description:`Para os anões, trabalho é oração, qualidade é honra e obras preservam parte de quem as fez. Sacerdotes-ferreiros não concedem magia: verificam medidas, nomes e responsabilidade. Reformistas defendem que o oitavo golpe é cada inovação; tradicionalistas temem que essa leitura banalize a origem.`,category:`Mitologia anã`,status:`Praticada`,truthStatus:`legendary`,events:[`Batida dos Sete Metais`,`Funeral da Ferramenta Nomeada`,`Festival do Oitavo Golpe`],relations:[{label:`Kar-Dûm`,to:`/reinos/kar-dum`},{label:`Os Nove Ecos`,to:`/religioes/nove-ecos`}]}),e({id:`pilares-adormecidos`,name:`Os Pilares Adormecidos`,subtitle:`As montanhas como ancestrais`,summary:`Crença dos gigantes de que montanhas são ancestrais adormecidos e avalanches podem ser movimentos de memória.`,description:`Círculos de pedra marcam locais onde cantos devem ser retomados por cada geração. A profecia do Grande Despertar possui duas leituras: destruição física das montanhas ou momento em que todos os tratados esquecidos cobrarão cumprimento. A segunda leitura orienta a diplomacia com Winterfeld.`,category:`Crença dos gigantes`,status:`Tradição oral`,truthStatus:`legendary`,events:[`Canto dos Passos Antigos`,`Círculo do Degelo`,`Vigília do Grande Despertar`],relations:[{label:`Gigantes das Montanhas`,to:`/povos/gigantes`},{label:`Fim dos Tempos`,to:`/fim-dos-tempos`}]})].map(e=>({...e,...A[e.id]})),Y=p([e({id:`o-veu`,name:`O Véu`,subtitle:`A fronteira que não é um muro`,summary:`Limite instável entre vivos, mortos, sonhos, memórias, espaços incompletos e outros mundos.`,description:`O Véu surgiu, segundo a Canção do Primeiro Céu, quando a realidade foi rompida em sete fragmentos. Estudos verificam apenas seus efeitos: perda de continuidade, repetição de lugares e memórias que se comportam como matéria. Não é uma estrada nem uma fonte segura de poder.`,category:`Estrutura cosmológica`,status:`Observado indiretamente`,truthStatus:`witnessed`,relations:[{label:`Fraturas do Véu`,to:`/portais`},{label:`Canção do Primeiro Céu`,to:`/mitologia/cancao-do-primeiro-ceu`}]}),e({id:`eco-primeiro-ceu`,name:`O Eco do Primeiro Céu`,subtitle:`O nome religioso da mana`,summary:`Interpretação de que a mana é o fragmento invisível da memória primordial.`,description:`Bruxos usam o termo para lembrar que a magia não lhes pertence. Naturalistas registram mana por seus efeitos, mas não confirmam sua origem mitológica. A hereditariedade permanece exclusiva a Kayler, Nimbus e Rivs.`,category:`Princípio arcano`,status:`Interpretação tradicional`,truthStatus:`disputed`,relations:[{label:`Doutrina das Três Correntes`,to:`/mitologia/doutrina-tres-correntes`}]})],s),X=p([e({id:`fraturas-do-veu`,name:`Fraturas do Véu`,subtitle:`Passagens que cobram passagem`,summary:`Portais raros, perigosos e instáveis, criados por rupturas extremas; jamais servem como transporte cotidiano.`,description:`Podem assumir forma de arco, água, sombra, espelho, runa, tempestade, caminho ou floresta deslocada. Alguns só permitem entrada; outros alteram tempo ou memória. Surgem após magia extrema, batalhas, sacrifícios, morte de criaturas antigas, juramentos quebrados ou alinhamentos celestes.`,category:`Fenômeno limiar`,status:`Raro`,truthStatus:`witnessed`,limitations:[`Destino incerto`,`Preço físico ou memorial`,`Instabilidade temporal`,`Possível passagem de mão única`],relations:[{label:`O Véu`,to:`/cosmologia/o-veu`},{label:`Vigias do Limiar`,to:`/faccoes/vigias-do-limiar`}]}),e({id:`espelho-de-sal`,name:`Espelho de Sal`,subtitle:`A fratura que devolve outra idade`,summary:`Lâmina de água imóvel no Deserto de Zharak que reflete o observador anos mais velho ou mais jovem.`,description:`Duas pessoas atravessaram e retornaram com lembranças incompatíveis. O local é cercado por marcos, não por muralhas: aproximar-se sem escriba e testemunha é proibido pelas cidades de poço.`,category:`Fratura registrada`,status:`Selada por vigilância`,location:`Deserto de Zharak`,truthStatus:`witnessed`,relations:[{label:`Cartógrafos do Impossível`,to:`/faccoes/cartografos-do-impossivel`}]}),e({id:`caminho-das-arvores-ausentes`,name:`Caminho das Árvores Ausentes`,subtitle:`Uma trilha que não pertence à estação`,summary:`Passagem de Sylvaris cuja vegetação muda para espécies nunca catalogadas em Avernor.`,description:`O caminho aparece apenas depois de certas tempestades violetas. Guardiões recolhem folhas e memórias antes de fechar o acesso. Alguns acreditam que leva a Elyra; outros, a uma versão futura da própria floresta.`,category:`Fratura registrada`,status:`Intermitente`,location:`Floresta Antiga`,truthStatus:`disputed`,relations:[{label:`Elyra`,to:`/outros-mundos/elyra`},{label:`Sylvaris`,to:`/reinos/sylvaris`}]})],a),Z=p([e({id:`elyra`,name:`Elyra`,subtitle:`Mundo da Luz Imóvel`,summary:`Lugar sem noite observável, onde sombras permanecem mesmo após seus objetos se moverem.`,description:`Fragmentos retornados de Elyra perdem cor quando expostos ao luar de Avernor. Peregrinos descrevem cidades claras sem habitantes visíveis. Não se sabe se a luz preserva, aprisiona ou apenas registra.`,category:`Outro mundo`,status:`Acesso não controlado`,truthStatus:`witnessed`,curiosities:[`Relatos divergem sobre a passagem do tempo.`]}),e({id:`morvath`,name:`Morvath`,subtitle:`Terra das Cinzas Vivas`,summary:`Planície onde cinzas se agrupam ao redor de nomes falados e preservam calor sem fogo.`,description:`A cinza reage a memória e luto. Amostras em Avernor tornam-se inertes depois de sete dias, mas podem apagar uma palavra de documentos próximos. A Corte de Cinza busca rotas permanentes para o lugar.`,category:`Outro mundo`,status:`Hostil`,truthStatus:`witnessed`,relations:[{label:`Corte de Cinza`,to:`/faccoes/corte-de-cinza`}]}),e({id:`naelor`,name:`Naelor`,subtitle:`Mar sem Margens`,summary:`Oceano sem costa conhecida onde estrelas aparecem sob a quilha.`,description:`Retornados trazem sal que não se dissolve e medo de céu aberto. Cartógrafos não concordam se Naelor é um mundo, uma camada do Mar das Estrelas ou o interior de uma Fratura.`,category:`Outro mundo`,status:`Não cartografado`,truthStatus:`disputed`,relations:[{label:`Mar das Estrelas`,to:`/locais/mar-das-estrelas`}]}),e({id:`varakh`,name:`Varakh`,subtitle:`Mundo da Guerra Inacabada`,summary:`Campos e fortificações que repetem os preparativos de uma batalha cujo inimigo nunca chega.`,description:`Armas encontradas ali carregam marcas de povos desconhecidos, mas se desfazem ao cruzar o Véu. Alguns Juramentados afirmam ter servido décadas em Varakh durante uma única noite de Avernor.`,category:`Outro mundo`,status:`Temporalmente instável`,truthStatus:`witnessed`,relations:[{label:`Juramentados`,to:`/retornados/juramentados`}]}),e({id:`fenda-sem-nome`,name:`A Fenda sem Nome`,subtitle:`O espaço que recusa descrição`,summary:`Ausência entre mundos relacionada a Nar-Khalion e a registros que apagam o próprio título.`,description:`Toda descrição prolongada perde palavras diferentes a cada cópia. O Arquivo conserva apenas características negativas: não é escuridão, vazio ou morte. A relação com o Prisioneiro permanece fora do conteúdo público.`,category:`Anomalia cosmológica`,status:`Restrito`,truthStatus:`redacted`,spoilerLevel:`public`})],t),re=[[`vazios`,`Vazios`,`Corpos retornados com respostas automáticas e quase nenhuma memória pessoal.`,`Identidade residual`],[`lembrantes`,`Lembrantes`,`Retornados que preservam uma única memória e organizam toda ação ao redor dela.`,`Memória fixa`],[`juramentados`,`Juramentados`,`Mortos mantidos por promessa incompleta; podem cessar quando o juramento é cumprido.`,`Vínculo de juramento`],[`coroados-de-cinza`,`Coroados de Cinza`,`Retornados capazes de impor fragmentos de lembrança sobre grupos próximos.`,`Risco coletivo`],[`desvelados`,`Desvelados`,`Pessoas que retornaram por uma Fratura e percebem limites invisíveis do Véu.`,`Percepção limiar`],[`ecoantes`,`Ecoantes`,`Presenças sem corpo estável que repetem vozes, gestos e caminhos.`,`Eco memorial`],[`devorados`,`Devorados`,`Retornados cuja identidade foi substituída por algo atraído durante a ruptura.`,`Ameaça extrema`]],ie={vazios:[{label:`Pastores dos Mortos`,to:`/faccoes/pastores-dos-mortos`}],lembrantes:[{label:`Coletores de Nomes`,to:`/faccoes/coletores-de-nomes`}],juramentados:[{label:`Varakh`,to:`/outros-mundos/varakh`}],"coroados-de-cinza":[{label:`Corte de Cinza`,to:`/faccoes/corte-de-cinza`}],desvelados:[{label:`Fraturas do Véu`,to:`/portais/fraturas-do-veu`}],ecoantes:[{label:`Escuta Ancestral`,to:`/necromancia/escuta-ancestral`}],devorados:[{label:`O Prisioneiro sem Nome`,to:`/nar-khalion/prisioneiro-sem-nome`}]},ae=p([...re.map(([t,n,r,i])=>e({id:t,name:n,subtitle:i,summary:r,description:`${r} A maioria dos mortos não retorna. Destruir o corpo nem sempre liberta a presença, e cada caso exige investigação de nome, memória, motivo e juramento.`,category:i,status:`Categoria documentada`,truthStatus:`witnessed`,limitations:[`Memórias degradam`,`Identidade pode fragmentar`,`Libertação depende da causa do retorno`],relations:ie[t]})),e({id:`marcha-dos-sem-nome`,name:`A Marcha dos Sem-Nome`,subtitle:`Quando as famílias apagaram nomes para deter os mortos`,summary:`Evento em que centenas de Retornados caminharam para o oeste até ouvirem seus nomes verdadeiros.`,description:`Autoridades removeram nomes de lápides por medo, agravando a marcha. Pastores dos Mortos e parentes restauraram os registros em praça pública. O episódio criou o direito funerário segundo o qual apagar um nome é agressão à família e risco coletivo.`,category:`Evento histórico`,status:`Encerrado`,period:`Ano 742`,truthStatus:`documented`,relations:[{label:`Pastores dos Mortos`,to:`/faccoes/pastores-dos-mortos`}]})],o),oe=p([e({id:`necromancia`,name:`Necromancia`,subtitle:`Manipular não é restaurar`,summary:`Práticas que interferem em corpos, ecos, memória, juramentos, fragmentos de alma e energia do Véu.`,description:`Toda necromancia cobra perda de memória, vida, identidade ou estabilidade do Véu. Comunicação ancestral consentida não é automaticamente necromancia: a distinção está em convocar ou prender, ouvir ou forçar, recordar ou fabricar.`,category:`Prática proibida`,status:`Criminalizada na maioria dos reinos`,truthStatus:`documented`,limitations:[`Perda de memória`,`Redução da vida`,`Contaminação`,`Atração de entidades`,`Fragmentação da identidade`,`Enfraquecimento do Véu`]}),e({id:`costura-de-eco`,name:`Costura de Eco`,subtitle:`Uma memória presa a um corpo`,summary:`Técnica que ancora uma lembrança alheia em matéria morta, confundindo testemunho com identidade.`,description:`Usada para interrogar restos, ela produz respostas contaminadas pelas expectativas do praticante. Tribunais rejeitam qualquer prova obtida por Costura de Eco.`,category:`Técnica necromântica`,status:`Proibida`,truthStatus:`documented`,relations:[{label:`Necromancia`,to:`/necromancia/necromancia`}]}),e({id:`escuta-ancestral`,name:`Escuta Ancestral`,subtitle:`Memória ritual sem coerção`,summary:`Práticas culturais de ouvir histórias preservadas por fogo, pedra, canto ou objetos sem aprisionar mortos.`,description:`A Escuta reconhece que uma comunidade interpreta memória; não afirma trazer uma pessoa integral de volta. Orcs, anões, elfos e gigantes mantêm protocolos distintos. Coerção, sacrifício e impedimento de partida transformam o rito em abuso.`,category:`Prática memorial`,status:`Permitida com limites`,truthStatus:`documented`,relations:[{label:`Anões de Kar-Dûm`,to:`/povos/anoes`}]})],i),se=p([[`segunda-ruptura`,`Segunda Ruptura`,`O Véu voltará a partir-se onde as cinco Relíquias se encontrarem.`],[`noite-sem-estrelas`,`Noite sem Estrelas`,`Os céus perderão orientação antes da abertura da Porta sem Fechadura.`],[`ultimo-inverno`,`Último Inverno`,`Winterfeld lê o fim como frio que nenhum abrigo consegue compartilhar.`],[`despertar-dos-pilares`,`Despertar dos Pilares`,`Gigantes esperam que montanhas cobrem todos os tratados esquecidos.`],[`grande-marcha`,`Grande Marcha`,`Pastores temem que todos os mortos privados de nome retornem juntos.`],[`queda-primeira-raiz`,`Queda da Primeira Raiz`,`Sylvaris debate se a queda é morte da floresta ou fim da memória comum.`],[`ultimo-golpe`,`Último Golpe`,`Anões preveem a obra final que selará ou romperá o mundo.`],[`sete-silencios`,`Sete Silêncios`,`Cada povo perderá uma linguagem essencial antes do silêncio completo.`],[`mundo-esquecera-nome`,`O Dia em que o Mundo Esquecerá seu Nome`,`A interpretação mais temida: realidade sem memória de si mesma.`]].map(([t,n,r])=>e({id:t,name:n,subtitle:`Uma leitura do fim`,summary:r,description:r,category:`Escatologia`,status:`Interpretação`,truthStatus:`prophetic`,relations:[{label:`Profecias centrais`,to:`/profecias`}]})),f),Q=p([e({id:`nar-khalion`,name:`Nar-Khalion`,subtitle:`O Cárcere além do Sétimo Céu`,summary:`Prisão entre o mundo físico, o Véu, a Fenda sem Nome e um espaço fora do tempo; nenhuma fuga interna é conhecida.`,description:`Nenhuma porta abre por dentro. Teletransporte retorna à cela, morte não liberta, mapas falham, nomes perdem poder e cada tentativa fortalece os selos. Nem dragões ou Relíquias permitem fuga interna. O único risco aceito é uma abertura deliberada pelo lado de fora.`,category:`Prisão cosmológica`,status:`Localização inacessível`,truthStatus:`redacted`,limitations:[`Morte não liberta`,`Memórias de fuga são apagadas`,`Mapas falham`,`Tentativas fortalecem os selos`],relations:[{label:`A Fenda sem Nome`,to:`/outros-mundos/fenda-sem-nome`},{label:`Profecia das Cinco Relíquias`,to:`/profecias/cinco-reliquias`}]}),e({id:`prisioneiro-sem-nome`,name:`O Prisioneiro sem Nome`,subtitle:`Registro público incompleto`,summary:`Uma presença imortal em Nar-Khalion, capaz de alcançar sonhos e conhecer futuros possíveis.`,description:`O Arquivo confirma apenas que a entidade deseja a reunião das Relíquias e pode contaminar interpretações proféticas. Motivo, origem e identidade foram suprimidos do registro público. Tratá-la como simples voz confiável ou vilão absoluto serve aos objetivos dela.`,category:`Entidade restrita`,status:`Contido`,truthStatus:`redacted`,spoilerLevel:`public`,relations:[{label:`Nar-Khalion`,to:`/nar-khalion/nar-khalion`},{label:`Profecias centrais`,to:`/profecias`}]})],te),ce=p([[`ultimo-violeta`,`Último Violeta`,`“Quando o último violeta fechar os olhos, a tempestade escolherá entre nome e céu.”`,`Pode indicar Sirius, o fim das linhagens ou apenas um crepúsculo raro.`],[`coroa-vazia`,`Coroa Vazia`,`“Uma coroa sem cabeça reunirá reis que não sabem ajoelhar.”`,`Usada tanto por monarquistas da Coroa Una quanto por republicanos.`],[`arvore-sem-sombra`,`Árvore sem Sombra`,`“A raiz esquecerá o chão quando nenhuma folha produzir sombra.”`,`Sylvaris lê como crise de memória; madeireiros, como autorização de expansão.`],[`tres-feras-aladas`,`Três Feras Aladas`,`“Três asas contarão uma ausência; só uma pousará diante do gelo.”`,`Frequentemente associada aos três dragões, embora o texto não os nomeie.`],[`ultima-forja`,`Última Forja`,`“O martelo derradeiro não fará arma, mas decidirá o que pode permanecer inteiro.”`,`Kar-Dûm disputa se a profecia exige selar ou abrir as profundezas.`],[`cicatriz-aberta`,`Cicatriz Aberta`,`“A ferida do céu voltará a sangrar por mãos que chamam medo de prudência.”`,`Clãs orcs a relacionam a juramentos quebrados e à perseguição.`],[`mar-acima`,`Mar Acima`,`“Quando o mar navegar sobre as estrelas, a margem pedirá um nome.”`,`Eldemar teme inundação; os Cartógrafos veem uma passagem para Naelor.`],[`chama-sem-coroa`,`Chama sem Coroa`,`“A chama sem coroa guardará a criança que reis decidiram esquecer.”`,`A tradição Bellatrix aplica o verso a Sirius, mas cópias anteriores falam em crianças no plural.`],[`sete-silencios-profecia`,`Sete Silêncios`,`“Sete nomes foram ditos; sete silêncios podem desfazê-los.”`,`Não se sabe se são mortes, línguas perdidas, votos ou Celestiais.`],[`cinco-reliquias`,`Profecia das Cinco Relíquias`,`“Cinco testemunhos buscarão uma porta que nenhum escriba consegue nomear.”`,`O verso sobrevive em cópias incompletas. Não se sabe se “testemunhos” significa pessoas, objetos, povos ou decisões, nem qual porta é mencionada.`],[`porta-sem-fechadura`,`Porta sem Fechadura`,`“A porta que não se fecha só abre para quem deixou o próprio nome do outro lado.”`,`Pode ser uma Fratura, Nar-Khalion ou metáfora para o retorno dos mortos.`]].map(([t,n,r,i])=>e({id:t,name:n,subtitle:`Texto de interpretação disputada`,summary:r,description:`${i} Existem traduções adulteradas e versões promovidas por facções; nenhuma leitura é confirmada pelo Arquivo.`,category:`Profecia central`,status:`Em circulação`,truthStatus:`prophetic`,quotes:[r.replace(/[“”]/g,``)],disputedClaims:[i],relations:[{label:`Fim dos Tempos`,to:`/fim-dos-tempos`}]})),d),le=p([e({id:`medalhao-ultimo-sussurro`,name:`Medalhão do Último Sussurro`,subtitle:`A morte paga com memória`,summary:`Relíquia capaz de alcançar o último eco de um morto ao custo de lembranças pessoais de quem pergunta.`,description:`Cada uso apaga uma memória ligada emocionalmente à pergunta. Respostas vêm como sensação e fragmento, nunca como testemunho completo. Necromantes procuram o objeto por confundir acesso com autoridade.`,category:`Relíquia do Véu Partido`,status:`Perdida`,truthStatus:`witnessed`,limitations:[`Cobra memória pessoal`,`Respostas fragmentárias`,`Atrai Retornados`],relations:[{label:`Necromancia`,to:`/necromancia/necromancia`}]}),e({id:`fulgarion`,name:`Fulgarion`,subtitle:`A Espada dos Sete Trovões`,summary:`Espada de Normus e Sirius, condutora do legado Kayler e uma das Cinco Relíquias.`,description:`Suas manifestações conhecidas recebem os nomes Despertar, Passo Celeste, Corrente Partida, Céu Descendente, Tempestade Interior, Julgamento Violeta e Porta da Tempestade. Cada etapa exige maior controle, mana e responsabilidade; a lâmina não cria o dom em um portador sem sangue Kayler. O efeito integral da sétima manifestação não faz parte do registro público.`,category:`Relíquia do Véu Partido`,status:`Com Sirius`,origin:`Normus Kayler`,truthStatus:`documented`,abilities:[`Despertar`,`Passo Celeste`,`Corrente Partida`,`Céu Descendente`,`Tempestade Interior`,`Julgamento Violeta`,`Porta da Tempestade — efeito integral não publicado`],limitations:[`Sobrecarga nervosa`,`Dependência do dom Kayler`,`Limite final não registrado publicamente`],relations:[{label:`Sirius Kayler`,to:`/personagens/sirius-kayler`},{label:`Espada da Trovoada`,to:`/artefatos/espada-da-trovoada`}]}),e({id:`aelysar`,name:`Aelysar`,subtitle:`O Arco da Primeira Raiz`,summary:`Arco destinado a Elara quando assumir o trono de Sylvaris, com seis flechas ligadas a responsabilidades da coroa.`,description:`As flechas são Raiz, Lua Verde, Memória, Caminho, Copa Silenciosa e Último Ramo. Cada uma é única e retorna apenas quando a obrigação representada foi cumprida. Aelysar não concede magia de sangue; responde a pactos rúnicos, ao reino e à portadora reconhecida.`,category:`Relíquia do Véu Partido`,status:`Guardada até a sucessão`,origin:`Sylvaris`,truthStatus:`redacted`,abilities:[`Flecha da Raiz`,`Lua Verde`,`Memória`,`Caminho`,`Copa Silenciosa`,`Último Ramo`],relations:[{label:`Elara`,to:`/personagens/elara`},{label:`Sucessão de Sylvaris`,to:`/sucessoes/sylvaris`}]}),e({id:`varkhael-seryn`,name:`Varkhael e Seryn`,subtitle:`As Lâminas da Dor Incendiária`,summary:`Espadas gêmeas: Varkhael alimenta-se da fúria; Seryn, da dor; ambas podem queimar nomes e memórias.`,description:`As lâminas tornam emoções em calor, mas não distinguem justiça de obsessão. Usadas juntas, podem apagar o nome de uma pessoa dos registros e das lembranças próximas. Separadas, procuram portadores em extremos emocionais.`,category:`Relíquia do Véu Partido`,status:`Separadas`,truthStatus:`legendary`,limitations:[`Amplificam emoção`,`Queimam memória`,`O uso conjunto ameaça identidade coletiva`],relations:[{label:`Corte de Cinza`,to:`/faccoes/corte-de-cinza`}]}),e({id:`ishara`,name:`Ishara`,subtitle:`O Véu da Última Cura`,summary:`Tecido capaz de curar ao transferir dor, reduzir vida ou armazenar sofrimento no próprio material.`,description:`Ishara não elimina preço: decide quem o carrega e quando. Dores absorvidas permanecem como bordados escuros e podem ser libertadas de uma vez. Curadores discutem se usar o objeto sem consentimento é salvação ou violência.`,category:`Relíquia do Véu Partido`,status:`Localização desconhecida`,truthStatus:`witnessed`,limitations:[`Transfere dor`,`Pode reduzir vida`,`Acumula sofrimento`,`Exige consentimento ético`],relations:[{label:`Profecia das Cinco Relíquias`,to:`/profecias/cinco-reliquias`}]})].map(e=>({...e,...P[e.id]})),l),$=[[`aureon`,`Aureon`,`Lei`,`solvaris`,`Solvaris`,`Lança do Julgamento`,`A lei sem misericórdia torna-se apenas uma máquina de culpa.`],[`myriel`,`Myriel`,`Memória`,`elythra`,`Elythra`,`Lança dos Nomes`,`O que deve ser lembrado quando toda memória também pode ferir?`],[`kaeloran`,`Kaeloran`,`Guerra`,`vharun`,`Vharun`,`Lança da Última Batalha`,`O fim de uma guerra pode exigir que alguém se recuse a vencê-la.`],[`selenya`,`Selenya`,`Misericórdia`,`ishmeriel`,`Ishmeriel`,`Lança da Misericórdia`,`Misericórdia imposta pode negar justiça às vítimas.`],[`tharos`,`Tharos`,`Tempestade`,`raekhar`,`Raekhar`,`Lança dos Sete Céus`,`A tempestade transforma e destrói sem reconhecer títulos.`],[`nerathiel`,`Nerathiel`,`Morte`,`mor-aeth`,`Mor-Aeth`,`Lança do Último Fôlego`,`A morte encerra posse, mas não apaga consequência.`],[`oryndar`,`Oryndar`,`Limiar`,`veyrion`,`Veyrion`,`Lança do Limiar`,`Toda fronteira protege algo e aprisiona outra coisa.`]],ue=p($.map(([t,n,r,i,a,o,s])=>e({id:t,name:n,subtitle:`Celestial de ${r}`,summary:`Figura associada a ${r.toLowerCase()} em textos anteriores à Coroa Una; sua natureza — pessoa, povo, função ou metáfora — permanece incerta.`,description:`${s} Relatos não provam divindade nem presença física. Igrejas e facções usam o nome de ${n} para interpretações conflitantes.`,category:`Celestial`,status:`Natureza incerta`,truthStatus:`legendary`,relations:[{label:`${a} — ${o}`,to:`/lancas/${i}`}]})),ee),de=p($.map(([t,n,r,i,a,o])=>e({id:i,name:a,subtitle:o,summary:`Arma atribuída a ${n}, ligada ao domínio de ${r.toLowerCase()}.`,description:`Nenhuma lança foi autenticada em sua forma completa. Fragmentos e cópias podem ser artefatos antigos, propaganda ou objetos tocados pelo Véu. O Arquivo separa a tradição da alegação material.`,category:`Lança celestial`,status:`Não autenticada`,truthStatus:`legendary`,relations:[{label:n,to:`/celestiais/${t}`}]})),r),fe={"vigias-do-limiar":{description:`Os Vigias nasceram de patrulhas que encontravam lugares onde distância, memória ou clima deixavam de obedecer ao padrão local. Mantêm postos desmontáveis, medem alterações e evacuam civis antes de permitir pesquisa. A ordem não concorda sobre Sirius: parte o vê como testemunha indispensável; outra parte teme que a presença de um artefato condutor contamine qualquer observação.`,foundation:`Fundados depois dos primeiros registros públicos de Fraturas.`,government:`Círculos regionais submetidos a um protocolo comum de quarentena.`,culture:`Precisão e prudência; um relatório deve registrar também o que não foi medido.`,methods:[`Isolamento proporcional`,`Marcos de distância`,`Entrevistas repetidas para detectar perda de memória`],moralLimits:[`Não encarcerar uma pessoa apenas por afinidade arcana`],alliesPolitical:[`Cartógrafos do Impossível`,`Pastores dos Mortos`],rivalsPolitical:[`Abertos`,`Seladores radicais`],importantCharacters:[`Lys Arven`],currentSituation:`Divididos sobre acompanhar ou conter a jornada de Sirius.`,rumors:[`Um posto inteiro desapareceu sem deixar alteração no terreno`],narrativeImportance:`Oferecem método público para investigar o Véu sem confirmar cada rumor sobrenatural.`},"cartografos-do-impossivel":{description:`Cartógrafos registram locais que mudam escala, sequência ou lembrança. Seus mapas exibem margens de erro, versões incompatíveis e rotas que só existem sob condições descritas. A organização rejeita mapas perfeitos porque precisão fingida já matou expedições. Seu interesse em Fulgarion limita-se a medições materiais e meteorológicas e não concede direito sobre Sirius.`,foundation:`Criados por pilotos de Eldemar e engenheiros de Kar-Dûm após duas expedições contraditórias.`,government:`Arquivo colegiado; autoria e contestação permanecem visíveis em cada mapa.`,culture:`Incerteza declarada vale mais que autoridade.`,methods:[`Cartografia comparada`,`Marcos redundantes`,`Diários separados por observador`],moralLimits:[`Não apagar versões divergentes`],alliesPolitical:[`Vigias do Limiar`,`Pilotos de Eldemar`],rivalsPolitical:[`Seladores que confiscam mapas`,`Coroas que exigem fronteiras falsas`],importantCharacters:[`Orel Daan`],currentSituation:`Solicitam depoimento de Sirius, que ainda não aceitou revelar todas as manifestações.`,rumors:[`O Arquivo das Margens contém um mapa de Nar-Khalion sem origem autenticada`],narrativeImportance:`Permitem representar outros mundos e Fraturas sem transformar hipótese em geografia absoluta.`},"peregrinos-sem-sombra":{description:`Os Peregrinos acreditam que a identidade atual é sombra de uma existência perdida em Elyra. Viajam em grupos pequenos e apagam títulos ao ingressar. Parte procura retorno voluntário; outra pressiona membros a abandonar família e nome, conflito que tornou a facção objeto de vigilância.`,foundation:`Formados após relatos convergentes de Retornados ligados a Elyra.`,government:`Guias itinerantes reconhecidos por consenso local.`,religion:`Interpretação radical dos relatos de Elyra.`,culture:`Desapego de nomes, propriedade mínima e canto coletivo.`,methods:[`Peregrinação`,`Coleta de sonhos`,`Busca de Fraturas associadas à luz`],moralLimits:[`A ala moderada exige partida voluntária; a ala do Sol Vazio contesta esse limite`],alliesPolitical:[`Abertos em células específicas`],rivalsPolitical:[`Pastores dos Mortos`,`Vigias do Limiar`],currentSituation:`A visão de Sirius como “luz aprisionada” divide os que desejam ouvi-lo e os que querem convertê-lo em sinal.`,rumors:[`A Voz de Elyra seria uma Retornada, não uma profetisa`],narrativeImportance:`Mostra como saudade e perda podem formar fé, comunidade e coerção.`},seladores:{description:`Os Seladores tratam toda Fratura como falha estrutural que deve ser fechada. Seus melhores técnicos salvaram comunidades, mas o segredo de métodos e a disposição de sacrificar pessoas do outro lado geraram dissidência. A proposta de usar Fulgarion como selo ignora que a espada responde ao corpo e ao consentimento de Sirius.`,foundation:`Surgiram em Kar-Dûm depois que um lacre instável contaminou três galerias.`,government:`Conselho técnico cujos nomes não são divulgados por alegada segurança.`,culture:`Dever material, sigilo e preferência por encerramento definitivo.`,methods:[`Lacres de pedra e metal`,`Evacuação`,`Confisco de artefatos`],moralLimits:[`Oficialmente preservam vidas locais; não há consenso sobre pessoas presas além do Véu`],alliesPolitical:[`Alguns salões de Kar-Dûm`],rivalsPolitical:[`Abertos`,`Cartógrafos do Impossível`],currentSituation:`Preparando um projeto para Fulgarion sem autorização de Sirius.`,rumors:[`O conselho já utilizou memória de Retornados como material de selo`],narrativeImportance:`Transforma proteção legítima em debate sobre consentimento e custo invisível.`},abertos:{description:`Os Abertos defendem que coroas e ordens não devem monopolizar passagens entre mundos. Publicam fragmentos de pesquisa e mantêm células autônomas, o que reduz censura e facilita infiltração. Moderados exigem rotas testadas; radicais consideram todo fechamento uma forma de tirania.`,foundation:`Rede criada por estudiosos expulsos de arquivos reais.`,government:`Células com porta-vozes temporários.`,culture:`Conhecimento distribuído e suspeita de autoridade central.`,methods:[`Publicação clandestina`,`Abertura experimental`,`Abrigo de pesquisadores`],moralLimits:[`Moderados exigem consentimento local; radicais rejeitam veto territorial`],alliesPolitical:[`Cartógrafos dissidentes`,`Peregrinos em algumas rotas`],rivalsPolitical:[`Seladores`,`Vigias conservadores`],currentSituation:`Tentam convencer Sirius de que revelar Fulgarion evitará monopólio, sem responder quem suportará os testes.`,rumors:[`Sereth Vaul recebe instruções em sonhos cuja origem desconhece`],narrativeImportance:`Representa a diferença entre democratizar conhecimento e distribuir risco sem responsabilidade.`},"filhos-setimo-silencio":{description:`A facção apaga textos, nomes e testemunhas ligados ao sétimo fragmento do Primeiro Céu. Não possui doutrina pública estável: células discordam se o perigo é uma palavra, uma linhagem ou uma forma de memória. Essa ambiguidade permite justificar violência contra qualquer pessoa marcada como “voz”.`,foundation:`Origem não registrada; primeiras ações autenticadas ocorreram após a Caça às Bruxas.`,government:`Células sem líder identificável e reconhecimento por frases incompletas.`,religion:`Leitura apocalíptica do Sétimo Silêncio.`,culture:`Anonimato, supressão documental e obediência fragmentada.`,methods:[`Roubo de arquivos`,`Destruição de inscrições`,`Ameaça a tradutores`],moralLimits:[`Nenhum limite confiável documentado`],alliesPolitical:[`Nenhum aliado público`],rivalsPolitical:[`Coletores de Nomes`,`Cartógrafos`,`Sirius`],currentSituation:`Rastreiam documentos Kayler e profecias que usam a palavra “chave”.`,rumors:[`A ausência de líder pode esconder coordenação pelo Prisioneiro; hipótese arcana`],narrativeImportance:`Materializa o risco de combater uma profecia apagando pessoas reais.`},"coletores-de-nomes":{description:`Coletores preservam nomes verdadeiros, vínculos e últimas vontades para ajudar Retornados a reconstruir identidade. A prática produziu um arquivo incomparável e um mercado clandestino: parte dos curadores negocia nomes como moeda, contra os estatutos da ordem. O interesse no nome ritual de Sirius expõe essa contradição.`,foundation:`Instituídos após Retornados sem memória causarem disputas de herança em Valoria.`,government:`Curadorias locais auditadas pela Casa dos Registros.`,culture:`Nome como vínculo, prova e responsabilidade.`,methods:[`Entrevista genealógica`,`Comparação de assinaturas`,`Custódia de últimas vontades`],moralLimits:[`Estatuto proíbe vender nomes; violações são documentadas`],alliesPolitical:[`Pastores dos Mortos`,`Arquivos civis`],rivalsPolitical:[`Filhos do Sétimo Silêncio`,`Mercadores internos corruptos`],currentSituation:`Oferecem pistas sobre Namídia em troca de informação que Sirius não deseja entregar.`,rumors:[`Maev Or mantém um livro privado fora da auditoria`],narrativeImportance:`Liga identidade, genealogia e necromancia ao problema político de quem controla arquivos.`},"ordem-ultima-brasa":{description:`A Ordem mantém cozinhas, depósitos e rotas de abrigo durante crises do Véu. Sua autoridade depende de serviço verificável, não de milagre. Protege Sirius como perseguido e rejeita a transformação dele em santo, arma ou justificativa para abandonar pessoas menos célebres.`,foundation:`Coalizão de templos-cozinha formada depois de uma Fratura interromper estradas de grão.`,government:`Casas locais ligadas por auditorias de estoque.`,religion:`Brasa Comum e Vigília da Última Brasa.`,culture:`Cuidado material, contabilidade pública e neutralidade de abrigo.`,methods:[`Cozinhas móveis`,`Rotas de evacuação`,`Mediação de estoque`],moralLimits:[`Abrigo não depende de lealdade religiosa`],alliesPolitical:[`Brasa Comum`,`Vigias do Limiar`],rivalsPolitical:[`Corte de Cinza`,`Nobres que confiscam doações`],currentSituation:`Expande depósitos porque rumores de fim dos tempos já provocam retenção de grãos.`,rumors:[`Uma casa da ordem esconde um Retornado de identidade real`],narrativeImportance:`Mantém consequências civis no centro de conflitos sobrenaturais.`},"pastores-dos-mortos":{description:`Pastores identificam cadáveres, Retornados e juramentos interrompidos antes de recorrer à força. Não praticam necromancia para comandar mortos. Usam genealogias, marcas de ofício e testemunhos para devolver nomes, sabendo que identidade restaurada não garante intenção pacífica.`,foundation:`Criados por guardiões de necrópole durante surtos de falsificação de herança.`,government:`Casas de estrada coordenadas por um conselho funerário.`,religion:`Práticas variadas; o código exige neutralidade entre crenças sobre a morte.`,culture:`Nomear, ouvir, verificar e encerrar obrigações.`,methods:[`Exame de sepultura`,`Pesquisa genealógica`,`Mediação de juramentos`],moralLimits:[`Não prender um Retornado sem avaliar memória e risco`],alliesPolitical:[`Coletores de Nomes`,`Ordem da Última Brasa`],rivalsPolitical:[`Necromantes coercivos`,`Corte de Cinza`],currentSituation:`Pedem escolta de Sirius numa rota onde descargas parecem atrair Retornados.`,rumors:[`Tovan Mirel teria morrido uma vez; relato não confirmado`],narrativeImportance:`Separa cuidado funerário, Retornados e necromancia, evitando tratar todo morto como inimigo.`},"corte-de-cinza":{description:`A Corte reúne aristocratas, arquivistas e agentes que desejam abrir Morvath para possuir memórias queimadas. Promete governo sem esquecimento, mas seu método depende de capturar lembranças e reescrever legitimidade. A Regente Velada é título, não identidade confirmada.`,foundation:`Primeiras células rastreadas a famílias comprometidas com a Cinza Branca.`,government:`Círculos de patronos subordinados à Regente Velada.`,religion:`Doutrina própria que trata memória como propriedade soberana.`,culture:`Hierarquia, chantagem documental e cerimônias de cinza.`,methods:[`Infiltração de arquivos`,`Compra de relíquias`,`Manipulação de sucessões`],moralLimits:[`Nenhum limite público confiável`],alliesPolitical:[`Agentes não identificados no Senado de Estandartes`],rivalsPolitical:[`Pastores dos Mortos`,`Coletores de Nomes honestos`,`Sirius`],currentSituation:`Procura apresentar Sirius como chave voluntária de um plano cujas consequências oculta.`,rumors:[`A Regente pode ser mais de uma pessoa usando o mesmo título`],narrativeImportance:`Conecta a perseguição histórica a uma ameaça que domina pela memória em vez de apenas pela força.`}},pe=[[`vigias-do-limiar`,`Vigias do Limiar`,`Uma chave diante de uma linha partida`,`Lys Arven`,`Observar, isolar e registrar Fraturas antes que coroas as convertam em armas.`,`postos móveis junto a anomalias`,`Consideram Sirius um risco que merece escolha e vigilância, não prisão.`],[`cartografos-do-impossivel`,`Cartógrafos do Impossível`,`Compasso com agulha quebrada`,`Mestre Orel Daan`,`Mapear lugares que alteram distância, tempo ou memória sem fingir precisão inexistente.`,`Arquivo das Margens, Eldemar`,`Querem que Sirius descreva a Porta da Tempestade de Fulgarion.`],[`peregrinos-sem-sombra`,`Peregrinos sem Sombra`,`Sandálias sob um sol vazio`,`A Voz de Elyra`,`Retornar a Elyra e abandonar identidades consideradas sombras impostas.`,`acampamentos itinerantes`,`Veem os olhos violetas de Sirius como sinal de uma luz aprisionada.`],[`seladores`,`Seladores`,`Sete pontos costurados em círculo`,`Conselho sem rosto`,`Fechar toda Fratura, mesmo que pessoas ou memórias permaneçam do outro lado.`,`criptas técnicas de Kar-Dûm`,`Pretendem usar Fulgarion como selo, com ou sem consentimento.`],[`abertos`,`Abertos`,`Porta sem parede`,`Sereth Vaul`,`Abrir passagens controladas e distribuir o conhecimento além das coroas.`,`células urbanas`,`Desejam convencer Sirius de que isolamento apenas preserva privilégios.`],[`filhos-setimo-silencio`,`Filhos do Sétimo Silêncio`,`Boca coberta por sete linhas`,`Nenhum líder público`,`Impedir que o sétimo nome seja novamente pronunciado, apagando textos e testemunhas.`,`desconhecida`,`Acreditam que o sangue Kayler é uma palavra viva que precisa calar.`],[`coletores-de-nomes`,`Coletores de Nomes`,`Livro preso por corrente`,`Curadora Maev Or`,`Preservar nomes verdadeiros para libertar Retornados, embora parte da ordem os negocie.`,`Casa dos Registros, Valória`,`Oferecem informações sobre Namídia em troca do nome ritual de Sirius.`],[`ordem-ultima-brasa`,`Ordem da Última Brasa`,`Brasa em duas mãos`,`Irmã Hilda Venn`,`Manter abrigo, comida e rotas civis durante eventos do Véu.`,`templos-cozinha de Winterfeld e Valoria`,`Protegem Sirius como pessoa perseguida, mas recusam culto ao seu poder.`],[`pastores-dos-mortos`,`Pastores dos Mortos`,`Cajado diante de lápide nomeada`,`Tovan Mirel`,`Identificar Retornados, restaurar nomes e resolver juramentos antes de usar força.`,`necrópoles e estradas antigas`,`Pedem a Sirius proteção em travessias, sem exigir que pratique necromancia.`],[`corte-de-cinza`,`Corte de Cinza`,`Coroa dissolvida em fuligem`,`A Regente Velada`,`Abrir Morvath e governar pela posse de memórias queimadas.`,`salões ocultos de Ravenhold`,`Deseja transformar Sirius na chave pública de um plano que não controla.`]].map(([t,n,r,i,a,o,s])=>e({id:t,name:n,subtitle:r,summary:a,description:`${a} A liderança registrada é ${i}; a estrutura combina um núcleo dirigente e agentes locais, mas disputas sobre meios e autoridade atravessam cada grupo.`,category:`Facção transregional`,status:`Ativa`,symbol:r,leadership:i,location:o,truthStatus:`documented`,objectives:[a],methods:[`Informação e recrutamento`,`Alianças circunstanciais`,`Operações coerentes com a própria ideologia`],disputedClaims:[`Relação com Sirius: ${s}`],relations:[{label:`Sirius Kayler`,to:`/personagens/sirius-kayler`}],...fe[t]}));export{S as C,D as S,ne as T,R as _,ce as a,k as b,Q as c,ae as d,Z as f,U as g,W as h,le as i,oe as l,q as m,ue as n,Y as o,J as p,de as r,se as s,pe as t,X as u,F as v,x as w,O as x,M as y};